def md5sum(filename):
    if not os.path.exists(filename):
        raise Exception(f"File {filename} not exists to check md5sum")
    md5, err, status = run_command("md5sum {}".format(filename))
    if status:
        raise Exception("Could not determine checksum, error: {}".format(err))
    return md5.split(" ")[0]

