# and keep <file>.mdcap-sha256 next to it; uploads without it are not hashed
CHECKSUM_HEADERS = {'X-Mdcap-Checksum': 'sha256'}

def format_file_size(size_bytes):
    """Format a byte count like '512 B', '1.50 MB' or '1.50 GB'."""
    size = float(size_bytes)
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024:
            return f"{int(size)} B" if unit == "B" else f"{size:.2f} {unit}"
        size /= 1024
    return f"{size:.2f} TB"

class _ProgressReader(io.BufferedReader):
    """File reader that reports the number of bytes read to a callback."""
    def __init__(self, path, on_read):
        super().__init__(io.FileIO(path, 'rb'))
        self._on_read = on_read

    def read(self, size=-1):
        chunk = super().read(size)
        self._on_read(len(chunk))
        return chunk

# upload a file to robin artifactory
async def upload_file(url, filename, ret_response_as=False, progress=False, headers=None):
    try:
        #headers = {'Authorization': os.environ.get('MDCAP_CDN_TOKEN', '')}
        bar = None
        sent = [0]
        total = os.path.getsize(filename)

        def track(nbytes):
            sent[0] += nbytes
            if bar:
                bar.update(nbytes)

        if progress:
            bar_ctx = click.progressbar(length=total, show_pos=False, file=sys.stderr,
                                        label=f"Uploading {os.path.basename(filename)}",
                                        item_show_func=lambda _: f"{format_file_size(sent[0])} / {format_file_size(total)}")
        else:
            bar_ctx = contextlib.nullcontext()
        with bar_ctx as bar, _ProgressReader(filename, track) as fh:
            async with aiohttp.ClientSession(connector=aiohttp.TCPConnector(ssl=False)) as session:
                async with session.put(url, data={"filename": fh}, headers=headers) as response:
                    response.raise_for_status()
                    #print("File Upload Complete")
                    #print("Uploaded file to : {}".format(url))
                    if ret_response_as == "text":
                        return await response.text()
                    elif ret_response_as == "binary":
                        return await response.read()
                    else:
                        return True
    except Exception as e:
        print(f"Could not upload at {url} due to {e}")
        return False

# delete a file from robin artifactory
async def delete_file(url, filename):
    try:
        #headers = {'Authorization': os.environ.get('MDCAP_CDN_TOKEN', '')}
        with open(filename, 'rb') as fh:
            print("Delete file: {}".format(filename))
            async with aiohttp.ClientSession(connector=aiohttp.TCPConnector(ssl=False)) as session:
                async with session.delete(url, data={"filename": fh}) as response:
                    response.raise_for_status()
                    print("File Delete Complete")
                    return True
    except Exception as e:
        print(f"Could not upload at {url} due to {e}")
        return False

