def elem_format(elem, keys=[], transform_fn=None):
    if type(elem) == type([]):
        for e in elem:
            yield from elem_format(e, keys, transform_fn=transform_fn)
    else:
        elem.update(elem.pop('metadata', {}))
        elem.update(elem.pop('status', {}))
        if transform_fn:
            transform_fn(elem)
        if keys:
            yield {key:elem[key] for key in keys}
        else:
            yield elem

@click.group(cls=ClickAliasedGroup)
def cli():
    global sc
    sc = ServerContext()

def run_command(cmd, cwd=None):
    # Make sure everything passed in is a string
    proc = subprocess.Popen(split(cmd), stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd)
    _out, _err = proc.communicate()
    out = _out.decode('utf-8') if _out else ''
    err = _err.decode('utf-8') if _err else ''
    status = proc.returncode
    return out, err, status


def read_csv_file(filepath, columndelimiter=',', rowdelimiter='\n'):
    if os.path.isfile(filepath):
        records = []
        with open(filepath, encoding='utf-8') as filepath:
            try:
                csvreader = csv.reader(filepath, delimiter=columndelimiter, quotechar=rowdelimiter)
                col_names = []
                for line in csvreader:
                    if not col_names:
                        for col in line:
                            col_names.append(col)
                    else:
                        col_index = 0
                        entry = {}
                        for col in line:
                            if "." in col_names[col_index]:
                                tokens = col_names[col_index].split(".")
                                tmp = entry
                                lasttoken = None
                                for token in tokens:
                                    if lasttoken:
                                        tmp = tmp[lasttoken]
                                    if token not in tmp:
                                        tmp[token] = {}
                                    lasttoken = token
                                tmp[lasttoken] = col
                            else:
                                entry[col_names[col_index]] = col
                            col_index+=1
                        records.append(entry)
            except Exception:
                raise Exception("File {} is not a properly formatted JSON and thus cannot be converted.".format(filepath))
        return records
    raise Exception("Path {} is not a file.".format(filepath))

def read_json_file(filepath):
    if os.path.isfile(filepath):
        with open(filepath) as json_file:
            try:
                return json.load(json_file)
            except Exception:
                raise Exception("File {} is not a properly formatted JSON and thus cannot be converted.".format(filepath))
    else:
        raise Exception("Path {} is not a file.".format(filepath))


def read_yaml_file(filepath):
    if os.path.isfile(filepath):
        with open(filepath) as yaml_file:
            try:
                return yaml.safe_load(yaml_file)
            except Exception:
                raise Exception("File {} is not a properly formatted YAML and thus cannot be converted.".format(filepath))
    else:
        raise Exception("Path {} is not a file.".format(filepath))

def timestamp_to_human_readable(timestamp, date=True, year=True):
    if not timestamp:
        return "-"
    timestamp = int(timestamp)
    if date and year:
        return datetime.fromtimestamp(timestamp).strftime("%d %b %Y %H:%M:%S")
    elif date:
        return datetime.fromtimestamp(timestamp).strftime("%d %b %H:%M:%S")
    else:
        return datetime.fromtimestamp(timestamp).strftime("%H:%M:%S")

def process_schedules(schedules, obj):
        result = []
        weekdays = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
        frequencies = ['hourly', 'daily', 'weekly', 'monthly']
        for frequency in frequencies:
            if schedules.get(frequency, {}).get('enabled', False):
                msg = ""
                time_converted = time.strftime('%H:%M', time.strptime("{}:{}".format(schedules[frequency].get('hour', 0), schedules[frequency].get('minute', 1)), '%H:%M'))
                if frequency == "hourly":
                    msg = "Every hour at minute {},".format(schedules[frequency]['minute'])
                elif frequency == "daily":
                    msg = "Every day at {},".format(time_converted)
                elif frequency == "weekly":
                    msg = "Every week on {} at {},".format(weekdays[schedules[frequency]['weekday'] - 1], time_converted)
                elif frequency == "monthly":
                    monthday = schedules[frequency]['monthday']
                    msg = "Every month on the {} at {},".format("{}{}".format(monthday, "tsnrhtdd"[(monthday // 10 % 10 != 1) * (monthday  % 10 < 4) * monthday % 10::4]), time_converted)
                else:
                    raise Exception("Invalid Frequency specified.")
                retain = schedules[frequency]['retain']
                msg = msg + " retaining {} {}{}".format(retain, obj, '' if retain == 1 else 's')
                result.append(msg)
        return result

def mkdir_p(path):
    try:
        os.makedirs(path)
    except OSError as exc:
        if exc.errno == errno.EEXIST and os.path.isdir(path):
            pass
        else:
            exc.message = 'Failed to create dir ' + path
            raise exc

def bmp_url_to_ks_url(config_url):
    # read <config_url>/kickstart/main.ks
    res = requests.head(config_url + "/kickstart/main.local.ks", verify=False)
    if res.ok:
        return res.url
    else:
        # if not present check manifest.local.yaml and get the spec.kickstart.main.ks, thats the file
        res = requests.get(config_url + "/manifest.local.yaml", verify=False)
        if res.ok:
            md = yaml.safe_load(res.content)
        try:
            ks_url = md['spec']['kickstart']['main.ks']
            resp = requests.head(ks_url, verify=False)
            if resp.ok:
                return resp.url
            else:
                return None
        except:
            raise Exception(f"spec.kickstart.main.ks missing in mainfest.yaml in bmp")

def ks_url_to_bmp_url(config_url):
    if config_url:
        res = requests.head(os.path.dirname(os.path.dirname(config_url)) + "/manifest.yaml")
        if res.ok:
            return res.url
        else:
            return None
    else:
        raise Exception(f"illegal config_url: {config_url}") 

