def handle_fn_elements(etype, fname, fnDir):
    managed_elements = ["VM","BM","ROBINCLUSTER","NETWORK_FUNCTION"]
    testDir = os.path.join(fnDir, "test")
    os.system(f"mkdir {testDir}")
    elem_config = None

    for ele in etype:
        if ele in managed_elements:
            config = gen_element(ele)
            if elem_config==None:
                elem_config = config
            config_file_name = "config" + str(ele) + ".json"
            config_file = os.path.join(fnDir,"test/{}".format(config_file_name))
            with open(config_file, 'w+', encoding='utf-8') as f:
                json.dump(config, f, ensure_ascii=False, indent=4)
        else:
            print(f"{ele} is an unmanaged element not adding config for that element")

    config_file = os.path.join(fnDir,"test/config.json")
    config_file_updated = os.path.join(fnDir,"test/configupdated.json")
    mdcap_config_file = os.path.join(fnDir,"test/hosts.ini")
    mdcap_configfull_file = os.path.join(fnDir,"test/mdcap-batch.conf.full")
    os.system(f"touch {config_file_updated} && touch {mdcap_config_file} && touch {mdcap_configfull_file}")
    if elem_config is not None:
        with open(config_file, 'w+', encoding='utf-8') as f:
            json.dump(elem_config, f, ensure_ascii=False, indent=4)
    
    envs = {"sample":"sample"}
    env_file = os.path.join(fnDir,"test/config.env")
    with open(env_file, 'w+', encoding='utf-8') as f:
        json.dump(envs, f, ensure_ascii=False, indent=4)
    
