def generate_binary_local(lang, fname, fnDir, runfn=False, env=None):

    #fnDir = os.path.join(os.environ.get("devdir"),fname)
    
    #setup env
    try:
       
        cwd = os.getcwd()
        os.chdir(fnDir)
        env_file=fnDir + "/env_file"
        with open(env_file,'w+') as f:
            for var, var_value in env.items():
                if var == 'UPDATE_PAYLOAD':
                    f.write(f"export {str(var)}='{str(var_value)}'\n")
                else:
                    f.write(f'export {str(var)}="{str(var_value)}"\n')
        if lang=="python":
           
            if not os.path.isfile("main.py"):
                raise Exception("main.py not present")
            if not os.path.isfile("Pipfile"):
                raise Exception("Pipfile is not present")
            
            lang_version = None
            Pipfile = os.path.join(fnDir,"Pipfile")
            with open(Pipfile) as f:
                for line in f:
                    if "python_version" in line:
                        version = float(".".join(line.split("=")[1].strip().replace('"', '').split('.', 2)[:2]))
                        print(f"Language Version : {version}")
            
           
            run_os_cmd("pipenv install", "Error failed to setup environment", dir=fnDir)      
            
            '''
            if version<3.0:        
                run_os_cmd("pipenv install pyinstaller~=3.6", "Error failed to install pyinstaller")
                virtualenv_path_bytes = subprocess.check_output("pipenv --venv", shell=True)
                virtualenv_path = virtualenv_path_bytes.decode('utf-8').split("\n")[0]
                os.chdir(virtualenv_path)
                #cmd = "mkdir -p include/python2.7 && touch include/python2.7/pyconfig-64.h" 
                if not os.path.isdir('local'):
                    cmd = "mkdir local && cp -R include local"
                    run_os_cmd(cmd, "Internal Error")
                os.chdir(fnDir)
            else:
                run_os_cmd("pipenv install pyinstaller", "Error failed to install pyinstaller", dir=fnDir)
            '''

            outputDir = fnDir + "/binary/release"
            if not os.path.isdir(outputDir):
                os.system(f"mkdir -p {outputDir}")
            cmd = f"pyinstaller --name {fname} --onefile --distpat {outputDir} --windowed main.py"
           
            run_os_cmd(cmd, "Failed to generate binary")

            
            #staticx_cmd = f"staticx -l /lib64/ld-linux-x86-64.so.2 -l /lib64/libpthread.so.0 binary/release/output binary/release/{fname}"
            #run_os_cmd(staticx_cmd, "Failed to statically link the binary with gcc")
            
        elif lang=="rust":
            cmd = "HOME=/opt/app-root/src cargo build"
            #os.system(cmd)
            run_os_cmd(cmd, "Failed to build the code")
            binary_path = fnDir + f"/target/debug/{fname}"
            release_path = fnDir + f"/binary/release/{fname}"
            release_cmd = f"cp {binary_path} {release_path}"
            #os.system(release_cmd)
            run_os_cmd(release_cmd, "Failed to transfer files to binary/release")
        
        elif lang=="golang":
            if not os.path.isfile("main/main.go"):
                raise Exception("main.go not present")

            mainDir = os.path.join(fnDir,"main")
            cmd = f"cd {mainDir} && go mod tidy && go get && go build"
            #os.system(cmd)
            run_os_cmd(cmd, "Failed to build the code")
            if not os.path.isdir(fnDir + "/binary/release"):
                os.system(f"mkdir {fnDir}/binary/release")
            binary_dir = fnDir + f"/binary/release/{fname}"
            binary_path = fnDir + "/main/main"
            os.system(f"cp {binary_path} {binary_dir}")
        
        print("---- Binary Generation complete ----")

        if runfn:
            print('---- Script Output ----')
            binary_path = fnDir + f"/binary/release/{fname}"
            
            if lang == "rust":
                cmd = f"HOME=/opt/app-root/src . ./env_file && {binary_path}"
            else:
                cmd = f". ./env_file && {binary_path}"
            #os.system(cmd)
            run_os_cmd(cmd, "Failed to run the binary")
        os.chdir(cwd)
        
    except Exception as ex:
        print(f"Error:- {ex}")
    finally:
        if env_file and os.path.isfile(env_file):
            os.system(f"rm {env_file}")
        hostfile = f"/root/hosts-{fname}.ini"
        conffile = f"/root/mdcap-batch-{fname}.conf.full"
        if os.path.isfile(hostfile):
            os.system(f"rm {hostfile}")
        if os.path.isfile(conffile):
            os.system(f"rm {conffile}")
        
        

def run_os_cmd(cmd, ex, dir=None):
    cwd = None
    if dir:
        cwd = os.getcwd()
        os.chdir(dir)
    status = os.system(cmd)
    if dir:
        os.chdir(cwd)
    if status != 0:
        raise Exception(ex)

# Helper function to get min/max values from a range specifier.
# range_value should be in the format <min>:<max>
def min_max_from_range(range_value, min_name=None, max_name=None):
    min_value = None
    max_value = None
    if range_value:
        split_values = range_value.split(":")
        try:
            min_value = int(split_values[0])
        except ValueError:
            raise Exception("Min value specified is not an integer.")
        if len(split_values) == 2:
            try:
                max_value = int(split_values[1])
            except ValueError:
                raise Exception("Max value specified is not an integer.")

            if min_value > max_value:
                raise Exception(f"Min value cannot be higher than Max value {min_value}, {max_value}.")

            if min_name and max_name:
                min_value = f"{min_name}={min_value}"
                max_value = f"{max_name}={max_value}"
        else:
            min_value = None

    return min_value, max_value

def transform_element(element):
    """Updates element keys/values as required for better CLI output"""

    # update lock key if present
    transform_lock_info(element)

def transform_lock_info(data, lock_key='lock'):
    """Helper function to change lock value to user readable text"""

    _status_shared = "shared lock(s)"
    _status_exclusive = "exclusive lock"
    _status_none = "no lock"

    if lock_key in data:
        if data[lock_key] > 0:
            data[lock_key] = str(data[lock_key]) + " " + _status_shared
        elif data[lock_key] < 0:
            data[lock_key] = _status_exclusive
        else:
            data[lock_key] = _status_none

    # Format lock_source for display — engines locks marked distinctly
    if 'lock_source' in data:
        src = data['lock_source']
        data['lock_source'] = 'engine' if src == 'batch' else src

def get_vmaas_vm_create_data(name, vmtype, image, flavor, networks, kwargs, vmpool=False):
    _networks = []
    for _net in networks:
        _networks += _net.split(',')
    data = {
        "metadata": {"name": name, "description": name},
        "spec": {
            "vmtype": vmtype,
            "networks": _networks,
            "image": {'elem_name': image, 'kind': "IMAGE"},
            "flavor": {'elem_name': flavor, 'kind': "FLAVOR"},
            "developer_options": {},
            "connectors": {'ssh': {'sshhost': "fillin", 'username': "root", 'password': "<<fillin-from-cloudconfig>>"}}
        }
    }

    uid = kwargs.get('uid')
    if uid and not re.match(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', uid):
        raise Exception(f"Invalid UID format: {uid}. Must be a valid UUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)")
    if uid:
        data['metadata']['uid'] = uid

    if kwargs.get('element_version'):
        data['metadata']['version'] = kwargs['element_version']

    user_sshkey = get_user_home_sshkey(passed_pub_file=kwargs.get('user_ssh_pubfile'))
    if not user_sshkey and not kwargs.get('ssh_keys'):
        raise Exception("Specify atleast one ssh-key name from IAM list or run ssh-keygen")
    if user_sshkey:
        kwargs['user_sshkey'] = user_sshkey

    labels = {}
    for item in kwargs.get('labels', []):
        _arr = item.split(':')
        labels[_arr[0]] = _arr[1]

    if labels:
        data['metadata']['labels'] = labels

    if kwargs.get('dryrun', 'none') not in ["client", "none"]:
        if not data['metadata'].get('labels'):
            data['metadata']['labels'] = {}
        data['metadata']['labels']['dryrun'] = kwargs['dryrun']
        data['spec']['dryrun'] = kwargs['dryrun']

    if kwargs.get('enable_netadmin') or kwargs.get('debug'):
        data['spec']['enable_netadmin'] = True

    if kwargs.get('cloudconfig'):
        data['spec']['cloudconfig'] = [{'elem_name': x, 'kind': "CLOUDCONFIG"} for x in kwargs['cloudconfig']]
    if kwargs.get('portgroup'):
        data['spec']['portgroup'] = {'elem_name': kwargs['portgroup'], 'kind': "PORTGROUP"}
    if kwargs.get('securitygroup'):
        data['spec']['securitygroup'] = [{'elem_name': x, 'kind': "SECURITYGROUP"} for x in kwargs['securitygroup']]
    if kwargs.get('isos'):
        data['spec']['isos'] = [{'elem_name': x, 'kind': "IMAGE"} for x in kwargs['isos']]
    if kwargs.get('user_volumes'):
        data['spec']['user_volumes'] = [{'elem_name': x, 'kind': "VOLUME"} for x in kwargs['user_volumes']]
    if kwargs.get('ssh_keys'):
        data['spec']['ssh_keys'] = [{'name': x} for x in kwargs['ssh_keys']]

    static_ips_dict = {}
    for sip_str in kwargs.get('static_ips', []):
        if '=' in sip_str:
            netname, static_ips = sip_str.split('=')
        else:
            static_ips = sip_str
            netname = _networks[0]
        static_ips_dict[netname] = static_ips

    if static_ips_dict:
        data['spec']['static_ips'] = static_ips_dict

    if kwargs.get('colocate_all_vms') is not None:
        data['spec']['colocate_all_vms'] = kwargs['colocate_all_vms']

    _individual_flavor_opts = ['flavor_storage_class', 'flavor_disks_size', 'flavor_cpu', 'flavor_memory',
                               'flavor_volumemode', 'flavor_accessmode', 'flavor_cores', 'flavor_sockets', 'flavor_threads']
    if kwargs.get('flavor_override'):
        if any(kwargs.get(k) is not None for k in _individual_flavor_opts):
            raise Exception('--flavor-override cannot be used together with other --flavor-* or --flavor-storage-class options.')
        try:
            with open(kwargs['flavor_override']) as f:
                flavor_config = json.load(f)
        except ValueError:
            raise Exception('Invalid --flavor-override file. Ensure it contains valid JSON.')
        if 'flavor_config' not in flavor_config:
            raise Exception('Invalid --flavor-override file. The JSON must contain a top-level "flavor_config" key. Use --flavor-override for a full flavor_config override, or use the individual --flavor-* options instead.')
        data['spec']['flavor_overrides'] = {'flavor_config': flavor_config['flavor_config']}
    else:
        flavor_overrides = {}
        if kwargs.get('flavor_storage_class'):
            flavor_overrides['storage_class'] = kwargs['flavor_storage_class']
        if kwargs.get('flavor_disks_size'):
            try:
                flavor_overrides['disks'] = json.loads(kwargs['flavor_disks_size'])
            except ValueError:
                raise Exception('Invalid --flavor-disks-size value. Ensure the format matches: \'{"root": "100Gi", "data1": "10Gi"}\'')
        resources_override = {}
        if kwargs.get('flavor_cpu'):
            try:
                cpu = json.loads(kwargs['flavor_cpu'])
            except ValueError:
                raise Exception('Invalid --flavor-cpu value. Ensure the format matches: \'{"limit": "8", "request": "4"}\'')
            if 'limit' in cpu:
                resources_override.setdefault('limits', {})['cpu'] = cpu['limit']
            if 'request' in cpu:
                resources_override.setdefault('requests', {})['cpu'] = cpu['request']
        if kwargs.get('flavor_memory'):
            try:
                mem = json.loads(kwargs['flavor_memory'])
            except ValueError:
                raise Exception('Invalid --flavor-memory value. Ensure the format matches: \'{"limit": "16Gi", "request": "16Gi"}\'')
            if 'limit' in mem:
                resources_override.setdefault('limits', {})['memory'] = mem['limit']
            if 'request' in mem:
                resources_override.setdefault('requests', {})['memory'] = mem['request']
        if resources_override:
            flavor_overrides['resources'] = resources_override
        for key in ['flavor_volumemode', 'flavor_accessmode', 'flavor_cores', 'flavor_sockets', 'flavor_threads']:
            if kwargs.get(key) is not None:
                flavor_overrides[key] = kwargs[key]
        if flavor_overrides:
            data['spec']['flavor_overrides'] = flavor_overrides

    optional_keys = [
        "count", "dhcp", "masquerade", "namespace",
        "skip_workflow", "skip_ping_check", "disable_vnc", "version",
        "hostname", "domain", "node_selector",
        "robinrpool", "user_sshkey", "skip_cloudinit_networking",
        "target_node", "cluster", "group","anti_affinity_tag", "starting_ordinal",
        "compute_storage_affinity", "hook_sidecar_configmap",
        "http_auth_username", "http_auth_password",
        "eviction_strategy", "preserve_hostname", "prefer_fqdn_over_hostname"
    ]
    for key in optional_keys:
        if kwargs.get(key):
            data['spec'][key] = kwargs[key]
    if kwargs.get('enable_eth_naming'):
        data['spec']['set_interface_names'] = True

    vmpool_keys = ["replicas", "hpa_min_replicas", "hpa_max_replicas", "hpa_cpu_util_pct"]
    if vmpool:
        for key in vmpool_keys:
            if kwargs.get(key):
                data['spec'][key] = kwargs[key]

    developer_options = [
        "delay_after_ping", "genplan", "allocate_dev_cluster", "skip_tenant", "skip_workflow", "skip_robin_app",
        "import_timeout", "pvc_timeout", "ping_timeout"
    ]
    if kwargs.get('debug') is not None:
        data['spec']['developer_options']['debug'] = kwargs['debug']
    for key in developer_options:
        if kwargs.get(key):
            data['spec']['developer_options'][key] = kwargs[key]

    return data


def run_concurrently(*calls):
    """Run blocking callables (e.g. requests calls) concurrently with asyncio.gather and return their results in order.
    A call that raised returns its exception instead of failing the others."""
    async def _run():
        loop = asyncio.get_running_loop()
        return await asyncio.gather(*[loop.run_in_executor(None, call) for call in calls], return_exceptions=True)
    return asyncio.run(_run())


def get_element_events(element_uid, count=20, severity='warning'):
    """Fetch the events of an element, same request as `event list --element-uid`."""
    url = f"{sc.eventserver()}/event?index=0&limit={count}&offset=0&uid={element_uid}&severity={severity}"
    result = requests.get(url, headers=get_hdrs(), verify=False)
    result.raise_for_status()
    return result.json()


def print_events_table(events, element_uid, count=20, severity='warning'):
    """Print events returned by get_element_events() (or the exception it raised) as a table."""
    if isinstance(events, Exception):
        print(f"Failed to fetch events: {events}")
        return
    if not events:
        print("No events found")
        return
    rows = []
    for ln in events:
        msg = ln.get('message', '') or ''
        time_str = (ln['last_timestamp'] if ln.get('last_timestamp') else ln['ftime'] or '')[:19]
        rows.append([
            ln['id'],
            time_str,
            ln.get('source', ''),
            ln['kind'],
            ln.get('element_name') or ln['elementid'],
            ln.get('severity', ''),
            ln.get('object_id', ''),
            ln.get('reason', ''),
            ln.get('count', ''),
            msg if len(msg) <= 60 else msg[:60] + '...',
        ])
    hdrs = ["ID", "Date", "Source", "Kind", "Element", "Severity", "Object", "Reason", "Count", "Message"]
    print(tabulate(rows, headers=hdrs, tablefmt="pretty"))
    print()
    print(f"Showing {len(rows)} event(s) [limit={count}, severity={severity}]. Use `event list --element-uid {element_uid}` for more")


def get_element_batches(element_uid, count=20):
    """Fetch the latest batches that ran on an element, same request as `batch list --element-uid`."""
    url = f"{sc.engine()}/batch{parameter_string([f'limit={count}', 'offset=0', f'element_uid={element_uid}'])}"
    req = requests.get(url, verify=False, headers=get_hdrs())
    req.raise_for_status()
    return req.json()


def print_batches_table(batches, element_uid):
    """Print batches returned by get_element_batches() (or the exception it raised) as a table."""
    if isinstance(batches, Exception):
        print(f"Failed to fetch batches: {batches}")
        return
    if not batches:
        print("No batches found")
        return
    rows = []
    for r in batches[::-1]:
        tenant = r.get('tenant_name', '')
        userid = r.get('userid', '')
        worker_str = f"{r.get('assigned_workers', '-')}/{r.get('max_assigned_workers', '-')}/{r.get('total_workers', '-')}"
        if worker_str == "None/None/None":
            worker_str = "0/0/0" if r['errmsg'] == "Queue Timeout" else "Waiting for Profile"
        wait = "{}s".format(r['wait_time']) if r['st_time'] else "{}s*".format(r['wait_time'])
        if r['end_time']:
            exec_t = "{}s".format(r['duration']) if r['st_time'] else "-"
            total_t = "{}s".format(r['total_time'])
        else:
            exec_t = "{}s*".format(r['duration']) if r['st_time'] else "N/A"
            total_t = "{}s*".format(r['total_time'])
        rows.append([
            r['batchid'],
            r['name'],
            f"{tenant}/{userid}" if tenant else userid,
            r['tprofile'][0:8] if r.get('tprofile', '') else '',
            "{}/{}".format(r['npools_done'], r['npools']),
            worker_str,
            r['fanout'],
            r['prioritylane'],
            r['status'],
            r['batch_priority'],
            time.strftime("%Y-%m-%d %H:%M:%S", (datetime.fromtimestamp(int(r['submitted_time']), local_tz)).timetuple()),
            "{}/{}/{}".format(wait, exec_t, total_t),
        ])
    hdrs = ['BatchID', 'Name', 'User', 'Profile', '#Pools', 'Workers\n(Ac/As/T)', 'Fanout', 'Priority\nlane', 'Status', 'Batch\nPriority', 'Submitted\nTime', 'Times\n(W/E/T)']
    print(tabulate(rows, headers=hdrs, tablefmt="pretty"))
    print()
    print(f"Showing the latest {len(rows)} batch(es). Use `batch list --element-uid {element_uid}` for more. * - still in progress")


def get_element_age(item, ctime=None):
    if not ctime:
        ctime = item['metadata']['ctime']
    delta = datetime.now() - datetime.fromtimestamp(ctime)
    total_seconds = delta.total_seconds()
    age = "-"
    if total_seconds < 60:
        age = "0m"
    elif total_seconds < 7200:
        # Less than 7200 seconds (2 hours)
        min = int(total_seconds / 60)
        age = "{}m".format(min)
    elif total_seconds < 172800:
        # Less than 48 hours (2 days)
        hours = int(total_seconds / 3600)
        age = "{}h".format(hours)
    else:
        days = int(total_seconds/86400)
        age = "{}d".format(days)
    return age


def parse_k8s_duration(value):
    """Parse k8s-style duration string to seconds. e.g. 100d, 2m, 1y, 6h"""
    units = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400, 'w': 604800, 'mo': 2592000, 'y': 31536000}
    m = re.fullmatch(r'(\d+)(mo|[smhdwy])', value.strip())
    if not m:
        raise click.BadParameter(f"Invalid duration '{value}'. Use format like 30d, 2mo, 1y, 6h")
    return int(m.group(1)) * units[m.group(2)]


def get_expiry_in(expiry_epoch):
    if not expiry_epoch:
        return "-"
    delta = datetime.fromtimestamp(int(expiry_epoch)) - datetime.now()
    secs = delta.total_seconds()
    if secs <= 0:
        return "expired"
    if secs < 7200:
        return "{}m".format(int(secs / 60))
    if secs < 172800:
        return "{}h".format(int(secs / 3600))
    return "{}d".format(int(secs / 86400))


def get_user_home_sshkey(passed_pub_file=None):
    id_rsa_f = f"{os.environ['HOME']}/.ssh/id_rsa.pub"
    id_ed_f = f"{os.environ['HOME']}/.ssh/id_ed25519.pub"
    user_sshkey = None
    if passed_pub_file and os.path.isfile(passed_pub_file):
        with open(passed_pub_file) as fp:
            user_sshkey = fp.read().strip()
    elif os.path.isfile(id_rsa_f):
        with open(id_rsa_f) as fp:
            user_sshkey = fp.read().strip()
    elif os.path.isfile(id_ed_f):
        with open(id_ed_f) as fp:
            user_sshkey = fp.read().strip()
    return user_sshkey

def get_element_owner(element):
    owners = []
    for acl in element.get('access', {}).get('acl', []):
        if acl.get('readwrite'):
            owners.append(f"{acl['tenant']}/{acl['userid']}")
    if not owners:
        return "-"
    return owners[0]


def get_element_liveness_str(liveness):
    liveness_map = ["unhealthy", "partial", "healthy", "unknown", "poweroff"]
    return liveness_map[liveness]


def fix_ssh_private_key(raw_key: str) -> str:
    raw_key = raw_key.strip()

    # Extract header and footer dynamically
    header_match = re.search(r"-----BEGIN [^-]+-----", raw_key)
    footer_match = re.search(r"-----END [^-]+-----", raw_key)

    if not header_match or not footer_match:
        raise ValueError("Could not find PEM header/footer in input")

    header = header_match.group(0)
    footer = footer_match.group(0)

    # Strip headers and collapse all whitespace from the body
    body = raw_key[header_match.end():footer_match.start()]
    body = re.sub(r"\s+", "", body)

    # OpenSSH keys use 70 chars/line, standard PEM uses 64
    width = 70 if "OPENSSH" in header else 64
    formatted = textwrap.fill(body, width=width)
    return f"{header}\n{formatted}\n{footer}\n"


def get_element_kubeconfig(result):
    """Write kubeconfig from an expanded element's IAM credentials and return the path.

    Works for ROBINCLUSTER, K8S, and K3S elements that store kubeconfig via IAM.
    Expects result to have spec.iam.config.kube_config (populated by ?expand=true).
    """
    name = result['metadata']['name']
    iam = result['spec'].get('iam')
    if not iam:
        print(f"Element '{name}' does not have an IAM (try fetching with ?expand=true)")
        return None
    kube_config = iam.get('config', {}).get('kube_config')
    if not kube_config:
        print(f"Element '{name}' IAM does not contain a kube_config")
        return None
    base_dir = os.path.join(os.environ['HOME'], '.mdcaprc')
    if not os.path.isdir(base_dir):
        os.mkdir(base_dir)
    cluster_dir = os.path.join(base_dir, name)
    if not os.path.isdir(cluster_dir):
        os.mkdir(cluster_dir)
    cluster_config = os.path.join(cluster_dir, 'kube.config')
    if not os.path.isfile(cluster_config):
        with open(cluster_config, 'w') as fp:
            fp.write(yaml.dump(kube_config, default_flow_style=False, allow_unicode=True, encoding=None))
    return cluster_config


def build_helm_app_spec(repo=None, chart=None, chart_version=None, cluster=None,
                        namespace=None, storage_class=None, values_dict=None,
                        appvalues_name=None, appvalues_uid=None,
                        cluster_admin_privileges=False, skip_workflow=False,
                        primary_network=None, secondary_networks=None, set_options=None, robinrpool=None):
    preset = appvalues_name or appvalues_uid
    spec = {}
    if appvalues_name: spec['appvalues_name'] = appvalues_name
    if appvalues_uid:  spec['appvalues_uid'] = appvalues_uid
    if not preset:
        if repo:          spec['repo_name'] = repo
        if chart:         spec['chart_name'] = chart
        if values_dict:   spec['values'] = values_dict

    if chart_version:      spec['chart_version'] = chart_version
    if cluster:            spec['cluster'] = cluster
    if namespace:          spec['namespace'] = namespace
    if storage_class:      spec['storage_class'] = storage_class
    if primary_network:    spec['primary_network'] = primary_network
    if secondary_networks: spec['secondary_networks'] = [*secondary_networks]
    if set_options:        spec['set_options'] = [*set_options]
    if robinrpool:         spec['robinrpool'] = robinrpool
    if cluster_admin_privileges: spec['cluster_admin_privileges'] = True
    if skip_workflow:            spec['skip_workflow'] = True
    return spec
