def _login(userid, password, tenant_info, timeout, otp=None):
    """Login into MDCAP"""
    tenant = tenant_info['name']
    if tenant_info['tenant_type'] == TENANT_TYPE_OPENID:
        details = tenant_info['details']
        auth_endpoint = details['auth_endpoint']
        token_endpoint = details['token_endpoint']
        CLIENT_ID = tenant_info['clientid']

        if not userid:
            # Device flow — no username/password needed, user approves in browser
            device_auth_url = auth_endpoint.replace('/auth', '/auth/device')
            try:
                resp = requests.post(device_auth_url, data={
                    "client_id": CLIENT_ID,
                    "scope": "openid profile email",
                }, verify=False)
                resp.raise_for_status()
                auth = resp.json()
            except Exception as e:
                click.secho(f"ERROR: Failed to initiate device flow: {e}", fg="red")
                sys.exit(1)

            device_code = auth["device_code"]
            user_code = auth["user_code"]
            expires_in = auth["expires_in"]
            interval = auth.get("interval", 5)
            verification_uri_complete = auth.get("verification_uri_complete", auth["verification_uri"])

            click.echo("")
            click.secho("  Open this URL in your browser to log in:", fg="cyan")
            click.secho(f"\n    {verification_uri_complete}\n", fg="yellow", bold=True)
            if "verification_uri_complete" not in auth:
                click.echo(f"  Enter code: {user_code}")
            click.echo(f"  Waiting for approval (expires in {expires_in}s) ...\n")

            deadline = time.time() + expires_in
            refresh_token_val = None
            while time.time() < deadline:
                click.echo(f"\rPolling after {interval} seconds ..    ", nl=False)
                time.sleep(interval)
                poll = requests.post(token_endpoint, data={
                    "grant_type": "urn:ietf:params:oauth:grant-type:device_code",
                    "client_id": CLIENT_ID,
                    "device_code": device_code,
                }, verify=False)
                body = poll.json()
                error = body.get("error")

                if poll.status_code == 200:
                    refresh_token_val = body.get("refresh_token")
                    sc.set_keycloak_tokens(
                        access_token=body.get("access_token"),
                        refresh_token=refresh_token_val,
                        expires_in=body.get("expires_in", 0),
                        token_type=body.get("token_type", "Bearer"),
                        token_endpoint=token_endpoint,
                        client_id=CLIENT_ID,
                    )
                    click.echo("")
                    break
                elif error == "authorization_pending":
                    continue
                elif error == "slow_down":
                    interval += 5
                elif error == "expired_token":
                    click.secho("  Device code expired. Please run login again.", fg="red")
                    sys.exit(1)
                elif error == "access_denied":
                    click.secho("  Access denied.", fg="red")
                    sys.exit(1)
                else:
                    click.secho(f"  Unexpected error: {body}", fg="red")
                    sys.exit(1)
            else:
                click.secho("  Timed out waiting for browser approval.", fg="red")
                sys.exit(1)

            if not refresh_token_val:
                click.secho("  ERROR: No refresh token in device flow response.", fg="red")
                sys.exit(1)

            data = {'refresh_token': refresh_token_val, 'tenant': tenant}
        else:
            REDIRECT_URI = details['redirect_uri']

            if not REDIRECT_URI:
                click.secho(f'WARN: No KEYCLOAK_REDIRECT_URI found in Engine env. Taking from current env', fg="yellow")
                REDIRECT_URI = os.getenv("KEYCLOAK_REDIRECT_URI")
                if not REDIRECT_URI:
                    click.secho(f"ERROR: Environment variable 'KEYCLOAK_REDIRECT_URI' not defined", fg="red")
                    sys.exit(1)

            try:
                payload = {
                    "response_type": "code",
                    "client_id": CLIENT_ID,
                    "scope": "openid",
                    "redirect_uri": REDIRECT_URI,
                }
                payload_str = "&".join("%s=%s" % (k,v) for k,v in payload.items())
                resp = requests.get(
                    url = auth_endpoint,
                    params = payload_str,
                    allow_redirects=False,
                    verify=False
                )
                resp.raise_for_status()
                cookie = resp.headers['Set-Cookie']
                cookie = '; '.join(c.split(';')[0] for c in cookie.split(', '))
                page = resp.text
                form_action = html.unescape(re.search(r'<form\s+.*?\s+action="(.*?)"', page, re.DOTALL).group(1))
                resp = requests.post(
                    url=form_action,
                    data={
                        "username": userid,
                        "password": password,
                    },
                    headers={"Cookie": cookie},
                    allow_redirects=False,
                    verify=False
                )
                resp.raise_for_status()

                page = resp.text
                form_id = ''

                # Differentiate at this point between single factor and multifactor authentication
                if page:
                    unescaped_html = html.unescape(page)
                    if re.search(r'Invalid username or password', unescaped_html):
                        raise Exception('Invalid username or password')

                    form_id = html.unescape(re.search(r'<form\s+.*?\s+id="(.*?)"', page, re.DOTALL).group(1))
                    if 'otp' in form_id:
                        # Multifactor auth. Need to give OTP
                        if not otp:
                            otp = click.prompt('Please enter OTP from the AUTH App', type=str, hide_input=True)
                        resp.raise_for_status()
                        page = resp.text
                        form_action = html.unescape(re.search(r'<form\s+.*?\s+action="(.*?)"', page, re.DOTALL).group(1))
                        resp = requests.post(
                            url=form_action,
                            data={
                                "otp": otp
                            },
                            headers={"Cookie": cookie},
                            allow_redirects=False,
                            verify=False
                        )
                        unescaped_html = html.unescape(resp.text)
                        if re.search(r'Invalid authenticator code\.', unescaped_html):
                            raise Exception('Invalid OTP entered. Please try again')
                        resp.raise_for_status()

                    else:
                        raise Exception(f'Unrecognised Response for URL: {form_action}')

                resp.raise_for_status()
                redirect = resp.headers['Location']
                query = urllib.parse.urlparse(redirect).query
                redirect_params = urllib.parse.parse_qs(query)
                auth_code = redirect_params['code'][0]

                data = {'auth_code': auth_code, 'tenant': tenant}
            except Exception as e:
                click.secho(f"Tenant Login Failed", fg="red")
                click.secho(f'ERROR: {e}', fg="red")
                sys.exit(1)
    else:
        data = {'userid': userid, 'password': password, 'tenant': tenant}
    try:
        if timeout:
            data['timeout'] = timeout
        resp = requests.post(f"{sc.engine()}/login", json=data, verify=False)
        resp.raise_for_status()
        r = resp.json()
        print("Login successful! MDCAP is all yours.")
        sc.set_creds(r['token'], r['roleuid'])
    except Exception as ex:
        handle_error(ex)
        if "expired" in ex.response.content.decode('utf-8'):
            print("Use: mdcap change-password <username>")
        sys.exit(1)
    try:
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/login", verify=False, headers=hdrs)
        r.raise_for_status()
        resp = r.json()
        print(f"Username: {resp['username']}")
        print(f"Tenant: {tenant_info['name']}({resp['current_tenant']})")
        cur_role = [(r[0], r[1]) for r in resp['roleinfo'] if r[0] == resp['current_role']]
        if len(cur_role):
            print(f"Current Role: {cur_role[0][1]}, uid: {cur_role[0][0]}")
        else:
            print("No role assigned to this user. Please ask admin to assign a role.")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to access information about self.")


@cli.group(cls=ClickAliasedGroup, aliases=['sc'])
def server_context():
    """Manage server contexts"""
    pass

@server_context.command(name="set")
@click.argument("name", type=str)
@click.argument("mdcap-url", type=str)
@click.option('-u', '--username', type=str)
@click.option('-p', '--password', hide_input=True)
@click.option('--tenant', type=str, help='Login to a tenant')
@click.option('--otp', type=str, help='OTP for Tenant multi factor authentication', hide_input=True)
@click.option('-t', '--timeout', type=int, help="Timeout of issued token, in seconds")
@click.option('-d', '--default', is_flag=True, type=bool, default=False, help="Make this the default connection context")
def set(name, mdcap_url, username, password, tenant, otp, timeout, default):
    """Add or update a new MDCAP server connection context"""
    try:
        ServerContext().set_context(name.lower(), url=mdcap_url, default=default)
        if (username and password) or tenant:
            tenant_info = _tenant_info(tenant)
            _login(username, password, tenant_info, timeout, otp)
    except Exception as ex:
        handle_error(ex)

@server_context.command()
@click.option('-o', '--format', type=click.Choice(['json', 'yaml']))
def list(format):
    """List all the registered MDCAP server connection contexts"""
    try:
        if format == 'json':
            print(json.dumps(ServerContext().contexts, indent=4))
        elif format == 'yaml':
            print(yaml.dump(ServerContext().contexts, indent=4))
        else:
            hdrs = ["Name", "Endpoint", "Default"]
            vals = []
            for name, ctx in ServerContext().contexts.items():
                vals.append((name, ctx['mdcap_base_url'], ctx.get('default', False)))
            print(tabulate(vals, headers=hdrs, tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex)

@server_context.command()
@click.argument('name')
def makedefault(name):
    """Set a default server context"""
    try:
        ServerContext().set_context(name.lower(), default=True)
    except Exception as ex:
        handle_error(ex)

@server_context.command()
@click.argument('name')
def remove(name):
    """Remove a server context from the list"""
    try:
        ServerContext().del_context(name.lower(), default=True)
    except Exception as ex:
        handle_error(ex)

class _EmptyAllowedPromptOption(click.Option):
    # click.Option.prompt_for_value ignores show_default, so an empty default always renders as "[]"
    def prompt_for_value(self, ctx):
        return click.prompt(self.prompt, default="", show_default=False, hide_input=True)

@cli.command(name="change-password")
@click.argument("username", type=str)
@click.option('-o', '--old-password', cls=_EmptyAllowedPromptOption, prompt="Old password (required unless you are an admin)", hide_input=True, help="Required if not admin")
@click.option('-n', '--new-password', prompt=True, hide_input=True, required=True)
@click.option('-c', '--confirm-password', prompt=True, hide_input=True, required=True)
@click.option('-e', '--expiry', type=str, help="Expiry of the new password. Format: Ad:Bh:Cm:Ds. A is #days, B is #hours, C is #minutes, D is #seconds")
def change_password(username, old_password, new_password, confirm_password, expiry, **kwargs):
    """Change user password"""
    try:
        r = None
        if new_password != confirm_password:
            raise Exception(f"Passwords don't match")
        data = {}
        data['opcode'] = 'change-password'
        data['userid'] = username
        data['new_password'] = new_password
        if expiry:
            data['expiry'] = parse_time(expiry)
        hdrs = {}
        try:
            token = sc.token()
            if token:
                hdrs['authorization'] = token
        except Exception:
            pass
        if old_password:
            data['old_password'] = old_password
        r = requests.post(f"{sc.engine()}/login/reset", json=data, headers=hdrs, verify=False)
        r.raise_for_status()
        resp = r.json()
        print(resp['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, data=data)

@cli.command()
@click.argument("username", type=str, required=False, default=None)
@click.option('-p', '--password', default=None, hide_input=True, help='Password for login')
@click.option('--tenant', type=str, help='Login to a tenant', default=DEFAULT_TENANT)
@click.option('--otp', type=str, help='OTP for Tenant multi factor authentication', hide_input=True)
@click.option('-t', '--timeout', type=int, help="Timeout of issued token, in seconds")
def login(username, password, tenant, otp, timeout):
    """Login into MDCAP"""
    tenant_info = _tenant_info(tenant)
    if not username and tenant_info.get('tenant_type') != TENANT_TYPE_OPENID:
        raise click.UsageError(f"username is required for tenant type '{tenant_info.get('tenant_type')}'")
    if username and not password:
        password = click.prompt("Password", hide_input=True)
    _login(username, password, tenant_info, timeout, otp)


