@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l", "--labels", type=str, multiple=True, help="Filter by labels used to idenftify bmp. Format: class:sku2,location:tokyo...")
@click.option("-n", "--name", type=str, help="Filter by specifying name of bmp")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def list(index, labels, name, output, **kwargs):
    """List Bare Metal Profilepack a.k.a bmp )"""
    try:
        r = None
        limit, offset = offset_limit_from_range(index)
        taglist = parse_labels(labels)
        if name:
            name=f"name={name}"
        query_params = [limit, offset, taglist, name]
        limit_url = parameter_string(query_params)

        hdrs = get_hdrs()
        r = requests.get("{}/bmprofile{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()
        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
        else:
            data = []
            headers = ["uid", "name", "version", "os", "parentUID", "tags", "description"]
            for item in results['items']:
                tags = []
                if item['tags']:
                    for key, val in item['tags'].items():
                        tags.append(f"{key}:{val}")
                data.append([
                    item['uid'],
                    item['name'],
                    item['version'],
                    item['ostype'],
                    item['parentuid'] if item['parentuid'] else '-',
                    #item['config_url'],
                    ",".join(tags) if item['tags'] else '-',
                    item['description'] if item['description'] else '-'
                ])

            print(tabulate(data, headers, tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list the bmp(s). ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


def _delete_bmp(uid, force=False, **kwargs):
    try:
        if uid is None:
            return

        r = None
        res_af = None
        hdrs = get_hdrs()
        data = {}
        data['force'] = force
        r = requests.get(f"{sc.engine()}/bmprofile/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()

        url = result['config_url']

        # delete BMP from db

        r = requests.delete(f"{sc.engine()}/bmprofile/{uid}", verify=False, json=data, headers=hdrs)
        r.raise_for_status()

        # delete BMP from artifactory
        res_af = requests.delete(f"{url}", verify=False, headers=hdrs)
        res_af.raise_for_status()
    except Exception as ex:
        handle_error(ex, action_msg="Failed to delete bmp with uid: {}. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)
        if kwargs.get('urlinfo') and res_af:
            compute_curl_command(res_af, headers=hdrs)


@bmprofilepack.command()
@click.argument('uid', type=str)
@click.option('-f', '--force', is_flag=True, help="Force delete even if wfs and fns are actively used in ongoing batches")
@add_options(common_options)
def delete(uid, force, **kwargs):
    """Delete an artifact from Robin Artifactory and unregister the artifact"""
    _delete_bmp(uid, force, **kwargs)
    print(f"Successfully deleted bmp {uid}")


def validate_ks(spec, pack_root):
    ks_path = spec.get('kickstart', None)
    if not ks_path:
        print("please add under spec.kickstart")
        print("main.ks: <URL>")
        raise Exception("spec.kickstart missing in manifest.yaml")
    else:
        ks = spec['kickstart']['main.ks']
        if not (ks.startswith("http") or ks.startswith("https") or ks.startswith("file")):
            if not os.path.isfile(pack_root + "/" + ks):
                raise Exception(f"file missing spec.kickstart.main.ks in {pack_root}. If \
                    file is present inside bmp dir as kickstart/main.ks, please add it in \
                        manifest.yaml as main.ks: file://kickstart/main.ks")



def get_manifest_metadata(file, pack_root, opn="add"):
    #print (f"validate manifest.yaml keys for file at: {file}")
    mandatory_keys = ['kind', 'apiversion', 'metadata', 'spec', 'functions', 'workflows']
    md = None
    with open(file, 'rb') as mf:
        md = yaml.safe_load(mf)
        keys = md.keys()
        for k in mandatory_keys:
            if k not in keys:
                print("Following keys are mandatory in manifest")
                print("  kind: bmprofile")
                print("  apiversion: mdcap/<version>")
                print("  metadata:")
                print("    labels:")
                print("      mdcap/operatingSystem: <os><verion>")
                print("  spec:")
                print("    .....")
                print("  functions:")
                print("    .....")
                print("  workflows:")
                print("    .....")
                raise Exception(f"{k} not found in the manifest.yaml")
        if md['metadata']['labels']['mdcap/operatingSystem'] == None:
                print("      mdcap/operatingSystem: <os><verion>")
                raise Exception(f"{k} missing in manifest.yaml")
    if opn == "add":
        validate_ks(md['spec'], pack_root)
    return md

def get_hash_for_file(path):
    '''
    blake2 is used for getting hash, its faster than md5sum
    https://blake2.net/
    '''
    with open(path, "rb") as f:
        file_hash = blake2b()
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            file_hash.update(chunk)
    return file_hash.hexdigest()

# The functions to be registered may have following issues:
#
# 1. A function with the identical contents is already registered (a BMP is added twice). This
#    causes the blake2 hash to match.
#       Dont care of 2 and 3 below. We can use this already registered fn.

# 2. A Function with the same name is already registered:
#
# 3. The Function name is different but its script with the same name is already present.
#       In both the above cases we do not proceed and report user to rename the function and/or
#       script, likewise.

def bmp_add_fns(bmp_id, bmpname, fndeflist, fndir, bmp_name_ver="None"):
    if fndeflist:
        rep_bmp_fn = []
        for key, fn in fndeflist.items():
            r = None
            hdrs = get_hdrs()
            script = fndir + '/' + fn["script_path"]
            selectors = fn.get("selectors", {})
            if bmp_name_ver != "None":
                selectors["mdcap/profile"] = bmp_name_ver
            data = {
                'name': fn["name"],
                'version': fn["version"],
                'operator': fn["operator"].lower(),
                'etypes': fn['etypes'],
                'description': fn.get("description", "QCT BMP function"),
                'envs': ','.join([env_dict['name'] for env_dict in fn.get("envs", [])]),
                'fanout': fn["fanout"],
                'action': fn.get("action", 'default'),
                'mode': 0 if fn["mode"].lower() == 'unit' else 1,
                'mem_size': fn.get("mem_size",  DEFAULT_FN_MEM_SIZE),
                'cpu': fn.get("cpu", None),
                'timeout': fn.get("timeout", 0),
                'runtime': fn.get("runtime",''),
                'selectors': selectors,
                'abstract': key,
                'bmp_id' : bmp_id
            }
            if script:
                # Check if there is already a function with same contents exists
                b2bhash = get_hash_for_file(script)
                r = requests.get(f"{sc.engine()}/fn/hash/{b2bhash}", verify=False, headers=hdrs)
                if r.ok:
                    mdcapfn = r.json()
                    version = mdcapfn['version']
                    name    = mdcapfn['name']
                    src     = mdcapfn['source']
                    if name != fn['name'] or version != fn['version'] or os.path.basename(script) != src:
                        print(f"Found prexisting file {src} for function '{name}':'{version}' with identical contents. Will use this instead of {os.path.basename(script)}")
                    continue

                # If the function script file name is same. That will be reported here.
                data['script'] = script.split('/')[-1]
                files = {'file': (script.split('/')[-1], open(script, 'rb'))}
                r = requests.post(f"{sc.engine()}/fn/upload", files=files, headers=hdrs, verify=False)
                r.raise_for_status()
                data['uid'] = r.json()['fn_uids']

            # function is already uploaded, now register it.
            r = requests.post(f"{sc.engine()}/fn", json=data, verify=False, headers=hdrs)
            r.raise_for_status()
            res = r.json()
            if res.get('bmp_fn' , ''):
                rep_bmp_fn.append(fn.get("name" , ''))
        return rep_bmp_fn

    else:
        print("No functions registered")

def validate_bmp_wfs(wflist):
    if len(wflist) == 0:
        return
    r = None
    hdrs = get_hdrs()
    r = requests.get(f"{sc.engine()}/workflow", headers=hdrs, verify=False)
    r.raise_for_status()
    results = r.json()
    print
    if results['items']:
        for _r in results['items']:
            if _r['name'] in wflist.keys():
                raise Exception(f"workflow conflict: {_r['name']} already present. Please rename your workflow.")

def bmp_add_wfs(bmpname, wfdefs, fndefs, fndir, apiversion='mdcap/v1'):
    if wfdefs:
        for wfname, fndict in wfdefs.items():
            wf = {}
            wf['name'] = wfname
            wf['kind'] = fndict['kind']
            wf['fns'] = {}
            absfndict = fndict['functions']
            if not absfndict:
                raise Exception(f"Could not find any functions under workflow name: {wfname}")
            hdrs = get_hdrs()
            # The functions to be registered under the WFs may have following issue while registering:
            # 1. A Function with the same name is already registered:
            #
            # 2. The Function name is different but its script with the same name is already present.
            #       In both the above cases we do not proceed and report user to rename the function and/or
            #       script, likewise.
            #
            # 3. A function with the identical contents is already registered (a BMP is added twice). This
            #    causes the blake2 hash to match.
            #       We get the  details of the registered function and make the changes in our WF.
            #       The WF will be registered to use the already registered fn, thereby discarding
            #       the BMP function, which wont be uploaded.

            for fnname, data in absfndict.items():
                #print(f"\t Process Fn {fnname}")
                fn = {}
                fndata = fndefs[fnname]
                r = None
                fnscript = f"{fndir}/{fndata['script_path']}"
                if os.path.isfile(fnscript):
                    b2bhash = get_hash_for_file(fnscript)
                else:
                    raise Exception(f"In Workflow: {wfname}, Function: {fnscript} file not present")

                # Blake2 hash check
                # Check if there is an identical function already registered. We will have
                # to modify this wf to use that fn, as MDCAP can not allow two functions with
                # same contents and same name.
                r = requests.get(f"{sc.engine()}/fn/hash/{b2bhash}", verify=False, headers=hdrs)
                if r.ok: # ok means 200, contens match and use this
                    mdcapfn = r.json()
                    if mdcapfn:
                        fn['function'] = mdcapfn['uid']
                        fn['script'] = mdcapfn['source']
                        # Check for 'elements' for ver >1
                        if apiversion != 'mdcap/v1':
                            if absfndict[fnname].get('elements'):
                                fn['elements'] = absfndict[fnname]['elements']

                elif r.status_code == 404: # Not found, 404
                    fn['script'] = mdcapfn['script_path']
                else:
                    r.raise_for_status()
                # data is a list of depends in v1
                if apiversion == 'mdcap/v1':
                    if data:
                        fn['depends'] = data
                else:
                    if data.get('depends'):
                        fn['depends'] = data['depends']
                    else:
                        fn['depends'] = []

                wf['fns'][fnname] = fn

            # register the workflow
            hdrs = get_hdrs()
            wf['type'] = 'dynamic'
            url = "{}/workflow".format(sc.engine())
            r = requests.post(url, json=wf, verify=False, headers=hdrs)
            r.raise_for_status()

def validate_bmp_fns(fndefsdict, fndir):
    #print(f"fndefsdict :{fndefsdict}")
    for name, fn in fndefsdict.items():
        script = fn["script_path"]
        name =  fn["name"]
        #print (fndir + "/" + script)
        if not os.path.isfile(fndir + "/" + fn["script_path"]):
            raise Exception(f"Function script {script}, not found for function name '{name}'")

def get_profile_extended_info(url, uid=None, wait_time_sec=30, show_manifest=False, show_profile=False, show_ks=False, show_diff=False, return_state=False):
    start = time.time()
    state = "Ready"
    if wait_time_sec > 10:
        print("Please wait while the bm state is ready. This depends on the bandwidth as package downloads specified in manifest takes time.")
    status_url = url + "/status"
    hdrs= get_hdrs()
    status_resp = requests.get(status_url, headers=hdrs, verify=False)
    data = status_resp.json()
    #print (f"Info Ready data: {data}")
    for k,v in data.items():
        if "Error" in v:
            state = "Not Ready"

    if return_state == True:
        return state

    print("State          : {}".format(state))
    print()
    if state != "Ready":
        print("Status          ")
        for k,v in data.items():
            print(f"    {k}:")
            for e in v.split("\n"):
                print("        {}".format(e))

    if state == "Ready":
        hdrs = get_hdrs()
        manifest_url = url + "/manifest.local.yaml"
        if uid and show_profile:
            res_prof = requests.get(f"{sc.engine()}/bmprofile/inputs/{uid}", headers=hdrs, verify=False)
            if res_prof.ok:
                data = res_prof.json()
                print(f"{'-' * 20}Input field as read from Kickstart and values applied from Manifest{'-' * 20}")
                print(json.dumps(data, indent=4))
                print(f"{'-' * 20}Input Data{'-' * 20}")
                print("** Please note that for the values which are empty as they are specific to each BM,")
                print("** those values can be specified as BM's config json during 'mdcap bm add'")
            else:
                print("Failed to get profile data.")

        if show_manifest:
            res_manifest = requests.get(manifest_url, allow_redirects=True, verify=False, headers=hdrs)
            if res_manifest.ok:
                print(f"{'-' * 20}Manifest file{'-' * 20}")
                print(f"{res_manifest.content.decode('utf-8')}")
                print(f"{'-' * 20}Manifest file{'-' * 20}")
            else:
                print(f"Could not get manifest file at: {manifest_url}")

        if show_ks:
            ks_url = bmp_url_to_ks_url(url)
            if ks_url:
                res_ks = requests.get(ks_url, allow_redirects=True, verify=False, headers=hdrs)
                if res_ks.ok:
                    print(f"{'-' * 20}Kickstart file{'-' * 20}")
                    print(f"{res_ks.content.decode('utf-8')}")
                    print(f"{'-' * 20}Kickstart file{'-' * 20}")
            else:
                print("Could not get kickstart file in the bmp")

        if show_diff:
            if uid:
                get_profile_update_diff_file(uid, display=True)
            else:
                print(f"Please specify uid")

def get_profile_update_diff_file(uid, display=False):
    hdrs= get_hdrs()
    res_prof = requests.get(f"{sc.engine()}/bmprofile/{uid}", headers=hdrs, verify=False)
    if res_prof.ok:
        data = res_prof.json()
        print(f"config_url: {data['config_url']}")
        diff_file_url = data['config_url'] + "/profilediff.json"
        diff_resp = requests.get(diff_file_url, verify=False, headers=hdrs)
        if diff_resp.ok:
            if display == True:
                print(f"{'-' * 20}Diff file{'-' * 20}")
                print(f"{diff_resp.content.decode('utf-8')}")
                print(f"{'-' * 20}Diff file{'-' * 20}")
            return diff_file_url, diff_resp.status_code
        else:
            return None, diff_resp.status_code
    else:
        print("Failed to get profile data.")
    return None, res_prof.status_code


def register_bmp_profile(bmp_name, version, url, metadata, parentuid, desc, referred_artifact_urls=None):
        #get_profile_extended_info(url, wait_time_sec=5)
        # add additional labels
        tags = metadata['metadata']['labels']
        tags["mdcap/profile"] = f"{bmp_name}_{version}"
        data = {}
        data['name'] = bmp_name
        data['version'] = version
        data['description'] = desc
        data['tags'] = json.dumps(tags)
        data['profile'] = {}
        data['parentuid'] = parentuid
        data['from_bmp'] = {'url': url, 'ostype': metadata['metadata']['labels']['mdcap/operatingSystem'] }
        data['referred_artifact_urls'] = referred_artifact_urls
        r = requests.post(f"{sc.engine()}/bmprofile", json=data, allow_redirects=True, verify=False, headers=get_hdrs())
        r.raise_for_status()
        return r, data

def extract_http(spec, referred_artifact_urls):
    for entry in spec:
        if type(spec.get(entry)) == str and spec.get(entry).startswith("http"):
          referred_artifact_urls.append(spec.get(entry))
        if type(spec.get(entry)) in [dict, list] and spec.get(entry):
          extract_http(spec.get(entry), referred_artifact_urls)

@bmprofilepack.command()
@click.argument('name', type=str)
@click.argument('version', type=str)
@click.argument('path', type=str)
@click.option('-d', "--desc", type=str, help="description about the bmp")
@add_options(common_options)
def add(name, version, path, desc, **kwargs):
    """Register a BMP (Bare Metal Profilepack)\n
        NAME    : name you like like to give to BMP\n
        VERSION : version for this BMP\n
        PATH    : path to the pack. Can be a directory, a .tar or .tar.gz file\n
    """
    unwind = False
    tmpdir = ""
    try:
        path = path.rstrip("/")
        req = None
        md = None
        fndeflist = None
        wflist = None
        fndir = None
        r = None
        path = path.rstrip("/")
        hdrs = get_hdrs()
        query_string = ""
        bmp_id = None
        if not os.path.exists(path):
            raise Exception(f"Path {path} not found.")
        if os.path.isfile(path):
            file = path
            if path.endswith("tar") or path.endswith("tar.gz") or path.endswith("tgz"):
                # extract manifest file and validate
                tmp = tempfile.TemporaryDirectory()
                tmpdir = tmp.name
                if os.path.isdir(tmpdir):
                    _, err, status = run_command(f"tar -C {tmpdir} -xf {path} manifest.yaml functions")
                    if status:
                        raise Exception(f"""Could not extract manifest.yaml inside pack, error: {err}.
                        \nPlease ensure that the archive directly opens to * and not a directory/*.
                        \nPlease create tar by:
                            % cd packdir
                            % tar -czvf pack.tgz *
                        """)
                    md = get_manifest_metadata(f"{tmpdir}/manifest.yaml", tmpdir)
                    fndir = f"{tmpdir}/functions"
                    wflist = md['workflows']
                    fndeflist = md['functions']
                    #print(f"WFlist: {wflist}, fndeflist: {fndeflist}")
                    validate_bmp_fns(fndeflist, fndir)
                    validate_bmp_wfs(wflist)
                else:
                    raise Exception("Failed to create tmp directory. Please open the tar and specify pack as a directory")
            else:
                print(traceback.format_exc())
                raise Exception("Unknown file compression. Please use .tgz or .tar.gz only for bmprofile pack")
            # Request Engine to validate if this is a valid operation and return us the URL to artifactory
            # where the upload needs to be done
            filename = os.path.basename(path)
            query_string = f"?name={name}&version={version}&filename={filename}"
            req = requests.get(f"{sc.engine()}/bmprofile{query_string}",
                                      allow_redirects=True, verify=False, headers=hdrs)
            #print(f"URL: {req.url}")
            req.raise_for_status()
            url = req.json()['redirect_url']

        elif os.path.isdir(path):
            file = '/tmp/' + next(tempfile._get_candidate_names()) + ".tar.gz"
            filename = os.path.basename(file)
            md = get_manifest_metadata(f"{path}/manifest.yaml", path)
            fndir = f"{path}/functions"
            wflist = md['workflows']
            fndeflist = md['functions']
            validate_bmp_fns(fndeflist, fndir)
            validate_bmp_wfs(wflist)

            # Request Engine to validate if this is a valid operation and return us the URL to artifactory
            # where the upload needs to be done. We first validate with engine and then tar the archive. The
            # idea is to fail early.
            query_string = f"?name={name}&version={version}&filename={filename}"
            req = requests.get(f"{sc.engine()}/bmprofile{query_string}",
                                      allow_redirects=True, verify=False, headers=hdrs)
            req.raise_for_status()
            url = req.json()['redirect_url']
            # engine made thumbs up, we now create a tar and upload.
            abspath=os.path.abspath(path)
            print(f"Please wait while the BMP is compressed and uploaded")
            _, err, status = run_command(f"tar -czvf {file} .", cwd=abspath)
            if status:
                raise Exception(f"Could not create tar archive at {file} from {abspath}, error code: {status}, error: {err}")

        elif path.startswith("git://"):
            print(f"TODO: Git path, to be handled with CI/CD")
        unwind = True
        #print(f"Engine Returned URL: {url}")
        # upload to artifactory
        if not upload_to_robin_artifactory(url, file):
            raise Exception("File upload failed. Please check artifactory logs")
        # proceed to register the kickstart and extract the variable contents out of it
        # which needs to be converted to bare metal profile.
        referred_artifact_urls = []
        extract_http(md['spec'], referred_artifact_urls)
        r, data = register_bmp_profile(name, version, os.path.dirname(url), md, None, desc, referred_artifact_urls)
        msg = r.json()['msg']
        bmp_id = r.json()['id']
        if fndir:
            rep_bmp_fn = bmp_add_fns(bmp_id, name, fndeflist, fndir, bmp_name_ver=f"{name}_{version}")
            bmp_add_wfs(name, wflist, fndeflist, fndir, apiversion=md['apiversion'])
        else:
            print("No directory for functions was found. The workflows can not be added to MDCAP.")
        print(f"{msg}")
        print()

        if rep_bmp_fn:
            print(f"Following fn_name:fn_version were already present in mdcap so registered by appending the bmp_uid to the version to maintain the uniqueness:\n  {rep_bmp_fn} \n")


        print(f"Since the BMP may take some to be ready, please use command below to check status:\n\n\t mdcap bmp info {r.json()['id']}\n")

        # if bmp has referred the artifact url
        # then update the artifact table so that user cant delete the artifact if it is being referred by any bmp


    except Exception as ex:
        handle_error(ex, action_msg="Failed to register BMP {}. ".format(name), exit=False)
        if unwind == True:
            _delete_bmp(bmp_id)

    finally:
        if os.path.isdir(path) and os.path.isfile(file):
            os.unlink(file)

        if path.endswith("tar") or path.endswith("tar.gz") or path.endswith("tgz"):
            if os.path.isfile(tmpdir):
                os.unlink(tmpdir)

        if kwargs.get('urlinfo'):
            if req:
                compute_curl_command(req, headers=hdrs)
            if r:
                compute_curl_command(r, headers=hdrs, data=data)


@bmprofilepack.command()
@click.argument('name', type=str)
@click.argument('version', type=str)
@click.argument('parentuid', type=str)
@click.argument('path', type=str)
@click.option('-d', "--desc", type=str, help="description about the update")
@add_options(common_options)
def update(name, version, parentuid, path, desc, **kwargs):
    """Update the BMP from another version of BMP\n
        NAME        : name you like like to give to the BM profile pack update\n
        VERSION     : version for this pack\n
        PARENTUUID   : UUID of the parent\n
        PATH        : path to the pack. Can be a directory, a .tar or .tar.gz file\n
    """
    unwind = False
    tmpdir = ""
    try:
        uid = None
        path = path.rstrip("/")
        req = None
        r = None
        md = None
        fndeflist = None
        req_reg = None
        wflist = None
        fndir = None
        path = path.rstrip("/")
        hdrs = get_hdrs()
        query_string = ""
        file = ""

        if not os.path.exists(path):
            raise Exception(f"Path {path} not found.")

        r = requests.get(f"{sc.engine()}/bmprofile/{parentuid}", headers=hdrs, verify=False)
        if not r.ok:
            raise Exception(f"parentuid: {parentuid}, does not exists.")

        bmp_data = r.json()
        state = get_profile_extended_info(bmp_data['config_url'], return_state=True)
        if state != "Ready":
            raise Exception(f"Parent BMP: {parentuid} not ready. Can not add an update")

        if os.path.isfile(path):
            file = path
            if path.endswith("tar") or path.endswith("tar.gz") or path.endswith("tgz"):
                # extract manifest file and validate
                #with tempfile.TemporaryDirectory() as tmpdir:
                tmp = tempfile.TemporaryDirectory()
                tmpdir = tmp.name
                if os.path.isdir(tmpdir):
                    _, err, status = run_command(f"tar -C {tmpdir} -xf {path} manifest.yaml functions")
                    if status:
                        raise Exception(f"""Could not extract manifest.yaml inside pack, error:\n{err}\n.
                        \nPlease ensure that the archive directly opens to * and not a directory/*.
                        \nPlease create tar by:
                            % cd packdir
                            % tar -czvf pack.tgz *
                        """)
                    md = get_manifest_metadata(f"{tmpdir}/manifest.yaml", tmpdir, opn="update")
                    fndir = f"{tmpdir}/functions"
                    wflist = md['workflows']
                    fndeflist = md['functions']
                    validate_bmp_fns(fndeflist, fndir)
                    validate_bmp_wfs(wflist)
                else:
                    raise Exception("Failed to create tmp directory. Please open the tar and specify pack as a directory")
            else:
                print(traceback.format_exc())
                raise Exception("Unknown file compression. Please use .tgz or .tar.gz only for bmprofile pack")
            # Request Engine to validate if this is a valid operation and return us the URL to artifactory
            # where the upload needs to be done
            filename = os.path.basename(path)
            query_string = f"?name={name}&version={version}&filename={filename}"
            req = requests.get(f"{sc.engine()}/bmprofile{query_string}",
                                      allow_redirects=True, verify=False, headers=hdrs)
            print(f"URL: {req.url}")
            req.raise_for_status()
            url = req.json()['redirect_url']
            print(f"Please wait while the BMP is uploaded: {file}")

        elif os.path.isdir(path):
            file = '/tmp/' + next(tempfile._get_candidate_names()) + ".tar.gz"
            filename = os.path.basename(file)
            md = get_manifest_metadata(f"{path}/manifest.yaml", path, opn="update")
            fndir = f"{path}/functions"
            wflist = md['workflows']
            fndeflist = md['functions']
            validate_bmp_fns(fndeflist, fndir)
            validate_bmp_wfs(wflist)

            # Request Engine to validate if this is a valid operation and return us the URL to artifactory
            # where the upload needs to be done. We first validate with engine and then tar the archive. The
            # idea is to fail early.
            query_string = f"?name={name}&version={version}&filename={filename}"
            req = requests.get(f"{sc.engine()}/bmprofile{query_string}",
                                      allow_redirects=True, verify=False, headers=hdrs)
            req.raise_for_status()
            url = req.json()['redirect_url']
            # engine made thumbs up, we now create a tar and upload.
            abspath=os.path.abspath(path)
            print(f"Please wait while the BMP is compressed and uploaded: {file}")
            _, err, status = run_command(f"tar -czvf {file} .", cwd=abspath)
            if status:
                raise Exception(f"Could not create tar archive at {file} from {abspath}, error code: {status}, error: {err}")

        elif path.startswith("git://"):
            print(f"TODO: Git path, to be handled with CI/CD")

        unwind = True
        #print(f"Engine Returned URL: {url}")
        # upload to artifactory
        if not upload_to_robin_artifactory(url, file):
            raise Exception("File upload failed. Please check artifactory logs")
        # proceed to register the kickstart and extract the variable contents out of it
        # which needs to be converted to bare metal profile.
        referred_artifact_urls = []
        extract_http(md['spec'], referred_artifact_urls)
        req_reg, data = register_bmp_profile(name, version, os.path.dirname(url), md, parentuid, desc, referred_artifact_urls)
        #print(f"Returned json: {req_reg.json()}")
        uid = req_reg.json()['id']

        #print("Please wait while the bmp workflows are added")
        if fndir:
            rep_bmp_fn = bmp_add_fns(uid, name, fndeflist, fndir, bmp_name_ver=f"{name}_{version}")
            bmp_add_wfs(name, wflist, fndeflist, fndir, apiversion=md['apiversion'])
        else:
            print("No directory for functions was found. The workflows can not be added to MDCAP.")

        if rep_bmp_fn:
            print(f"Following fn_name:fn_version were already present in mdcap so registered by appending the bmp_uid to the version to maintain the uniqueness:\n  {rep_bmp_fn} \n")

        diff_url, _  = get_profile_update_diff_file(uid, display=False)
        payload = {
            'uid' : uid,
            'parentuid': parentuid
        }
        if diff_url == None:
            r = requests.put(f"{sc.engine()}/bmprofile/profilediff", headers=hdrs, data=payload, verify=False)
            if r.ok:
                get_profile_update_diff_file(uid, False)
                print(f"Successfully created change set between profile (this): {uid} and parent: {parentuid}")
            else:
                print(f"Could not create the change set. This may happen if the BMP is still busy in processing. You can retry when the processing is done. \nTo check bmp status: mdcap bmp info {uid}")
        else:
            print(f"Successfully created change set between profile: {uid} and parent: {parentuid}")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to register BMP {}. ".format(name), exit=False)
        if unwind == True:
            _delete_bmp(uid)

    finally:
        if os.path.isdir(path) and os.path.isfile(file):
            os.unlink(file)

        if path.endswith("tar") or path.endswith("tar.gz") or path.endswith("tgz"):
            if os.path.isfile(tmpdir):
                os.unlink(tmpdir)

        if kwargs.get('urlinfo'):
            if req:
                compute_curl_command(req, headers=hdrs)

            if req_reg:
                compute_curl_command(req_reg, headers=hdrs, data=data)

            if r:
                compute_curl_command(r, headers=hdrs, data=payload)


@bmprofilepack.command()
@click.argument('uid', type=str)
@click.argument('parentuid', type=str)
@add_options(common_options)
def makediff(uid, parentuid, **kwargs):
    """Extracts the difference, change-set, between uuid and its parent and saves this in a file.
        Later BMP update workflows use this information to bring the change in the BMs.\n
        UID         : UUID of update BMP\n
        PARENTUID   : parent's UUID
    """
    try:
        hdrs = get_hdrs()
        this = requests.get(f"{sc.engine()}/bmprofile/{uid}", headers=hdrs, verify=False)
        if not this.ok:
            raise Exception (f"uid: {uid}, does not exists.")

        p = requests.get(f"{sc.engine()}/bmprofile/{parentuid}", headers=hdrs, verify=False)
        if not p.ok:
            raise Exception(f"parentuid: {parentuid}, does not exists.")

        payload = {
            'uid' : uid,
            'parentuid': parentuid
        }
        r = requests.put(f"{sc.engine()}/bmprofile/profilediff", headers=hdrs, json=payload, verify=False)
        if r.ok:
            get_profile_update_diff_file(uid, False)
            print(f"Successfully created change set between profile (this): {uid} and parent: {parentuid}")
        else:
            print(f"Could not create the change set. This may happen if the BMP is still busy in processing.")
            print(f" You can retry, once the processing is done. To check bmp status: mdcap bmp info {uid}.")
            print( f"Status: {r.status_code}")


    except Exception as ex:
        handle_error(ex, action_msg="Failed to create change-set. ")

    finally:
        if kwargs.get('urlinfo'):
            if r:
                compute_curl_command(r, headers=hdrs, data=payload)

def make_filename(pwd, tmpname):
    if not os.path.isfile(pwd + "/" + tmpname):
        return tmpname
    for i in range(1,100):
        filename=f"{i}." + tmpname
        if not os.path.isfile(pwd + "/" + filename):
            break
    return filename

@bmprofilepack.command()
@click.argument('uid', type=str)
@click.option("-s","--source", is_flag=True, help="Download BMP's original manifest.yaml")
@click.option('-a', "--artifact", multiple=True, type=str, help="Download artifact e.g -a config/test.conf; use '-a all' for all BMP")
@add_options(common_options)
def download(uid, source, artifact, **kwargs):
    """ Download files from BMP """
    try:
        req = None
        hdrs = get_hdrs()
        url = ""
        url_endpoint = ""
        query_string = ""
        tgt_filename = ""
        if "all" in artifact and len(artifact) > 1:
            raise Exception("there should be no other value for artifact when 'all' is specified.")

        req = requests.get(f"{sc.engine()}/bmprofile/{uid}", headers=hdrs, verify=False)
        if req.ok:
            url = req.json()['config_url']
        else:
            raise Exception(f"uid: {uid}, does not exists.")
        url_endpoint = "manifest.local.yaml"
        if source:
            url_endpoint = "manifest.yaml"
        tgt_filename = url_endpoint
        if artifact:
            tgt_filename = ".tgz"
            if artifact == "all":
                query_string = "?download=all"
            else:
                only_once=True
                for file in artifact:
                    if only_once == True:
                        query_string += "?"
                        only_once = False
                    query_string += f"download={file}&"
        query_string = query_string.rstrip("&")
        req = requests.get(url + "/" + url_endpoint + query_string, verify=False, headers=hdrs)
        if req.ok:
            cwd = os.getcwd()
            tmpf_prefix=os.path.basename(url) + tgt_filename
            with tempfile.NamedTemporaryFile(prefix=tmpf_prefix, dir=os.getcwd(), delete=False) as temp:
                temp.write(req.content)
                temp.flush()
                filename = make_filename(cwd, tmpf_prefix)
                os.rename(temp.name, filename)
                print(f"Saved as: {filename}")
        else:
            raise Exception(f"Could not download BMP data, artifactory server returned: {req.status_code}")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to download file(s)")

    finally:
        if kwargs.get('urlinfo'):
            if req:
                compute_curl_command(req, headers=hdrs)

