@bmprofilepack.command()
@click.argument('uid', type=str)
@click.argument('parentuid', type=str)
@add_options(common_options)
def listdirdiff(uid, parentuid, **kwargs):

    """Extracts the directory structure difference between uuid and its parent and saves this in a file.\n
       UID         : UUID of update BMP\n
       PARENTUID   : parent's UUID
    """
    try:
        req = None
        req_af = None
        hdrs = get_hdrs()
        alldir = []

        for bmp in [uid, parentuid]:
            req = requests.get(f"{sc.engine()}/bmprofile/{bmp}", headers=hdrs, verify=False)
            req.raise_for_status()
            data = req.json()
            dir_data = requests.get(data['config_url'] + "/ls", allow_redirects=True, verify=False, headers=hdrs)
            if dir_data.ok:
                vector = {}
                for item in dir_data.json().get('items').split('\n'):
                    key = item[:item.rfind("-")]
                    value = item.split("-")[-1]
                    vector[key] = value
                alldir.append(vector)
            else:
                raise Exception(f"Unable to get directory information for bmp : {bmp} ")

        dirlist = alldir[0]
        parentdirlist = alldir[1]

        add = []
        sub = []
        modified = []

        for entry in parentdirlist:
            if dirlist.get(entry , '') and dirlist.get(entry) != parentdirlist[entry]:
                modified.append(entry)
            elif not dirlist.get(entry , ''):
                sub.append(entry)

        for entry in dirlist:
            if not parentdirlist.get(entry, ''):
                add.append(entry)

        data = {}
        data["Files added to second version of bmp are :"] = add
        data["Files subtracted from second version of bmp are :"] = sub
        data["Files modified in second version of bmp are :"] = modified
        for key in data:
            print(f"{'=' * 30}")
            print(key)
            print(f"{'=' * 30}")
            for file in data.get(key):
                print(f"{file}")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to list file(s)")

    finally:
        if kwargs.get('urlinfo'):
            if req:
                compute_curl_command(req, headers=hdrs)
            if req_af:
                compute_curl_command(req_af, headers=hdrs)


@bmprofilepack.command()
@click.argument('uid', type=str)
@click.argument('parentuid', type=str)
@click.argument('artifact', type=str)
@add_options(common_options)
def filediff(uid, parentuid, artifact, **kwargs):
    """Opens a editor to differentiate between a given file of a bmpp and its parent_bmpp.\n
       UID         : UUID of update BMP\n
       PARENTUID   : parent's UUID\n
       Artifact    : The path to artifact for which the difference needs to be seen ex: -a config/test.conf
    """
    try:
        req = None
        hdrs = get_hdrs()
        url = ""
        parenturl = ""

        req = requests.get(f"{sc.engine()}/bmprofile/{uid}", headers=hdrs, verify=False)
        if req.ok:
            url = req.json()['config_url']
        else:
            raise Exception(f"uid: {uid}, does not exists.")
        req = requests.get(f"{sc.engine()}/bmprofile/{parentuid}", headers=hdrs, verify=False)
        if req.ok:
            parenturl = req.json()['config_url']
        else:
            raise Exception(f"uid: {parentuid}, does not exists.")
        if not artifact:
            raise Exception(f"Provide the file name")
        data = {uid:url , parentuid:parenturl}
        filenames = []
        for key in data:
            req = requests.get(data[key] + "/" + artifact, verify=False, headers=hdrs)
            if req.ok:
                cwd = os.getcwd()
                tmpf_prefix = key + "-" + artifact.split("/")[-1]
                print(tmpf_prefix)
                with tempfile.NamedTemporaryFile(prefix=tmpf_prefix, dir=os.getcwd(), delete=False) as temp:
                    temp.write(req.content)
                    temp.flush()
                    filename = make_filename(cwd, tmpf_prefix)
                    filenames.append(filename)
                    os.rename(temp.name, filename)
                    print(f"Saved as: {filename}")
            else:
                raise Exception(f"Could not download BMP data for bmp : {key}, artifactory server returned: {req.status_code}")
        try:
            os.system(f"vimdiff {filenames[0]} {filenames[1]}")
        except Exception as ex:
            raise Exception(f"Unable to show diff between the files due to : {ex}")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to download file(s)")

    finally:
        if kwargs.get('urlinfo'):
            if req:
                compute_curl_command(req, headers=hdrs)


@bmprofilepack.command()
@click.argument('uid', type=str)
@click.argument('file', type=str)
@add_options(common_options)
def edit(uid, file, **kwargs):
    """ Edit a file in BMP\n

        UID: UID of the BMP\n

        FILE: path of the file relative to the URL
    """
    try:
        r = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/bmprofile/{uid}", headers=hdrs, verify=False)
        r.raise_for_status()
        data = r.json()
        name_version = f"{data['name']}_{data['version']}"
        r = requests.get("{}/bm?labels=mdcap/profile:{}&total=True".format(sc.engine(), name_version), headers=hdrs, verify=False)
        r.raise_for_status()
        result = r.json()
        if result['count'] != 0:
            print("Edit not allowed as the BMP is used in following BM(s).")
            for item in result['items']:
                print(item['metadata']['name'])
            return
        if file == "manifest.yaml":
            file = "manifest.local.yaml"
        file_url = data['config_url'] + "/" + file
        ext = file.split(".")[-1]
        res = requests.get(file_url, allow_redirects=True, verify=False, headers=hdrs)
        if res.ok:
            contents = res.content.decode('utf-8')
            mod = open_in_editor("", content=contents, edit_fmt=ext, artifactory_flag=True)
            if not mod:
                return
        tmpfile = f"/tmp/{time.time()}"
        # writing python object to tmp file was giving issues. Dedicated creating
        # and writing the yaml file worked.
        if ext == "yaml":
            with open(tmpfile, "w") as yf:
                yaml.dump(mod, yf, default_flow_style=False)
            if not upload_to_robin_artifactory(file_url, tmpfile):
                raise Exception(f"Could not upload file")
            os.unlink(tmpfile)
        else:
            with tempfile.NamedTemporaryFile(suffix=".tmp") as t:
                t.write(bytes(mod))
                t.flush()
                if not upload_to_robin_artifactory(file_url, t.name):
                    raise Exception(f"Could not upload file")
        print("File edited successfully")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to edit and upload file")

    finally:
        if kwargs.get('urlinfo'):
            if r:
                compute_curl_command(r, headers=hdrs)

