@func.command(aliases=['register','add'])
@click.argument('name', type=str)
@click.argument('version', type=str)
@click.argument('operator', type=str)
@click.option('--cmd', '-c', type=str, help="Command to be run as part of the Function.")
@click.option('--script', '-s', type=str, help="Script to be run as part of the Function.")
@click.option('--desc', '-d', type=str, help="Description of the Function.")
@click.option('--envs', type=str, help="Comma seperated list of environment variables needed by the specified script.")
@click.option('--fanout', '-n', type=int, help="Fanout factor to be used with this function")
@click.option('--action', '-a', type=str, help="Action type: mutable or default")
@click.option('--tar', type=bool, help="Files to be placed in execution environmnet of entry")
@click.option('--kinds', '-e', '-k', required=True, multiple=True, help="Valid element kinds for this function")
@click.option('--upload', is_flag=True, help="upload the script while adding, without script present error is thrown")
@click.option('--mode', '-m', required=True, default="unit",
              type=click.Choice(['unit', 'batch'], case_sensitive=False),
              help="Valid function modes ('unit', 'batch')")
@click.option('--mem_size', '-ms', required=False, type=int,
              help="Memory size for required worker in bytes")
@click.option('--cpu', '-cpu', required=False, type=float,
              help="Number of cpus required for worker")
@click.option('--timeout', '-t', required=False, type=int,
              help="Timeout for the function to exit, for 1 element")
@click.option('--runtime', '-r', required=False, type=str,
              help="Executor image which this function will use")
@click.option('--returnid', required=False, is_flag=True,
              help="Flag for internal cli-api usage")
@click.option('--abstract-reference', '-ar', required=False, type=str,
              help="Name of abstract function")
@click.option('--is-abstract', '-ia', required=False, is_flag=True,
              help="Function is an abstract function")
@click.option("-sl", "--selectors", type=str, multiple=True, help="Add selectors to help with grouping and filtering. Format: key1:val1,key2val2...")
@click.option("--remote", is_flag=True, default=False, help="Mark function as remote (runs on target cluster workers)")
@add_options(common_options)
def add(name, version, operator, cmd, script, kinds, desc,
        envs, fanout, action, tar, upload, mode, mem_size, cpu,
        timeout, runtime, abstract_reference, is_abstract, selectors, returnid, remote, **kwargs):
    """Add a function"""
    try:
        r = None
        hdrs = get_hdrs()
        tar = 1 if tar else 0
        if not timeout:
            timeout = 0
        data = {
            'name': name,
            'version': version,
            'operator': operator,
            'etypes': kinds,
            'description': desc,
            'envs': envs if envs else "",
            'fanout': fanout,
            'action': action if action else 'default',
            'tar': tar,
            'mode': 0 if mode.lower() == 'unit' else 1,
            'mem_size': mem_size,
            'cpu': cpu,
            'timeout': timeout,
            'runtime': runtime,
            'abstract': abstract_reference if abstract_reference else '',
            'is_abstract': is_abstract,
            'selectors': parse_labels(selectors, ret_dict=True),
            'remote': remote,
        }
        if script:
            if not os.path.exists(script) and not is_abstract:
                raise Exception(f"Not Found: {script}")
            data['script'] = script.split('/')[-1]
        if cmd:
            data['cmd'] = cmd

        if not cmd and not script and not is_abstract:
            raise Exception("CMD or SCRIPT are required, if its a abstract function then provide --is-abstract and --upload flag.")
        elif cmd and script:
            raise Exception("Only one of CMD or SCRIPT can be specified.")
        else:
            if upload:
                try:
                    # if fn is abstract and user provides script file.
                    if script and os.path.exists(script):
                        files = {'file': (script.split('/')[-1], open(script, 'rb'))}
                    # if abs fn and user gives only script name then create script file with own content,
                    # if no script name given derive script name from abs_fn name
                    elif not cmd:
                        if not script:
                            script = f"{name}.py"
                            data['script'] = script.split('/')[-1]
                        with open(f"/tmp/{script.split('/')[-1]}", "w") as absfile:
                            absfile.write(str(uuid.uuid4()))
                        files = {'file': (script.split('/')[-1], open(f"/tmp/{script.split('/')[-1]}", 'rb'))}
                    r = requests.post(f"{sc.engine()}/fn/upload", files=files, headers=hdrs, verify=False)
                    r.raise_for_status()
                    data['uid'] = r.json()['fn_uids']
                except Exception as e:
                    handle_error(e, action_msg=f"Failed to upload file: {script}")
                    return

        r = requests.post(f"{sc.engine()}/fn", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])

        if returnid:
            manifest_file = os.path.join(os.getcwd(), "manifest.yaml")
            if not os.path.isfile(manifest_file):
                raise Exception('Manifest.yaml not present function upload may fail during further attempts')
            function_uid = r.json()['msg'].split(" ")[6]
            with open(manifest_file, "r") as fh:
                manifestData = yaml.safe_load(fh)
            manifestData['spec']['function_uid'] = function_uid
            with open(manifest_file, "w") as fh:
                yaml.safe_dump(manifestData, fh)
    except Exception as ex:
        # if "not fetch" in ex:
        #     click.secho("Try adding --upload", fg="red")
        handle_error(ex, action_msg="Failed to add function {}. ".format(name))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

