@func.command()
@click.option('-k', "--kind", type=str, help="Option to filter Functions based on the kinds they operate on.")
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option('-m', '--match', type=str, help="Partial filter match on uid, name, source")
@click.option("-v", "--verbose", is_flag=True)
@click.option("-a", "--abstract", is_flag=True)
@click.option("--remote", is_flag=True, default=None, help="Filter to show only remote functions")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("-t", "--display_timestamp", is_flag=True, help="Display creation and updation times")
@add_options(common_options)
def list(kind, index, match, verbose, abstract, remote, output, display_timestamp=False, **kwargs):
    """List all functions"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        q_params = [limit, offset]
        if match:
            q_params.append("match={}".format(match))
        if kind:
            q_params.append("etype={}".format(kind))
        if abstract:
            q_params.append("abstract=true")
        if remote:
            q_params.append("remote=true")
        limit_url = parameter_string(q_params)
        url = "{}/fn{}".format(sc.engine(), limit_url)

        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        results = r.json()
        if not results['items']:
            print("No results found")
            return
        if verbose:
            for item in results['items']:
                item['hash'] = item['hash'][0:6]
            #hdrs = ['uuid', 'name', 'version', 'operator', 'cmd', 'source', 'etypes', 'desc', 'ENV variables', 'reserved ENV variables', 'fanout']
            print(tabulate(results['items'], headers="keys"))
        else:
            table_hdrs = ['uid', 'name', 'version', 'operator', 'mode', 'source', 'types', 'fanout', 'mem_size', 'cpu', 'timeout', 'runtime', 'action', 'remote', 'abs', 'abs_ref', 'selectors']
            if display_timestamp:
                table_hdrs.append('ctime')
                table_hdrs.append('mtime')
            vals = []
            for item in results['items']:
                entry = [item['uid'],
                            item['name'],
                            item['version'],
                            item['operator'],
                            item['mode'],
                            item['source'],
                            item['types'],
                            item['fanout'],
                            item['mem_size'],
                            item['cpu'],
                            item['timeout'],
                            item['runtime'],
                            item['action'],
                            't' if item.get('remote') else 'f',
                            '-' if item['abstract'] else 'y',
                            item['abstract'] if item['abstract'] and item['abstract'] != item['uid'] else '-',
                            item['selectors']]
                if display_timestamp:
                    entry.append(datetime.fromtimestamp(int(item['ctime'])))
                    entry.append(datetime.fromtimestamp(int(item['mtime'])))
                vals.append(entry)
            print(tabulate(vals, headers=table_hdrs))

    except Exception as ex:
        handle_error(ex, action_msg="Failed to list functions. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


@func.command()
@click.argument("uid", type=str)
@click.argument("key", type=click.Choice(['script', 'operator', 'runtime', 'mode',
                        'envs', 'fanout', 'mem_size', 'cpu', 'timeout', 'abstract',
                        'selectors', 'lockdetails', 'kinds']))
@click.argument("value", type=str)
@click.option("-v", "--version", type=str, help="new version of the function")
@click.option("-uwf", "--update_wfs", is_flag=True, help="Update all existing workflows with this function")
@add_options(common_options)
def update(uid, key, value, version, update_wfs, **kwargs):
    """Update a function script already registered \n
        UID: uid of the already registered fn \n
        KEY: Param of fn to update \n
        VALUE: Value or fn param \n
        script: str (path/to/script) \n
        operator: shell|ssh \n
        kinds: Valid element kinds for this function (Format: bm,vm,..[comma separated, no spaces])
        runtime: str (docker img) \n
        mode: 1|0  (batch|unit) \n
        envs: comma separated str \n
        fanout: int \n
        mem_size: int (mb) \n
        cpu: float \n
        timeout: int (seconds) \n
        abstract: string \n
        selectors: string (Format: key1:val1,key2val2...")
        """
    try:
        r = None
        payload = {}
        hdrs = get_hdrs()
        errmsg = None
        r = requests.get(f"{sc.engine()}/fn/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        fn_conf = r.json()
        if key == 'script':
            errmsg = "Failed to upload new script for fn: {}. ".format(uid)
            script = value
            files = {}
            with open(script, 'rb') as f:
                files[fn_conf['uid']] = (os.path.basename(script), f.read())
            r = requests.post(f"{sc.engine()}/fn/upload?update=true", headers=hdrs, files=files, verify=False)
            r.raise_for_status()
            print("Upload complete, script is updated.")
        else:
            fn_conf[key] = value
            if key == 'selectors':
                value = parse_labels([value], ret_dict=True)
            payload = {
                "config": {
                    key: value
                }
            }
            r = requests.put(f"{sc.engine()}/fn/{uid}", headers=hdrs, data=json.dumps(payload), verify=False)
            r.raise_for_status()
            print(r.text)
    except Exception as ex:
        handle_error(ex, action_msg=errmsg if errmsg else "Failed to update fn: {}. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)


@func.command()
@click.option('--runtime', '-r', required=False, type=str, help="Runtime of the function to be updated")
@click.option('--uid', '-u', required=False, type=str, help="UID of the function to be updated")
# @click.option('--mem_size', '-ms', required=False, type=int, help="Update memory size for required worker in bytes")
# @click.option('--cpu', '-cpu', required=False, type=float, help=" Update number of cpus required for worker")
@add_options(common_options)
def update_cpu_mem(runtime, uid, mem_size=0, cpu=0, **kwargs):
    """Update a cpu, memory of function  already registered \n
        Runtime: Runtime of the already registered fn \n
        UID : UID of registered fn \n
        """
    try:
        r = None
        payload = {}
        hdrs = get_hdrs()
        errmsg = None
        ex = None

        if not runtime and not uid:
            errmsg = "Failed to update fn"
            raise Exception("Either a function runtime or UID must be specified.")

        elif runtime:
            payload = {"runtime" : runtime}

        else:
            payload = {"uid" : uid}
        payload.update({"config" : {"cpu" : cpu,"mem_size" : mem_size}})
        r = requests.put(f"{sc.engine()}/fn/update/cpu-mem", headers=hdrs, data=json.dumps(payload), verify=False)
        r.raise_for_status()
        print(r.text)
    except Exception as ex:
        handle_error(ex, action_msg=errmsg if errmsg else "Failed to update fns with runtime/uid : {}. ".format(runtime))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)

