@workerprofile.command("add")
@click.option("--img", type=str, help="Image name for the workerprofile")
@click.option("--script_name", type=str, help="Script name for which workerprofile is to be added")
@click.option("--version", type=str, help="Version of the script")
@click.option("--mem", "-m", type=str)
@click.option("--cpu", "-c", type=float)
@click.option("--max-workers", "-w", type=int, help="Max worker count")
@click.option("-py", "--partialyaml", type=str, help="yaml with volumes/volumemounts/secrets/envs/cms/annotations/labels")
@click.option("--cluster-uid", type=str, default=None, help="Cluster UID to bind this worker profile to")
@add_options(common_options)
def add_wp(img, script_name, version, mem, cpu, max_workers, partialyaml, cluster_uid, **kwargs):
    '''Register a new Persistent Worker profile'''
    try:
        r = None
        hdrs = get_hdrs()
        partial_yaml = {}
        if partialyaml:
            with open(partialyaml, 'r') as f:
                partial_yaml = yaml.safe_load(f)
        data = {
            "partial_yaml": partial_yaml
        }
        if max_workers:
            data["max_worker_cnt"] = max_workers
        if cpu:
            data["cpu"] = cpu
        if mem:
            data["mem"] = convert_readable_to_bytes(mem)
        if script_name:
            data["script_name"] = script_name
            if version:
                data["version"] = version
        if img:
            data["img"] = img
        if cluster_uid:
            data["cluster_uid"] = cluster_uid
        if not script_name and not img:
            raise Exception("script_name or img is required argument")
        r = requests.post(f"{sc.engine()}/taskprofile", verify=False, json=data, headers=hdrs)
        r.raise_for_status()
        results = r.json()
        print(f"Worker profile {results['id']} has been registered")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to register worker profile. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)


