@batch.command()
@click.option("--interval", type=int, help="Time limit in seconds for which stats needs to be fetched")
@add_options(common_options)
def exec_stats(interval, **kwargs):
    """Retrieve batch execution statistics"""
    try:
        r = None
        hdrs = get_hdrs()
        q_params = ""
        if interval:
            q_params = f"?interval={interval}"

        r = requests.get(f"{sc.engine()}/stats/batch_exec{q_params}", verify=False, headers=hdrs)
        r.raise_for_status()
        results = r.json()
        tbl_hdrs = ['stat time', 'queued', 'inprogress', 'paused', 'success', 'failed', 'other', 'total']
        if not results or results['count'] == 0:
            print("Batch execution stats records not found.")
            return

        print()
        print(f"Total stats: {results['count']}")
        print()
        data = []
        for stat in results['stats']:
            queued = next((st["count"] for st in stat['data']['summary'] if st["status"]=="queued"), 0)
            inprogress = next((st["count"] for st in stat['data']['summary'] if st["status"]=="inprogress"), 0)
            paused = next((st["count"] for st in stat['data']['summary'] if st["status"]=="paused"), 0)
            success = next((st["count"] for st in stat['data']['summary'] if st["status"]=="success"), 0)
            failed = next((st["count"] for st in stat['data']['summary'] if st["status"]=="failed"), 0)
            other = stat['data']['total'] - (queued+inprogress+paused+success+failed)
            data.append([datetime.fromtimestamp(int(stat['ctime'])), queued,
                inprogress, paused, success, failed, other, stat['data']['total']])
        print(tabulate(data, headers=tbl_hdrs))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to get batch execution stats")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@batch.command()
@click.argument('batchid', type=str)
@click.option('--jsonfile', type=click.Path(exists=True))
@click.option('--pool-ids', '-p', type=str, help="Optional poolids to rerun batch")
@click.option('--allpools', '-a', is_flag=True, help="Rerun all pools in the batch(not just failed ones)", default=False)
@click.option('--fanout', '-s', type=int, help="Fan out value for batch rerun.")
@click.option('--pool-range', '-r', type=str, help="Option to rerun a range of pools. Can be specified as <start_pool>:<end_pool>.")
@click.option('--cpu','-c',type=float, help= "Number of CPUs for batch rerun")
@click.option('--mem-size','-m',type=int, help= "Memory value for batch rerun in bytes")
@click.option('--dockerimg', '-d', required=False, type=str, help="Executor image that batch will use")
@click.option('--validate-elements', '-v', is_flag=True, \
    help="Validate batch elements to be present. Fail if one or more elements are not found.", default=False)
@click.option('-c',"--customid", is_flag= True, help="If customid is provided instead of batchid for batch info",default=False)
@click.option('--batchpriority', '-bp', type=str, help="Batch priority for batch.")
@add_options(common_options)
def rerun(batchid, jsonfile, pool_ids, allpools, fanout, pool_range, cpu, mem_size, dockerimg, validate_elements, customid, batchpriority, **kwargs):
    '''Rerun the batch'''
    try:
        r = None
        hdrs = get_hdrs()
        url = f"{sc.engine()}/batch/{batchid}/rerun"
        q = []
        min_value, max_value = min_max_from_range(pool_range, 'minpool', 'maxpool')
        if min_value and max_value:
            q.append(min_value)
            q.append(max_value)
        if pool_ids:
            for poolid in pool_ids.split(','):
                q.append(f"poolid={poolid}")
        if allpools:
            q.append(f"allpools={allpools}")
        if fanout:
            q.append(f"fanout={fanout}")
        if validate_elements:
            q.append(f"validate_elements={validate_elements}")
        if customid:
            q.append("idtype=customid")
        if q:
            url += f"?{'&'.join(q)}"

        payload = {}
        if jsonfile:
            payload = read_json_file(jsonfile)
        if cpu:
            payload['cpu'] = cpu
        if mem_size:
            payload['mem_size'] = mem_size
        if dockerimg:
            payload['dockerimg'] = dockerimg
        if batchpriority:
            payload['batch_priority'] = batchpriority
        r = requests.put(url, json=payload, verify=False, headers=hdrs)
        r.raise_for_status()
        resp = r.json()
        print(json.dumps(resp))
    except Exception as ex:
        handle_error(ex, "Failed to rerun batch. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)


