@batch.command()
@click.argument('batchid', type=str)
@click.option('-c',"--customid", is_flag= True, help="If customid is provided instead of batchid for function script",default=False)
@add_options(common_options)
def downloadfn(batchid, customid,**kwargs):
    '''Download function from a batch'''
    try:
        r = None
        hdrs = get_hdrs()
        q = ""
        if customid:
            q = "?idtype=customid"
        r = requests.get(f"{sc.engine()}/batch/{batchid}{q}", verify=False, headers=hdrs)
        result = r.json()
        if not result:
            print("No results found")
            return
        uid = result['fn_uid']
        res = requests.get(f"{sc.engine()}/fn/{uid}?artifact=true", verify=False, headers=hdrs)
        resp = res.json()
        if res.ok:
            path = f'/tmp/rorc-fn-{uid}'
            with open(path, "wb") as fh:
                fh.write(resp['file'].encode('utf-8'))
            print(f"Dumped the function to '{path}'")
        else:
            raise Exception(f"Failed to download function. {r.text}")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to download function. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)
            if kwargs.get('urlinfo') and res:
                compute_curl_command(res, headers=hdrs)

@batch.command()
@click.argument('batchid', type=str)
@click.option('--workerid', '-w', type=str, help="Specify worker id to see worker logs")
@click.option('--element-uid', '-e', type=str, help="Specify element uid to see element logs [required to fetch boot logs]")
@click.option('-b', '--bootlogs', is_flag=True, help="(for VM boot) Fetch the boot logs instead of batch logs", default=False)
@click.option('-c','--customid', is_flag=True, help="If customid is provided instead of batchid for batch logs",default=False)
@click.option('-d','--download', is_flag=True, help="Downloads the log file instead of streaming",default=False)
@click.option('-o','--ofile', type=str, help="Save downloaded output to file", default=None)
@click.option('-l','--list', is_flag=True, help="Shows the list of logs for a batch and element-uid",default=False)
@click.option('--logfile', type=str, help="Specify logfile name instead of default function logs", default=None)
def logs(batchid, workerid, element_uid, bootlogs, customid, download, ofile, **kwargs):
    '''Stream or download batch logs'''
    def _helper(response):
        if ofile:
            with open(ofile, "w") as fh:
                fh.write(response.text)
        else:
            print(response.text)
    def _stream_helper(response):
        for line in response.iter_content(chunk_size=512):
            # filter out keep-alive new lines
            if line:
                decoded_line = line.decode('utf-8', errors='replace')
                print(decoded_line,flush=True,end="")
    try:
        if not workerid and not element_uid:
            print("Please specify either workerid or element uid to see the logs")
            return
        hdrs = get_hdrs()
        content, stream = "stream", True
        if download:
            content, stream = "download", False
        qp = f"?content={content}"
        if customid:
            qp = qp + "&idtype=customid"
        if workerid:
            qp = qp + f"&workerid={workerid}"
        elif element_uid:
            qp = qp + f"&element_uid={element_uid}"

        if kwargs.get('list') or kwargs.get('logfile'):
            pass
        elif bootlogs:
            if not element_uid:
                raise Exception("--bootlogs cannot be passed without --element-uid")
            qp = qp + f"&bootlogs={bootlogs}"

        # Fetch the logstore URL from the engine
        engine_res = requests.get(f"{sc.engine()}/batch/logs/{batchid}{qp}", verify=False, headers=hdrs)
        engine_res.raise_for_status()
        log_url = engine_res.json()['url']

        if element_uid and kwargs.get('list'):
            lres = requests.get(os.path.dirname(log_url), verify=False, headers=hdrs, stream=stream)
            log_list = lres.text.split(',')
            for _item in log_list:
                if not _item.startswith(element_uid) or not _item.endswith('.log'):
                    continue
                print(_item)
            return
        elif element_uid and kwargs.get('logfile'):
            log_url = os.path.dirname(log_url).rstrip('/') + "/" + kwargs['logfile']

        logstore_res = requests.get(log_url, verify=False, headers=hdrs, stream=stream)
        if logstore_res.status_code == 404:
            if not bootlogs: 
                msg = f"No log files found for batch {batchid}."
            else:
                msg = f"No boot logs found for batch {batchid}. Please check if it is a compatible batch for boot logs, or fetch only the batch logs."
            raise Exception(msg)
        logstore_res.raise_for_status()

        if download and logstore_res:
            _helper(logstore_res)
            if ofile:
                msg = f"Logs downloaded to: {os.path.abspath(ofile)}"
                print(f"{msg}")
        else:
            _stream_helper(logstore_res)
    except Exception as ex:
        handle_error(ex)


