@batch.command()
@click.option("-t", "--type", type=click.Choice(["function", "workflow", "dockerimg", "element_tags", "envs", "envs_per_element", "others"]), default="function")
@click.option("-o", "--output", help="Save the template to a file")
def gentpl(type, output):
    '''Provides batch execution templates'''
    try:
        type = type.lower()
        if type == "function":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "function": "uuid",
                "elements": ["uuid1", "uuid2", "uuid3"],
                "etype": "VM",
                "fanout": 1
            }
        elif type == "workflow":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "workflowid": "uuid",
                "elements": ["uuid1", "uuid2", "uuid3"],
                "etype": "VM",
                "fanout": 1
            }
        elif type == "dockerimg":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "dockerimg": "foo/bar:1.2",
                "elements": ["uuid1", "uuid2", "uuid3"],
                "etype": "VM",
                "fanout": 1
            }
        elif type == "element_tags":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "function": "uuid",
                "labels": {"location": "nyc", "site": "east-2"},
                "etype": "VM",
                "fanout": 1
            }
        elif type == "envs":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "function": "uuid",
                "elements": ["uuid1", "uuid2", "uuid3"],
                "etype": "VM",
                "fanout": 1,
                "env": {
                    "key1": "value1",
                    "key2": "value2"
                }
            }
        elif type == "envs_per_element":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "function": "uuid",
                "elements": ["uuid1", "uuid2"],
                "etype": "VM",
                "fanout": 1,
                "env": {
                    "uuid1": {
                        "key1": "value1",
                        "key2": "value2"
                    },
                    "uuid2": {
                        "key1": "value1",
                        "key2": "value2"
                    }
                }
            }
        elif type == "others":
            data = {
                "name": "batch-1",
                "batch_id": "batch1",
                "function": "uuid",
                "mem_size": 104857600,
                "cpu": 1,
                "customid": "foobar",
                "elements": ["uuid1", "uuid2", "uuid3"],
                "etype": "VM",
                "fanout": 1,
                "prioritylane": "gold"
            }
        if output:
            with open(output, "w") as fh:
                fh.write(json.dumps(data, indent=4))
            print(f"Batch execution template of type '{type}' is saved to {output}")
        else:
            print(json.dumps(data, indent=4))
    except Exception as e:
        print("Error generating/saving batch execution template: {}".format(str(e)))

