@tenant.command()
@click.argument('uid', type=str)
@click.option("-y", "--yes", is_flag=True, help="confirm yes, non-interactive", default=False)
@add_options(common_options)
def delete(uid, yes, **kwargs):
    """Delete a tenant"""
    try:
        r = None
        check_uid(uid)
        if not yes:
            val = input(f"Confirm tenant delete? [y/n] ")
            if val.lower() not in ['y', 'yes']:
                print("Tenant not deleted")
                sys.exit(0)
        hdrs = get_hdrs()
        r = requests.delete("{}/tenant/{}".format(sc.engine(), uid),
                         allow_redirects=True, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.text)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to delete tenant. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


@tenant.command()
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option('--all', is_flag=True, help="Fetch all tenants", default=False)
@click.option("--chargeback", is_flag=True, default=False, help="Include chargeback data for all tenants")
@click.option("-s", "--start-date", type=str, default=None, help="Chargeback start date (yyyy-mm-dd)")
@click.option("-e", "--end-date", type=str, default=None, help="Chargeback end date (yyyy-mm-dd)")
@add_options(common_options)
def list(output, chargeback, start_date, end_date, **kwargs):
    """List all tenants"""
    try:
        r = None
        hdrs = get_hdrs()
        if chargeback:
            params = []
            if start_date:
                params.append(f"start_date={start_date}")
            if end_date:
                params.append(f"end_date={end_date}")
            url = f"{sc.engine()}/tenant/chargeback"
            if params:
                url += "?" + "&".join(params)
            r = requests.get(url, verify=False, headers=hdrs)
            r.raise_for_status()
            if output == 'yaml':
                print(yaml.dump(r.json(), indent=4))
                return
            print(json.dumps(r.json(), indent=4))
            return
        url = f"{sc.engine()}/tenant"
        if kwargs.get('all'):
            url += "?include_dummy=true"
        r = requests.get(url, allow_redirects=True, verify=False, headers=hdrs)
        r.raise_for_status()
        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        # Convert ctime from epoch to human-readable timestamp
        data = r.json()
        for tenant in data:
            ctime_val = tenant[5]
            if isinstance(ctime_val, (int, float)):
                tenant[5] = datetime.fromtimestamp(int(ctime_val))

        tbl_hdrs = ['uid', 'name', 'type', 'clientid', 'chargeback_multiplier', 'ctime']
        print(tabulate(data, headers=tbl_hdrs, tablefmt="pretty"))

    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@tenant.command()
@click.argument('uid', type=str)
@click.option("-e", "--elements", is_flag=True, help="Get list of elements assigned to the tenant")
@click.option("--chargeback", is_flag=True, default=False, help="Include chargeback data for the tenant")
@click.option("--start-date", type=str, default=None, help="Chargeback start date (yyyy-mm-dd)")
@click.option("--end-date", type=str, default=None, help="Chargeback end date (yyyy-mm-dd)")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def info(uid, elements, chargeback, start_date, end_date, output, **kwargs):
    """Get information about a particular tenant"""
    try:
        r = None
        hdrs = get_hdrs()
        params = []
        if elements:
            params.append("get_elements=true")
        if chargeback:
            params.append("chargeback=true")
        if start_date:
            params.append(f"start_date={start_date}")
        if end_date:
            params.append(f"end_date={end_date}")
        url = f"{sc.engine()}/tenant/{uid}"
        if params:
            url += "?" + "&".join(params)
        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        resp = r.json()
        print(resp)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to find information about tenant with uid {}".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

