@cli.group(cls=ClickAliasedGroup)
def iam():
    """IAM Credentials Management"""
    pass

@iam.command()
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option('-t', "--type", 'kind', type=str, help="Filter by type")
@click.option('-e', "--elemref", 'elemref', type=str, help="Filter by elemref")
@click.option('-m', "--match", type=str, default=None, help="Filter by substring match on name")
@click.option("--expires-in", type=str, default=None, help="Filter IAMs expiring within duration e.g. 30d, 6h, 1y")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def list(index, output, kind, elemref, match, expires_in, **kwargs):
    """List all IAM Credentials"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        q_args = [limit, offset]
        if kind:
            q_args.append(f"kind={kind.upper()}")
        if elemref:
            q_args.append(f"elemref={elemref}")
        if match:
            q_args.append(f"match={match}")
        if expires_in:
            q_args.append(f"expiry_within={parse_k8s_duration(expires_in)}")
        limit_url = parameter_string(q_args)
        r = requests.get("{}/iam{}".format(sc.engine(), limit_url), verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
        else:
            data = []
            headers = ["uid", "name", "type", "age", "description", "elem_ref", "Expires in"]
            for item in results['items']:
                agestr = get_element_age(None, ctime=item['ctime'])
                data.append([item['uid'], item['name'], item['type'], agestr, item['description'] if item['description'] else "-", item['elem_ref'] if item['elem_ref'] else "-", get_expiry_in(item.get('expiry'))])
            print(tabulate(data, headers, tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list IAM. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@iam.command()
@click.argument('uid', type=str)
@click.option('-c', "--credentials", is_flag=True, help="Show credentials in output")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def info(uid, credentials, output, **kwargs):
    """Get information about a particular IAM credential"""
    try:
        r = None
        hdrs = get_hdrs()
        show_creds = ""
        if credentials:
            show_creds = "?show_creds=True"
        r = requests.get(f"{sc.engine()}/iam/{uid}{show_creds}", headers=hdrs, verify=False)
        r.raise_for_status()
        req_json = r.json()

        # Always convert credentials field to JSON
        if 'credentials' in req_json and isinstance(req_json['credentials'], str):
            req_json['credentials'] = json.loads(req_json['credentials'])

        if output == 'yaml':
            print(yaml.dump(req_json, indent=2, default_flow_style=False))
            return

        if output == 'json':
            print(json.dumps(req_json, indent=4))
            return

        result = req_json
        if not result:
            print("IAM '{}' does not exist".format(uid))
        else:
            #hdrs = ['uid', 'type', 'name', 'description']
            print("Name:        {}".format(result['name']))
            print("UUID:        {}".format(result['uid']))
            print("Type:        {}".format(result['type']))
            print("Description: {}".format(result['description'] if result.get('description') else "-"))
            print("Element Reference: {}".format(result['elem_ref'] if result['elem_ref'] else "-"))
            print()
            if credentials:
                print("Credentials:")
                creds = result['credentials']['config']
                creds.pop("type", None)
                creds.pop("name", None)
                creds.pop("description", None)
                print(json.dumps(creds, indent=4))

    except Exception as ex:
        handle_error(ex, action_msg="Failed to fetch IAM info")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@iam.command(aliases=['register'])
@click.argument('name', type=str)
@click.argument('file', type=click.File('r'), required=False)
@click.option('--type', '-t', required=True,
              type=click.Choice(['aws', 'gcp', 'kube_config', 'ssh_key', 'tls'], case_sensitive=False),
              help="Valid element types ('aws', 'gcp', 'kube_config', 'ssh_key', 'tls') for this function")
@click.option('-d', '--description', help="Description of Iam.")
@click.option('-e', '--elem-ref', help="Element Reference of the IAM")
@click.option('--key-algo', type=click.Choice(['rsa', 'ecdsa']), default=None, show_default=True, help="Key algorithm to be used")
@click.option('--key-size', type=click.Choice(['2048', '4096']), default='2048', show_default=True, help="RSA key size (only applies when --key-algo=rsa)")
@click.option('--ec-curve', type=click.Choice(['P-256', 'P-384', 'P-521']), default='P-256', show_default=True, help="EC curve (only applies when --key-algo=ecdsa)")
@click.option('--comment', type=str, default=None, help="Comment to embed in the generated SSH key (defaults to username)")
@click.option('--passphrase', type=str, default=None, help="Passphrase to protect the generated SSH private key")
@click.option('--ssh-key-file', type=click.File('rb'))
@click.option('--ssh-pub-file', type=click.File('rb'))
@click.option('--tls-cert-file', type=click.File('rb'), help="TLS certificate file (cert.pem / tls.crt)")
@click.option('--tls-key-file', type=click.File('rb'), help="TLS private key file (key.pem / tls.key)")
@click.option('--tls-ca-file', type=click.File('rb'), help="TLS CA certificate file (ca.pem / ca.crt) - optional")
@click.option('--tls-cn', type=str, help="Common Name for the generated certificate (required with --generate)")
@click.option('--tls-san', type=str, help="Comma-separated Subject Alternative Names, e.g. DNS:svc.ns.svc.cluster.local,IP:10.0.0.1")
@click.option('--tls-days', type=int, default=365, show_default=True, help="Validity period in days for the generated certificate")
@click.option('--generate', is_flag=True, default=False, help="Generate a self-signed TLS certificate instead of providing files")
@add_options(common_options)
def add(name, file, type, description, elem_ref, **kwargs):
    """Add an IAM credential"""
    try:
        r = None
        hdrs = get_hdrs()
        if not type:
            raise Exception("Must give 'type' in json or as flag")
        if type.upper() not in ['AWS', 'GCP', 'KUBE_CONFIG', 'SSH_KEY', 'TLS']:
            raise Exception("Type needs to be one of ('AWS', 'GCP', 'KUBE_CONFIG', 'SSH_KEY', 'TLS')")

        data = {}
        creds = {}
        data['config'] = {}
        if type.upper() == 'KUBE_CONFIG':
            try:
                try:
                    import ruamel.yaml
                    ryaml = ruamel.yaml.YAML(typ='safe')
                    kube_config_json = ryaml.load(file)
                except:
                    kube_config_json = yaml.safe_load(file)
            except Exception as err:
                raise Exception(f"Failed to parse kubeconfig yaml {err}")
            data['config']['kube_config'] = kube_config_json
        elif type.upper() == 'SSH_KEY':
            if kwargs.get('ssh_key_file') and kwargs.get('ssh_pub_file'):
                if not kwargs.get('key_algo'):
                    raise Exception("Type SSH_KEY should have --key-algo if --ssh-key-file and --ssh-pub-file are passed.")
                try:
                    base64_encoded_data = base64.b64encode(kwargs['ssh_key_file'].read().strip())
                    data['config']['id'] = base64_encoded_data.decode('utf-8')
                    base64_encoded_data = base64.b64encode(kwargs['ssh_pub_file'].read().strip())
                    data['config']['id.pub'] = base64_encoded_data.decode('utf-8')
                    data['config']['key_algo'] = kwargs['key_algo']
                except Exception as err:
                    raise Exception(f"Failed to parse json ssh key file. {err}")
            else:
                data['config']['key_algo'] = kwargs.get('key_algo', 'rsa')
                data['config']['key_size'] = int(kwargs.get('key_size', 2048))
                data['config']['ec_curve'] = kwargs.get('ec_curve', 'P-256')
                if kwargs.get('comment'):
                    data['config']['comment'] = kwargs['comment']
            if kwargs.get('passphrase'):
                data['config']['passphrase'] = kwargs['passphrase']
        elif type.upper() == 'TLS':
            if kwargs.get('generate'):
                if not kwargs.get('tls_cn'):
                    raise Exception("--tls-cn is required when using --generate")
                data['config']['generate'] = True
                data['config']['cn'] = kwargs['tls_cn']
                data['config']['sans'] = [s.strip() for s in kwargs['tls_san'].split(',')] if kwargs.get('tls_san') else []
                data['config']['days'] = kwargs.get('tls_days', 365)
                data['config']['key_algo'] = kwargs.get('key_algo', 'rsa')
                data['config']['key_size'] = int(kwargs.get('key_size', 2048))
                data['config']['ec_curve'] = kwargs.get('ec_curve', 'P-256')
            else:
                if not kwargs.get('tls_cert_file') or not kwargs.get('tls_key_file'):
                    raise Exception("Type TLS requires --tls-cert-file and --tls-key-file, or use --generate to create a self-signed cert.")
                try:
                    data['config']['cert'] = base64.b64encode(kwargs['tls_cert_file'].read().strip()).decode('utf-8')
                    data['config']['key'] = base64.b64encode(kwargs['tls_key_file'].read().strip()).decode('utf-8')
                    if kwargs.get('tls_ca_file'):
                        data['config']['ca_cert'] = base64.b64encode(kwargs['tls_ca_file'].read().strip()).decode('utf-8')
                except Exception as err:
                    raise Exception(f"Failed to read TLS files. {err}")
        else:
            try:
                creds = json.loads(file.read())
            except Exception as err:
                raise Exception(f"Failed to parse the json file. {err}")
            data['config'] = creds

        data['config']['type'] = type.upper()
        data['name'] = name
        data['elem_ref'] = elem_ref if elem_ref else creds.get('elem_ref', None)
        data['description'] = description if description else ""
        r = requests.post(f"{sc.engine()}/iam", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to add iam '{name}'")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

@iam.command()
@click.argument('uid', type=str)
@click.option('-o', '--output', help='Output file path')
@add_options(common_options)
def download_creds(uid, output, **kwargs):
    """Download an IAM credential (creds only, not full spec)"""
    try:
        resp = None
        hdrs = get_hdrs()
        resp = requests.get(f"{sc.engine()}/iam/{uid}?show_creds=True", headers=hdrs, verify=False)
        resp.raise_for_status()
        r = resp.json()
        # print(r)
        file_base = f"iam_{r['name']}_{uid[:8]}"
        if r['type'].upper() == 'KUBE_CONFIG':
            kube_config = json.loads(r['credentials'])['config']['kube_config']
            if output:
                filename = output
            else:
                filename = f"/tmp/{file_base}.yaml"
            with open(filename, 'w') as outfile:
                try:
                    import ruamel.yaml
                    ruamel.yaml.dump(kube_config, outfile, default_flow_style=False, indent=2)
                except:
                    yaml.dump(kube_config, outfile, default_flow_style=False)
            print(f"Downloaded kubeconfig credentials to {filename}")
        elif r['type'].upper() == 'TLS':
            creds = json.loads(r['credentials'])['config']
            out_dir = output if output else f"/tmp/{file_base}"
            import os
            os.makedirs(out_dir, exist_ok=True)
            for field, fname in [('cert', 'tls.crt'), ('key', 'tls.key'), ('ca_cert', 'ca.crt')]:
                if field in creds:
                    fpath = os.path.join(out_dir, fname)
                    with open(fpath, 'wb') as f:
                        f.write(base64.b64decode(creds[field]))
                    print(f"Downloaded TLS {field} to {fpath}")
        else:
            creds = json.loads(r['credentials'])
            if output:
                filename = output
            else:
                filename = f"/tmp/{file_base}.json"
            with open(filename, 'w') as f:
                json.dump(creds, f)
                print(f"Downloaded {r['type'].upper()} credentials to {filename}")

        # print(r.text)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to download iam with uid: {}. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(resp, headers=hdrs)

