def subscriber():
    """Subscriber Management"""


@subscriber.command('add')
@click.argument('name', type=str, required=True )
@click.argument('type' , required=True, type=click.Choice(['kafka', 'S3']))
@click.option('-b', '--brokers', type=str,
              help="The host / IP address of Kafka Brokers. Should be in"
                   " <hostname>:<port> or <ipv4-addr>:<port> or"
                   " <[ipv6-addr]>:<port> (required for kafka type)")
@click.option('-t', '--topic', type=str,
              help="The Kafka topic where the events/alerts will be sent(required for kafka type")
@click.option('-p', '--partition', type=int, required=False,
              help="The kafka partition where the events/alerts will be sent")
@click.option('--sasl-mechanism', type=click.Choice(['PLAIN']),
              help="The kafka broker SASL mechanism. Valid types are['PLAIN']")
@click.option('--username', type=str,help="The kafka broker username")
@click.option('--password', type=str, help="The kafka broker password")
@click.option('--enable-ssl', is_flag=True, default=False,
              help="Enable SSL for communication with Kafka brokers")
@click.option('--credentials',help="Path to file containing credentials <required for type S3>" )
@click.option('--bucket',help="Bucket name <required for type S3>" )
@click.option('--region',help="Region <required for type S3>")
@click.option('--permission', help="Permission (readwrite/readonly)")

@add_options(common_options)
def subscriber_add(name, type, brokers, topic, partition, sasl_mechanism, username, password, enable_ssl, credentials, bucket, region,permission, **kwargs):
    """Add a subscriber"""
    try:
        res = None
        hdrs = get_hdrs()
        payload = {'name': name, 'type': type}
        if type == 'kafka':
            if not brokers:
                raise Exception("Please specify brokers <mandatory for kafka type>")
            if not topic:
                raise Exception("Please specify topic <mandatory for kafka type>")
            payload.update({'brokers': brokers, 'topic': topic})
            if partition:
                payload['partition'] = partition
            if sasl_mechanism:
                if not username:
                    raise Exception("Please specify username using --username option")
                payload['sasl_mechanism'] = sasl_mechanism
            if username:
                if not password:
                    raise Exception("Please specify password using --password option")
                payload['username'] = username
            if password:
                payload['password'] = password
            if enable_ssl:
                payload['enable-ssl'] = enable_ssl
        elif type == 'S3':
            if not credentials:
                raise Exception("credentials ACCESS_KEY, SECRET_KEY necessary for s3 type ")
            payload['credentials'] = read_json_file(credentials)
            if not bucket:
                raise Exception("Bucket not specified for s3 type")
            payload['bucket'] = bucket
            if not region:
                raise Exception("Region of bucket necessay for s3 type")
            payload['region'] = region
            if not permission:
                raise Exception("Permission of bucket necessay for s3 type")
            payload['permission'] = permission
        url = "{}/subscriber".format(sc.engine())
        r = requests.post(url, data=json.dumps(payload), verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.text)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to add subscriber. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)

