def print_help(cmd, parent=None):
    ctx = click.core.Context(cmd, info_name=cmd.name, parent=parent)
    print(cmd.get_help(ctx).replace("Usage: cli", "Usage: mdcap"))
    print()
    commands = getattr(cmd, 'commands', {})
    for sub in commands.values():
        print_help(sub, ctx)

@cli.command()
@click.argument('url', type=str)
@click.option('-X', '--method', default='GET', type=click.Choice(['GET', 'POST', 'PUT', 'DELETE', 'PATCH']), help="HTTP method (default: GET)")
@click.option('-d', '--data', default=None, type=str, help="JSON request body")
@click.option('-o', '--output', type=click.Choice(['json', 'raw']), default='json', help="Output format (default: json)")
@add_options(common_options)
def curl(url, method, data, output, **kwargs):
    """Make an authenticated HTTP request to a MDCAP API URL.

    If URL does not start with http:// or https://, it is treated as a path
    relative to the configured MDCAP engine base URL.
    Example: /api/v1/batch/ -> https://<host>/api/v1/batch/
    """
    result = None
    try:
        if not url.startswith('http://') and not url.startswith('https://'):
            url = sc.engine().rstrip('/') + '/' + url.lstrip('/')
        json_data = None
        if data:
            try:
                json_data = json.loads(data)
            except json.JSONDecodeError as e:
                raise click.BadParameter(f"Invalid JSON: {e}", param_hint="'--data'")
        result = requests.request(method, url, json=json_data, headers=get_hdrs(), verify=False)
        result.raise_for_status()
        if output == 'raw':
            print(result.text)
        else:
            try:
                print(json.dumps(result.json(), indent=4))
            except Exception:
                print(result.text)
    except requests.HTTPError as ex:
        handle_error(ex, action_msg=f"Request failed [{result.status_code}]: {result.text}")
    except Exception as ex:
        handle_error(ex, action_msg=f"Request failed: {ex}")
    finally:
        if kwargs.get('urlinfo') and result:
            compute_curl_command(result, headers=get_hdrs(), data=json_data)


