@cli.group(cls=ClickAliasedGroup)
def lock():
    """Lock Management"""
    pass


@lock.command()
@add_options(common_options)
@click.argument('uids', nargs=-1)
@click.option('--lock', '-l', help="Type of lock", type=click.Choice(['exclusive', 'shared']))
@click.option('--owner', '-o', help="Owner (USER_UID) of the lock")
@click.option('--cascade', '-c', is_flag=True, help="Cascade the lock")
@click.option('--all-or-none', '-a', is_flag=True, help="All or none")
def acquire(uids, lock, owner, cascade, all_or_none, **kwargs):
    '''Acquire locks for elements'''
    try:
        res = None
        hdrs = get_hdrs()
        url = "{}/lock/acquire".format(sc.engine())
        lock = -1 if lock == 'exclusive' else 1
        if not uids:
             print("Please provide element uids")
             sys.exit()
        data = {
            'uids': uids,
            'lock': lock,
            'cascade': cascade,
            'all_or_none': all_or_none,
        }
        if owner:
            data['owner'] = owner
        res = requests.put(url, json=data, verify=False, headers=hdrs)
        res.raise_for_status()
        out = res.json()
        pprint(out)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to acquire locks for elements")
    finally:
        if kwargs.get('urlinfo') and res:
            compute_curl_command(res, headers=hdrs, data=data)


@lock.command()
@add_options(common_options)
@click.argument('uids', nargs=-1)
@click.option('--owner', '-o', help="Release owner (USER_UID) of the lock on the element")
@click.option('--cascade', '-c', is_flag=True, help="Cascade the lock")
def release(uids, owner, cascade, **kwargs):
    '''Release locks for elements'''
    try:
        res = None
        hdrs = get_hdrs()
        url = "{}/lock/release".format(sc.engine())
        if not uids:
             print("Please provide element uids")
             exit()
        data = {
            'uids': uids,
            'cascade': cascade,
        }
        if owner:
            data['owner'] = owner
        res = requests.put(url, json=data, verify=False, headers=hdrs)
        res.raise_for_status()
        out = res.json()
        # Normalize response — 'not_released' is the current field name,
        # 'already_unlocked' is the legacy alias kept for backward compat
        if 'not_released' not in out and 'already_unlocked' in out:
            out['not_released'] = out.pop('already_unlocked')
        elif 'already_unlocked' in out:
            del out['already_unlocked']
        pprint(out)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to release locks for elements")
    finally:
        if kwargs.get('urlinfo') and res:
            compute_curl_command(res, headers=hdrs, data=data)

@lock.command()
@add_options(common_options)
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option('--locktype', '-l', help="Type of lock", type=click.Choice(['exclusive', 'shared']))
@click.option('--element-uid', '-e', help="Filter by element uid", type=str)
@click.option('--owner', '-w', help="Choose owner of the lock")
@click.option('--lock-source', '-s', help="Filter by lock source", type=click.Choice(['user', 'batch']))
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
def list(index, locktype, element_uid, owner, lock_source, output, **kwargs):
    '''list locks for elements'''
    try:
        res = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        query_params = [limit, offset]
        if locktype:
            if locktype == 'exclusive':
                locktype = -1
            else:
                locktype = 1
            query_params.append(f"locktype={locktype}")
        if owner:
            query_params.append(f"owner={owner}")
        if element_uid:
            query_params.append(f"element={element_uid}")
        if lock_source:
            query_params.append(f"lock_source={lock_source}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/lock{}".format(sc.engine(), limit_url), verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        results = r.json()
        if not results:
            print("No results found")
            return
        else:
            for lock in results['items']:
                transform_lock_info(lock)

            print(tabulate(results['items'], headers="keys"))
            footer = '\n--------------------------------------------\n'
            num, den = (results['count'], results['limit']) if results['count'] < results['limit'] else (results['limit'], results['count'])
            footer += "Displaying {}/{} locks from offset {}\n".format(num, den, results['offset'])
            footer += '--------------------------------------------\n'
            print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list locks for elements")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

