@cli.group(cls=ClickAliasedGroup, aliases=['cp'], hidden=True)
def clusterprovisioner():
    """clusterprovisioner Management"""
    pass

@clusterprovisioner.command()
@click.argument('operation', type=click.Choice(['provision', 'configure', 'scaleout', 'scalein', 'manualprovision']))
@click.option( '-p', '--payload', type=str, help="Path to payload")
@add_options(common_options)
def submit(operation, payload, **kwargs):
    """BMM operations"""

    try:
        r = None
        hdrs = get_hdrs()
        data = []
        if payload:
            with open(payload, 'r') as f:
                data = json.load(f)
        op_url = ''
        if operation == 'provision':
            op_url = 'clusterprovisioner'
        elif operation == 'configure':
            op_url = 'clusterprovisioner/configure'
        elif operation == 'scaleout' or operation == 'scalein':
            op_url = 'clusterprovisioner/rescale'
        elif operation == 'manualprovision':
            op_url = 'clusterprovisioner/manualClusterProvision'
        if not op_url:
            click.secho(f"ERROR: Operation {operation} is not supported.", fg="red")
            return
        r = requests.post(f"{sc.engine()}/bmm/{op_url}", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json())
    except Exception as ex:
        handle_error(ex, action_msg="Failed to provision cluster")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

