@schedule.command()
@click.argument('uid', type=str)
@click.option("-o", "--output", type=click.Choice(['json']))
@add_options(common_options)
def info(uid, output, **kwargs):
    """Get schedule with uid"""

    try:
        r = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/schedule/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        d = r.json()['schedule']
        if output == 'json':
            print(json.dumps(r.json()))
        else:
            spec = d['spec']
            lastexec = ''
            if d['lastexec']:
                lastexec = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(d['lastexec']))
            nextexec = ''
            if d['nextexec']:
                nextexec = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(d['nextexec']))
            print(f"\nuid       : {d['uid']} \n")
            print(f"name        : {d['name']} \n")
            print(f"Status      : {d['state']} \n")
            print(f"Request     : {spec['request']} \n")
            print(f"Cron        : {d['cron']} \n")
            print(f"nextexec    : {nextexec} \n")
            print(f"lastexec    : {lastexec} \n")
            print(f"Errmsg      : {d['errmsg']} \n")
            trackers = d['trackers']
            print(f"Batch/Workflow Trackers : \n")
            for idx, tracker in enumerate(trackers):
                print(f"{idx}   : {tracker} \n")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to fetch schedule")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

