@passwordmanager.command(aliases=['info'])
@click.option('--passwordname', '-p', default=None, help="Name of password")
@click.option('--etype', '-e', default=None, type=str, help="Element type")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options,)
def info_secrets(passwordname, etype, output, **kwargs):
    """Show info of stored passwords"""
    try:
        hdrs = get_hdrs()
        #
        data = {
            "name":passwordname,
            "kind":etype
        }
        r = requests.get(f"{sc.engine()}/passwordmanager/info", verify=False, headers=hdrs, json=data)
        r.raise_for_status()

        result = r.json()
        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return


        table=[]
        tbl_hdrs = ["Password name", "kind", "JSON path", "script"]
        for item in result:
            table.append([item['name'],
                            item['kind'],
                            item['path'],
                            item['script']]
                        )

        print(tabulate(table, headers=tbl_hdrs, tablefmt="pretty"))

    except Exception as ex:
        handle_error(ex, action_msg="Failed to list secret paths")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

