@passwordmanager.command(aliases=['add'])
@click.argument("uid", type=str)
@click.argument('passwordname', type=str)
@click.option('--ttl', '-t', default=None, type=str, help="Cron string (use & to replace with random values)")
@click.option('--reset', '-rst', default=None, type=bool)
@click.option('--rules', '-r', default=None, type=str)
@click.option('--username', '-u', default=None, type=str)
@click.option('--sshhost', '-h', default=None, type=str)
@click.option('--jsonfile', '-j', type=click.File('r'))
@add_options(common_options)
def add_password(uid, passwordname, ttl, reset, rules, username, sshhost, jsonfile, **kwargs):
    """Add password rotation for element\n
        UID is uid of element\n
        PASSWORDNAME can be ssh,cloud,bmc,robin
    """

    try:
        data = {}
        if jsonfile:
            data = json.loads(jsonfile.read())
        if ttl is not None:
            data["ttl"] = ttl
        if rules is not None:
            data["rules"] = rules
        if username is not None:
            data["username"] = username
        if sshhost is not None:
            data["sshhost"] = sshhost
        if reset is not None:
            data["reset"] = reset

        data["rotation"] = True

        if not data.get('ttl'):
            raise Exception("ttl not provided")

        hdrs = get_hdrs()
        q_params = []
        q_params.append(f"passwordname={passwordname}")
        limit_url = parameter_string(q_params)
        r = requests.put(f"{sc.engine()}/passwordmanager/add/{uid}{limit_url}", verify=False, headers=hdrs, json=data)
        r.raise_for_status()
        print(json.dumps(r.json(), indent=4))
    except Exception as Ex:
        handle_error(Ex, action_msg="Failed to add password rotation for element")

