@cliconsole.command()
@add_options(common_options)
@click.argument('elementuid', type=str)
@click.argument('iamref', type=str)
@click.option('-c', '--clitype', type=click.Choice(['kubectl', 'helm']), help="type of cli to access", required=True)
#@click.option('-v', '--cliversion', type=str, help="cliversion", required=True)
def k8s(elementuid, iamref, clitype, **kwargs):
    """Start cli console"""

    try:
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/iam/{iamref}?show_creds=True", verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        kubeconfig = data['creds_yaml']
        r = requests.get(f"{sc.engine()}/element/{elementuid}?expand=true", verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        if not data.get("spec", None).get("robin_config", None).get("version", None) or not data.get("spec", None).get("robin_config", None).get("vip", None) or\
        not data.get("spec", None).get("connectors", None).get("http", None).get("port", None):
            print("Version, port, spec, vip details not present in config")
            return
        payload = {
        "element_uid": elementuid,
        "iam_ref": iamref,
        "version": data["spec"]["robin_config"]["version"],
        "vip":  data["spec"]["robin_config"]["vip"],
        "port": data["spec"]["connectors"]["http"]["port"]
        }

        # TODO: add client pod url to servercontext
        url = f"{sc.clientpod()}/kubectl/setup"
        r = requests.post(url, json=payload, verify=False, headers=hdrs)
        r.raise_for_status()
        clientpod_res = r.json()
        payload = {
            "element_uid": elementuid,
            "iam_ref": iamref,
            "kubeconfig": kubeconfig,
            "clitype": clitype,
            "cliversion": data["spec"]["robin_config"]["version"],
            "patch_data": ""
        }

        prompt_prefix = clitype
        print("** CONSOLE ACCESS GRANTED ENTER COMMANDS **")
        while True:
            user_input = input(f"~ {prompt_prefix} ")
            if user_input == "exit":
                break
            # writing logs to a file
            if user_input.find("logs") != -1:
                filename = None
                if clitype == "kubectl":
                    if '>' in user_input:
                        user_input, filename = user_input.split('>')
                    payload["cmd"] = f"%kubectl_cli% {user_input}"
                url = f"{sc.clientpod()}/kubectl/cmd"
                r = requests.post(url, json=payload, verify=False, headers=hdrs)
                r.raise_for_status()
                if filename:
                    with open(filename.strip(), "w+") as f:
                        f.write(r.json()["output"])
                else:
                    print(r.json()["output"])
                continue
            # in case of edit get the resource and edit it inline using  kubectl patch --patch {json data}
            elif user_input.find("edit") != -1:
                user_input = user_input.replace("edit", "get")
                patch_input = user_input.replace("get", "patch")
                user_input = f"{user_input} -o yaml --show-managed-fields=false"

                if clitype == "kubectl":
                    payload["cmd"] = f"%kubectl_cli% {user_input}"
                if clitype == "helm":
                    payload["cmd"] = f"%helm_cli% {user_input}"
                url = f"{sc.clientpod()}/kubectl/cmd"
                r = requests.post(url, json=payload, verify=False, headers=hdrs)
                r.raise_for_status()
                content = r.json()["output"]
                edit_fmt = "yaml"
                with tempfile.NamedTemporaryFile(suffix=".tmp") as t:
                    t.write(bytes(content, 'UTF-8'))
                    t.flush()
                    rc = run([sc.editor(), t.name]).returncode
                    with open(t.name,'rb') as f:
                        mcontent = f.read()
                    changes_detected = False
                    changes = mcontent
                    if edit_fmt == "json":
                        changes = json.loads(mcontent)
                    elif edit_fmt == "yaml":
                        changes = yaml.safe_load(mcontent)
                    if content.strip() != mcontent.decode("utf-8").strip():
                        changes_detected = True
                    if get_user_confirmation('Do you want to apply the changes[y/n]?'):
                        user_input = f" %kubectl_cli% {patch_input} --patch-file "
                        payload["cmd"] = user_input
                        payload["patch_data"] = json.dumps(changes)
                        url = f"{sc.clientpod()}/kubectl/cmd"
                        r = requests.post(url, json=payload, verify=False, headers=hdrs)
                        r.raise_for_status()
                        print(r.json()["output"])
                    continue

            # normal cli operations
            else:
                if clitype == "kubectl":
                    payload["cmd"] = f"%kubectl_cli% {user_input}"
                if clitype == "helm":
                    payload["cmd"] = f"%helm_cli% {user_input}"
                url = f"{sc.clientpod()}/kubectl/cmd"
                r = requests.post(url, json=payload, verify=False, headers=hdrs)
                r.raise_for_status()
                print(r.json()["output"])

    except Exception as ex:
        handle_error(ex, action_msg="Console access failed")

@cliconsole.command()
@add_options(common_options)
@click.argument('elementuid', type=str)
@click.option( '-u', '--username', type=str, help="User account name")
@click.option('--password', type=str, help="password of user account")
def robin(elementuid, username, password, **kwargs):
    """Start cli console"""

    try:
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/element/{elementuid}?expand=true", verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        if not (username and password):
            username = data["spec"]["robin_config"]["robin_user"]
            password = data["spec"]["robin_config"]["robin_password"]

        if not data.get("spec", None).get("robin_config", None).get("version", None) or not data.get("spec", None).get("robin_config", None).get("vip", None) or\
        not data.get("spec", None).get("connectors", None).get("http", None).get("port", None):
            print("Version, port, spec, vip details not present in config")
            return

        payload = {
            "username": username,
            "password": password,
            "version": data["spec"]["robin_config"]["version"],
            "vip": data["spec"]["robin_config"]["vip"],
            "port": data["spec"]["connectors"]["http"]["port"],
            "element_uid": elementuid
        }

        url = f"{sc.clientpod()}/robincli/setup"
        r = requests.post(url, json=payload, verify=False, headers=hdrs)
        r.raise_for_status()
        element_access_token = r.json()["element_access_token"]
        payload = {
            "element_uid": elementuid,
            "element_access_token": element_access_token,
            "cliversion": data["spec"]["robin_config"]["version"]
        }
        print("** CONSOLE ACCESS GRANTED ENTER COMMANDS **")
        while True:
            user_input = input("~ robin ")
            if user_input == "exit":
                break
            payload["cmd"] = f"%robin_cli% {user_input}"
            url = f"{sc.clientpod()}/robincli/cmd"
            r = requests.post(url, json=payload, verify=False, headers=hdrs)
            r.raise_for_status()
            print(r.json()["output"])
    except Exception as ex:
        handle_error(ex, action_msg="Console access failed")
