@event.command("list")
@click.option("-P", "--page", default=1, type=click.IntRange(min=1), help="Page number (1-based)")
@click.option("-c", "--count",  default=100, type=click.IntRange(min=1), help="Number of events per page (in descending order by date)")
@click.option("-e", "--element-uid",  default="", type=str, help="Filter by element UID")
@click.option("-p", "--parent-uid", default="", type=str, help="Filter by parent element UID (e.g. cluster UID)")
@click.option("-t", "--tenant-uid", default="", type=str, help="Filter by tenant UID")
@click.option("--tenant-name", default="", type=str, help="Filter by tenant name")
# TODO VMS-2298: vmalert removed from valid sources for now
@click.option("--source", default=None, type=click.Choice(['k8s', 'robin', 'bmc']), help="Filter by source")
@click.option("--full", is_flag=True, default=False, help="Show full data payload")
@click.option("--severity", type=click.Choice(['all', 'warning', 'critical']), default='warning', show_default=True, help="Set severity level (shows events at the provided severity and higher)")
@click.option("--age", default="", type=str, help="Filter by age, e.g. 1h, 12h, 24h, 3d, 7d, 1mo")
@click.option("--sort-by", type=click.Choice(['time', 'id']), default='time', show_default=True, help="Order events (newest first) by event time or by event id; applied by the server before paging")
@click.option("-o", "--output", type=click.Choice(['json']), default=None, help="Output format")
@add_options(common_options)
def list_events(page, count, element_uid, parent_uid, tenant_uid, tenant_name, source, full, severity, age, sort_by, output, **kwargs):
    """List all events (optionally, filter the results)"""
    if age and not re.match(r'^\d+(s|m|h|d|mo)$', age):
        raise click.BadParameter(f"'{age}' is invalid. Use format like 1h, 12h, 3d, 7d, 1mo", param_hint="'--age'")
    offset = (page - 1) * count
    url = f"{sc.eventserver()}/event?index=0&limit={count}&offset={offset}"
    if element_uid:
        url += f"&uid={element_uid}"
    if parent_uid:
        url += f"&parent_uid={parent_uid}"
    if tenant_uid:
        url += f"&tenant_uid={tenant_uid}"
    if tenant_name:
        url += f"&tenant_name={tenant_name}"
    if source:
        url += f"&source={source}"
    if age:
        url += f"&age={age}"
    url += f"&severity={severity}&sort={sort_by}"
    result = None
    try:
        result = requests.get(url, headers=get_hdrs(), verify=False)
        result.raise_for_status()
        events = result.json()
        if output == 'json':
            print(json.dumps(events, indent=4))
            return
        hdrs = ["ID", "Date", "Source", "Kind", "Element", "Severity", "Object", "Reason", "Count", "Message"]
        if full:
            hdrs.append("Data")
        rows = []
        for ln in events:
            msg = ln.get('message', '')
            _time_str = _fmt_time(ln['last_timestamp']) if ln.get('last_timestamp') else _fmt_time(ln['ftime'])
            row = [
                ln['id'],
                _time_str,
                ln.get('source', ''),
                ln['kind'],
                ln.get('element_name') or ln['elementid'],
                ln.get('severity', ''),
                ln.get('object_id', ''),
                ln.get('reason', ''),
                ln.get('count', ''),
                msg if full else _truncate(msg),
            ]
            if full:
                row.append(ln.get('data', ''))
            rows.append(row)
        print(tabulate(rows, headers=hdrs, tablefmt="pretty"))
        print(f"Showing {len(rows)} event(s) [page={page}, limit={count}]")
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to list events: {ex}")
    finally:
        if kwargs.get('urlinfo') and result:
            compute_curl_command(result, headers=get_hdrs())

