@click.option("--full", is_flag=True, default=False, help="Show full data payload")
@click.option("--sort-by", type=click.Choice(['time', 'id']), default='time', show_default=True, help="Order alerts (newest first) by alert time or by alert id; applied by the server before paging")
@click.option("-o", "--output", type=click.Choice(['json']), default=None, help="Output format")
@add_options(common_options)
def list_alerts(page, count, element_uid, parent_uid, tenant_uid, tenant_name, source, full, sort_by, output, **kwargs):
    """List all alerts (optionally, filter the results)"""
    offset = (page - 1) * count
    url = f"{sc.eventserver()}/alert?index=0&limit={count}&offset={offset}"
    if element_uid:
        url += f"&uid={element_uid}"
    if parent_uid:
        url += f"&parent_uid={parent_uid}"
    if tenant_uid:
        url += f"&tenant_uid={tenant_uid}"
    if tenant_name:
        url += f"&tenant_name={tenant_name}"
    if source:
        url += f"&source={source}"
    url += f"&sort={sort_by}"
    result = None
    try:
        result = requests.get(url, headers=get_hdrs(), verify=False)
        result.raise_for_status()
        if output == 'json':
            print(json.dumps(result.json(), indent=4))
            return
        hdrs = ["ID", "Date", "State", "Severity", "Kind", "Element", "Source", "Reason", "Message"]
        if full:
            hdrs.append("Data")
        rows = []
        for ln in result.json():
            row = [
                ln['id'],
                _fmt_time(ln['ftime']),
                _alert_state_name(ln['state']),
                ln['severity'],
                ln['kind'],
                ln.get('element_name') or ln['elementid'],
                ln.get('source', ''),
                ln['reason'],
                ln['message'] if full else _truncate(ln['message']),
            ]
            if full:
                row.append(ln.get('data', ''))
            rows.append(row)
        print(tabulate(rows, headers=hdrs, tablefmt="pretty"))
        print(f"Showing {len(rows)} alert(s) [page={page}, limit={count}]")
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to list alerts: {ex}")
    finally:
        if kwargs.get('urlinfo') and result:
            compute_curl_command(result, headers=get_hdrs())

