@click.option('--validate', 'do_validate', is_flag=True, default=False, help='Validate spec and helm template without creating the element')
@click.option('--template', 'include_template', is_flag=True, default=False, help='Include rendered helm template in --validate output')
@click.option('-o', '--output', type=click.Choice(['json', 'yaml', 'template']), default=None, help='Output format for --validate result')
@add_options(common_options)
def add(name, appvalues_name, appvalues_uid, description, labels, version, flavor,
        skip_workflow, do_validate, include_template, output,
        repo, chart, chart_version, cluster, namespace, storage_class, values,
        primary_network, secondary_networks, robinrpool, cluster_admin_privileges, set_options, **kwargs):
    """Register an APP element (use --validate to dry-run without creating)"""
    try:
        r = None
        hdrs = get_hdrs()

        values_dict = {}
        if values:
            with open(values, 'r', encoding='utf-8') as fh:
                values_dict = yaml.safe_load(fh) or {}

        labels_dict = {}
        for label in labels:
            if ':' not in label:
                raise Exception(f"Label '{label}' must be in KEY:VALUE format")
            k, v = label.split(':', 1)
            labels_dict[k.strip()] = v.strip()

        spec = build_helm_app_spec(repo, chart, chart_version, cluster, namespace, storage_class,
                                   values_dict, appvalues_name, appvalues_uid,
                                   cluster_admin_privileges, skip_workflow,
                                   primary_network, secondary_networks, set_options, robinrpool=robinrpool)

        data = {
            'kind': 'APP',
            'apiVersion': 'mdcap.robin.io/v1',
            'metadata': {
                'name': name,
                'description': description,
                'labels': labels_dict,
                'version': version,
                'flavor': flavor,
            },
            'spec': spec,
        }

        if do_validate:
            need_template = include_template or output == 'template'
            url = f"{sc.engine()}/app/validate{'?template=true' if need_template else ''}"
            r = requests.post(url, json=data, verify=False, headers=hdrs)
            r.raise_for_status()
            result = r.json()
            if output == 'json':
                print(json.dumps(result, indent=2))
            elif output == 'yaml':
                print(yaml.dump(result, indent=4))
            elif output == 'template':
                objects = result.get('objects') or []
                if not objects:
                    print("No template available")
                else:
                    for obj in objects:
                        tmpl = obj.get('template')
                        if tmpl:
                            print('---')
                            print(base64.b64decode(tmpl).decode())
            else:
                print(f"Valid:    {result.get('valid')}")
                print(f"Chart:    {result.get('chart_name')} {result.get('chart_version') or ''}")
                print(f"Repo UID: {result.get('repo_uid')}")
                print(f"Pods:     {result.get('pods', 0)}")
                print(f"Storage:  {result.get('storage', '0')}")
                req = result.get('requests', {})
                lim = result.get('limits', {})
                print(f"Requests: cpu={req.get('cpu', '0')}  memory={req.get('memory', '0')}")
                print(f"Limits:   cpu={lim.get('cpu', '0')}  memory={lim.get('memory', '0')}")
                objects = result.get('objects', [])
                if objects:
                    print()
                    print(tabulate(
                        [[o.get('kind', ''), o.get('name', ''), o.get('replicas', ''), o.get('requests', {}).get('cpu', ''), o.get('requests', {}).get('memory', '')] for o in objects],
                        headers=['Kind', 'Name', 'Replicas', 'CPU Req', 'Mem Req'],
                        tablefmt='pretty'
                    ))
                errors = result.get('errors', [])
                if errors:
                    print()
                    print("Errors:")
                    for err in errors:
                        print(f"  - {err}")
        else:
            r = requests.post(f"{sc.engine()}/app", json=data, verify=False, headers=hdrs)
            r.raise_for_status()
            print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)
            
