@app.command()
@click.option("-l", "--labels", type=str, multiple=True, help="Filter by labels (key:value).")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']), default=None, help="Output format")
@click.option("--metrics", is_flag=True, default=False, help="Include CPU and memory metrics for each app")
@click.option("--metrics-duration", type=str, default=None, help="Sample duration for metrics (e.g. 5m, 1h)")
@click.option("--resource-metrics", is_flag=True, default=False, help="Include per-resource breakdown in metrics")
@add_options(common_options)
def list(labels, output, metrics, metrics_duration, resource_metrics, **kwargs):
    """List APP elements"""
    try:
        r = None
        hdrs = get_hdrs()
        labellist = parse_labels(labels)
        query_params = [labellist]
        if metrics:
            query_params.append("metrics=true")
        if metrics_duration:
            query_params.append(f"metrics_duration={metrics_duration}")
        if resource_metrics:
            query_params.append("resource_metrics=true")
        limit_url = parameter_string(query_params)
        r = requests.get(f"{sc.engine()}/app/{limit_url}", verify=False, headers=hdrs)
        r.raise_for_status()
        results = r.json()
        if not results['items']:
            print("No results found")
        elif output == 'json':
            print(json.dumps(results, indent=2))
        elif output == 'yaml':
            print(yaml.dump(results, default_flow_style=False))
        else:
            headers = ['Uid', 'Name', 'Tenant', 'User', 'Age', 'State', 'Health', 'Repo', 'Chart', 'Version', 'Cluster']
            if metrics:
                headers += ['CPU%', 'Mem%']
            data = []
            for item in results['items']:
                meta = item.get('metadata', {})
                spec = item.get('spec', {})
                status = item.get('status', {})
                row = [
                    meta.get('uid', '-'),
                    meta.get('name', '-'),
                    spec.get('tenant_name', '-'),
                    spec.get('username', '-'),
                    get_element_age(item),
                    status.get('curr_st', '-'),
                    get_element_liveness_str(status.get('liveness')),
                    spec.get('repo_name', '-'),
                    spec.get('chart_name', '-'),
                    spec.get('current_version', '-'),
                    spec.get('cluster', '-'),
                ]
                if metrics:
                    m = item.get('metrics', {})
                    cpu_val = m.get('cpu', {}).get('util_percent', [None, None])[1]
                    mem_val = m.get('memory', {}).get('util_percent', [None, None])[1]
                    row.append(f"{cpu_val}%" if cpu_val is not None else '-')
                    row.append(f"{mem_val}%" if mem_val is not None else '-')
                data.append(row)
            print(tabulate(data, headers, tablefmt="pretty"))
            footer = '\n--------------------------------------------\n'
            num, den = (results['count'], results['limit']) if results['count'] < results['limit'] else (results['limit'], results['count'])
            footer += "Displaying {}/{} elements from offset {}\n".format(num, den, results['offset'])
            footer += '--------------------------------------------\n'
            print(footer)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

