@app.command()
@click.argument('uid', type=str)
@click.option('--force', is_flag=True, type=bool, default=False, help="Force delete element without running workflow", hidden=True)
@click.option('-y', '--yes', is_flag=True, type=bool, default=False, help="Skip confirmation prompt")
@add_options(common_options)
def delete(uid, force, yes, **kwargs):
    """Delete an APP element"""
    try:
        r = None
        hdrs = get_hdrs()
        if not yes:
            if not get_user_confirmation(f'Do you want to delete app {uid}?'):
                return
        url = f"{sc.engine()}/app/{uid}"
        if force:
            url += "?force=true"
        r = requests.delete(url, verify=False, headers=hdrs)
        r.raise_for_status()
        resp = r.json()
        wf_tracker = resp.get('wf_tracker')
        if wf_tracker:
            print(resp.get('msg', ""))
            print()
            url = "{}/batch/bow/{}".format(sc.engine(), wf_tracker)
            res = requests.get(url, verify=False, headers=hdrs)
            res.raise_for_status()
            r1 = res.json()
            for batchid in r1.get('batches', []):
                print(f"{PROGRAM_NAME} batch info-bow {wf_tracker}")
                print(f"{PROGRAM_NAME} batch info {batchid}")
                print(f"{PROGRAM_NAME} batch logs {batchid} -e {uid}")
            print()
        else:
            print(resp.get('msg', ""))
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

