@click.argument('profileuid', type=str)
@click.option( '-b',"--bm", multiple=True, help="specify bm's uuid ")
@click.option('-e', "--edit", is_flag=True, help="Allow edit before submitting")
@click.option('--set', type=str, multiple=True, help="Override the default values of BM profile")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']), default='json')
@click.option("-s", "--selector", help="use BM selector key:value to applyprofile on matching BMs.")
@click.option('-e',"--exclude", multiple=True, help="Exclude BMs; specify bm's uuid which need to be excluded")
@add_options(common_options)
def applyprofile(profileuid, bm, edit, set, output, selector, exclude, **kwargs):
    """Apply a profile to a baremetal element"""
    try:
        r = None
        hdrs = get_hdrs()
        data = {}
        additional_bmc_config = {}
        for item in set:
            entry = item.split("=")
            additional_bmc_config[entry[0]] = entry[1]

        if edit:
            r = requests.get(f"{sc.engine()}/bm/{bm}?applyprofile={profileuid}&interactive=1",json=additional_bmc_config, verify=False, headers=hdrs)
            r.raise_for_status()
            config = r.json()
            if not output:
                output = "json"

            data = open_in_editor(None, content=json.dumps(config, indent=4), edit_fmt=output)
            if not data:
                return
            r = requests.put(f"{sc.engine()}/bm/{bm}", json=data, verify=False, headers=hdrs)
        else:
            if selector:
                if ":" not in selector:
                    raise Exception("Please specify selector as '--selector key:value'")
                r = requests.get(f"{sc.engine()}/bm?labels={selector}&total=True", verify=False, headers=hdrs)
                r.raise_for_status()
                result = r.json()
                for item in result['items']:
                    if item['metadata']['uid'] in exclude:
                        continue
                    r = requests.put(f"{sc.engine()}/bm/{item['metadata']['uid']}?applyprofile={profileuid}", json=additional_bmc_config, verify=False, headers=hdrs)
                    if r.status_code == 412:
                        print("Please specify values for the following keys:\n")
                        for key in r.text.split(','):
                            print(f"{key}")
                        print (f"\nYou may possibly have to check all the BMs associated with selector: {selector}. To list BMs, use: mdcap bm list -l {selector}")
                        print("You can use syntax --set key1=value1 --set key2=value2 ....\nPlease check command help")
                    r.raise_for_status()
                    print(r.text)
                return
            else:
                for bmuid in bm:
                    if bmuid in exclude:
                        continue
                    r = requests.put(f"{sc.engine()}/bm/{bmuid}?applyprofile={profileuid}", json=additional_bmc_config, verify=False, headers=hdrs)
        if r.status_code == 412:
            print("Please specify values for the following keys:")
            for key in r.text.split(','):
                print(f"{key}")
            print("You can use syntax --set key1=value1 --set key2=value2 ....\nPlease check command help")
            
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

@baremetal.command()
@click.argument('profileuid', type=str)
@click.option( '-b',"--bm", multiple=True, help="specify bm's uuid; use --bm=uid1 --bm=uid2 ... for multiple")
@click.option("-s", "--selector", help="use BM selector key:value to applyprofile on matching BMs.")
@click.option('-e',"--exclude", multiple=True, help="Exclude BMs; specify bm's uuid which need to be excluded")
@add_options(common_options)
def removeprofile(profileuid, bm, selector, exclude, **kwargs):
    """Remove the current profile from the baremetal element"""
    try:
        r = None
        hdrs = get_hdrs()
        data = {}
        
        if selector:
            if ":" not in selector:
                raise Exception("Please specify selector as '--selector key:value'")
            r = requests.get(f"{sc.engine()}/bm?labels={selector}&total=True", verify=False, headers=hdrs)
            r.raise_for_status()
            result = r.json()
            for item in result['items']:
                if item['metadata']['uid'] in exclude:
                    continue
                r = requests.put(f"{sc.engine()}/bm/{item['metadata']['uid']}?removeprofile={profileuid}", json=data, verify=False, headers=hdrs)
                r.raise_for_status()
                print(r.text)
            return
        else:
            for bmuid in bm:
                r = requests.put(f"{sc.engine()}/bm/{bmuid}?removeprofile={profileuid}", json=data, verify=False, headers=hdrs)
                r.raise_for_status()
                print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

