@baremetal.command()
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l", "--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--config", is_flag=True, help="Include config")
@click.option("--metrics", is_flag=True, help="Include metrics for each BM", default=False)
@click.option("--metrics-duration", type=str, default=None, help="Sample duration for metrics (e.g. 5m, 1h)")
@click.option("--network-metrics", is_flag=True, default=False, help="Include network rx/tx metrics")
@add_options(common_options)
def list(index, labels, match, output, config, metrics, metrics_duration, network_metrics, **kwargs):
    """List all BareMetal elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        if config:
            query_params.append(f"config={config}")
        if metrics:
            query_params.append("metrics=true")
        if metrics_duration:
            query_params.append(f"metrics_duration={metrics_duration}")
        if network_metrics:
            query_params.append("network_metrics=true")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/bm{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
            return
        liveness_map = ["unhealthy", "partial", "healthy", "unknown"]
        headers = ["Uid", "Name", "Age", "State", "Health", "Hostname", "IP", "Cluster"]

        data = []
        for item in results['items']:
            metadata = item['metadata']
            status = item['status']
            age = get_element_age(item)
            spec = item.get('spec', {})
            cluster = metadata.get('labels', {}).get('cluster', "") or "-"
            status_str = status['curr_st']
            if status['lock'] != 0:
                status_str += "(locked)"
            elif spec.get('dryrun'):
                status_str += "(dryrun)"
            ipaddress = spec.get('ipaddress')
            if not ipaddress:
                ipaddress = spec.get('connectors', {}).get('ssh', {}).get('sshhost') or "-"
            hostname = spec.get('hostname') or "-"
            data.append([metadata['uid'], metadata['name'], age, status_str, liveness_map[status['liveness']], hostname, ipaddress, cluster])
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += "Displaying {}/{} BMs from offset {}\n".format(results['count'], results['limit'], results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list BMs. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


@baremetal.command()
@click.argument('uid', type=str)
@click.option('-e', "--evaluate", is_flag=True, help="Evaluate any properties referenced from registry within the Baremetal config")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("-s", "--systemdetails", is_flag=True, help="Fetch hardware details from BIOS")
@click.option("--metrics", is_flag=True, default=False, help="Fetch node metrics (CPU, memory, disk)")
@click.option("--metrics-duration", type=str, default=None, help="Sample duration for metrics (e.g. 5m, 15m, 1h)")
@add_options(common_options)
def info(uid, output, evaluate, systemdetails, metrics, metrics_duration, **kwargs):
    """Get information on a particular BareMetal element"""
    try:
        r = None
        hdrs = get_hdrs()
        params = []
        if evaluate:
            params.append("evaluate=true")
        if systemdetails:
            params.append("sd=true")
        if metrics:
            params.append("metrics=true")
            if metrics_duration:
                params.append(f"metrics_duration={metrics_duration}")
        qs = ("?" + "&".join(params)) if params else ""
        r = requests.get(f"{sc.engine()}/bm/{uid}{qs}", verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        result = r.json()
        if not result:
            print("BM '{}' does not exist".format(uid))
        else:
            #hdrs = ['uid', 'type', 'name', 'description']
            print("Name:        {}".format(result['metadata']['name']))
            print("UUID:        {}".format(result['metadata']['uid']))
            print("LABELS :       {}".format(result['metadata']['labels']))
            print("Description: {}".format(result['metadata']['description'] if result['metadata']['description'] else "-"))
            print()
            print("SSH Config:")
            print("    SSH Host:     {}".format(result['spec']['connectors']['ssh']['sshhost']))
            print("    SSH Username: {}".format(result['spec']['connectors']['ssh']['username']))
            if 'password' in result['spec']['connectors']['ssh']:
                print("    SSH Password: ******")
            print()
            if result['spec']['connectors'].get('bmc'):
                print("BMC Config:")
                print("    BMC Host:     {}".format(result['spec']['connectors']['bmc']['bmchost']))
                print("    BMC Username: {}".format(result['spec']['connectors']['bmc']['username']))
                print("    BMC Password: ******")
            if result['spec']:
                print()
                if 'os' in result['spec']:
                    print("Operating System:")
                    print_nested(result['spec']['os'], indent=0)
                if 'network' in result['spec']:
                    print("Network:")
                    print_nested(result['spec']['network'], indent=0)
                if 'storage' in result['spec']:
                    print("Storage:")
                    print_nested(result['spec']['storage'], indent=0)
                if 'artifactory' in result['spec']:
                    print("Artifactory:")
                    print_nested(result['spec']['artifactory'], indent=0)
                if 'config_url' in result['spec']:
                    print("Kickstart:")
                    print_nested(result['spec']['config_url'], indent=0)
                if 'profile_uuid' in result['spec']:
                    print("BM Profile:")
                    print_nested(result['spec']['profile_uuid'], indent=0)
                if 'metrics' in result['spec']:
                    print("Metrics:")
                    metrics_found = False
                    for metric in result['spec']['metrics']:
                        if metric.get('url'):
                            metrics_found = True
                            print("    URL: {}".format(metric['url']))
                            print("    Enabled: {}".format(metric.get('enable', False))) 
                    if not metrics_found:
                        print("No metrics URL(s) available at this moment.")
                if systemdetails:
                    print("ComputerSystem Details:")
                    for k, v in result['systemdetails'].items():
                        print("    {:<30} {}".format(k,v))
                if metrics and result.get('metrics'):
                    m = result['metrics']
                    print()
                    print("Metrics:")
                    cpu = m.get('cpu', {})
                    mem = m.get('memory', {})
                    rootfs = m.get('rootfs', {})
                    print("    CPU util:    {}%".format(cpu.get('util_percent', [None, None])[1]))
                    print("    Mem util:    {}%".format(mem.get('util_percent', [None, None])[1]))
                    print("    Disk util:   {}%".format(rootfs.get('util_percent', [None, None])[1]))
                    if m.get('network_rx_bytes_rate'):
                        print("    Net RX (bps):")
                        for dev, val in m['network_rx_bytes_rate'].items():
                            print("        {}: {}".format(dev, val[1]))
                    if m.get('network_tx_bytes_rate'):
                        print("    Net TX (bps):")
                        for dev, val in m['network_tx_bytes_rate'].items():
                            print("        {}: {}".format(dev, val[1]))

    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for BM '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


