@baremetal.command()
@click.argument('new_bmp_uid', type=str)
@click.option('--bm', type=str, multiple=True, help="BM UID on which to update BMP profile; --bm='all' for all BMs where parent BMP is in effect.")
@click.option('--set', type=str, multiple=True, help="Override the default values of BM profile")
@click.option("-y", "--yes", is_flag=True, help="confirm yes, non-interactive", default=False)
@click.option("-n", "--no-wfs", is_flag=True, help="update only, run no associated workflows on BM(s)", default=False)
@click.option('-e',"--exclude", multiple=True, help="Exclude BMs; specify bm's uuid which need to be excluded")
@add_options(common_options)
def updateprofile(new_bmp_uid, bm, set, yes, exclude, **kwargs):
    """update the BM's config to point to new bmp"""
    try:
        r_child = False
        r_parent = False
        r_bm = False
        r_rm = False
        r_apply = False
        additional_bmc_config = { "update" : True }
        for item in set:
            entry = item.split("=")
            additional_bmc_config[entry[0]] = entry[1]
        hdrs = get_hdrs()
        # Get the info of the BMP
        r_child = requests.get(f"{sc.engine()}/bmprofile/{new_bmp_uid}", headers=hdrs, verify=False)
        r_child.raise_for_status()
        bmp = r_child.json()
        # Get the parent profile
        parent_bmp = bmp['parentuid']
        if parent_bmp is None:
            raise Exception(f"Could not find parentUID of BMP: {new_bmp_uid}. Please use 'mdcap bmp list' to check")

        if len(bm) == 0 or 'all' in bm: 
            # Get the list of associated BMs which are using the parent profile
            r_parent = requests.get(f"{sc.engine()}/bmprofile/bms/{parent_bmp}", headers=hdrs, verify=False)
            r_parent.raise_for_status()
            result = r_parent.json()
            bmlist = []

            # These are the associated BMs
            for item in result['items']:
                if item['metadata']['uid'] in exclude:
                    continue
                bmlist.append(item['metadata']['uid'])
        else:
            # Case, where only few BMs need to be updated
            bmlist = bm
            for bm_uid in bmlist:
                r_bm = requests.get(f"{sc.engine()}/bm/{bm_uid}", headers=hdrs, verify=False)
                r_bm.raise_for_status()
                result = r_bm.json()
                parent_bmp = result['spec'].get('profile_uuid', False)
                if parent_bmp == new_bmp_uid:
                    print('New BMP UUID same as old UUID. No change')
                    return

        if not yes:
            print(f"WARNING: This will update BM(s) existing BMP which is {parent_bmp} to {new_bmp_uid}")
            print(f"To check present BMP contents:\n\n\tmdcap bmp info {parent_bmp} -m\n\n" )
            print(f"To check new BMP contents:\n\n\tmdcap bmp info {new_bmp_uid} -m\n\n" )
            print(f"Number of BMs  that will be updated: {len(bmlist)}\n\n" )
            print(f"Do you wish to proceed with updation ?" )
            val = input("Confirm [y/n] ? ")
            if val.lower() not in ['y', 'yes']:
                sys.exit(0)

        for bmuid in bmlist:
            #r_rm = requests.put(f"{sc.engine()}/bm/{bmuid}?removeprofile=ifexists", json=data, verify=False, headers=hdrs)
            #r_rm.raise_for_status()
            r_apply = requests.put(f"{sc.engine()}/bm/{bmuid}?applyprofile={new_bmp_uid}", json=additional_bmc_config, verify=False, headers=hdrs)
            if r_apply.status_code == 412:
                print("Please specify values for the following keys:")
                for key in r_apply.text.split(','):
                    print(f"{key}")
                print("You can use syntax --set key1=value1 --set key2=value2 ....\nPlease check command help")
            r_apply.raise_for_status()
            print (f"Updated BM: {bmuid} ")

    except Exception as ex:
        handle_error(ex, action_msg="Failed to validate the BM for BMP")
    finally:
        if kwargs.get('urlinfo') and r_child:
            compute_curl_command(r_child, headers=hdrs, data={})

        if kwargs.get('urlinfo') and r_parent:
            compute_curl_command(r_parent, headers=hdrs, data={})

        if kwargs.get('urlinfo') and r_bm:
            compute_curl_command(r_bm, headers=hdrs, data={})

        if kwargs.get('urlinfo') and r_rm:
            compute_curl_command(r_rm, headers=hdrs, data={})

        if kwargs.get('urlinfo') and r_apply:
            compute_curl_command(r_apply, headers=hdrs, data={})

@baremetal.command(hidden=True)
@click.argument('uid', type=str)
@click.option('--operation', help="Bm operation", type=click.Choice(['poweron', 'poweroff', 'powerreset']), required=True)
@add_options(common_options)
def bmops(uid, operation, **kwargs):
    """Run one of baremetal operation"""
    try:
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/bm/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        if not result:
            print("BM '{}' does not exist".format(uid))
            return
        if not result['spec']['connectors'].get('bmc'):
            print("BMC details not present")
            return
        
        payload = {
            "bmcusername": result['spec']['connectors']['bmc']['username'],
            "operation": operation,
            "bmcpassword": result['spec']['connectors']['bmc']['password'],
            "bmchost": result['spec']['connectors']['bmc']['bmchost']
        }
        url = f"{sc.clientpod()}/bmops"
        r = requests.post(url, json=payload, verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        print(data["output"])
    except Exception as ex:
        handle_error(ex, action_msg="Failed run bmoperations")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)

