@element.command()
@click.option('--all', 'all_conditions', is_flag=True, default=False, help="Show all conditions, not just failed ones")
@click.option('--limit', '-l', type=int, default=1000, help="Maximum number of results to return")
@click.option('--username', type=str, help="Filter by username (admin/tenant-admin only)")
@click.option('--tenant', type=str, help="Filter by tenant name (admin only)")
@click.option('--opt-in-types', type=str, help="Only show these condition types (comma-separated)")
@click.option('--opt-out-types', type=str, help="Exclude these condition types (comma-separated)")
@click.option('--kinds', '-k', type=str, help="Filter by element kind (comma-separated)")
@click.option('--age', type=str, help="Filter by last probe time, e.g. 30s, 2m, 1h, 2d, 2w, 1mo, 1y")
@click.option('--parent-eid', type=str, help="Filter conditions for this element and all its children (owner_references)")
@click.option('-o', '--output', type=click.Choice(['json', 'yaml', 'wide']), help="Output format (wide includes message and timestamps)")
@add_options(common_options)
def conditions(all_conditions, limit, username, tenant, opt_in_types, opt_out_types, kinds, age, parent_eid, output, **kwargs):
    """List element conditions (failed conditions by default)"""
    r = None
    try:
        hdrs = get_hdrs()
        query_params = [f"limit={limit}"]
        if all_conditions:
            query_params.append("all_conditions=true")
        if username:
            query_params.append(f"username={username}")
        if tenant:
            query_params.append(f"tenant={tenant}")
        if opt_in_types:
            query_params.append(f"opt_in_types={opt_in_types}")
        if opt_out_types:
            query_params.append(f"opt_out_types={opt_out_types}")
        if kinds:
            query_params.append(f"kinds={kinds}")
        if age:
            query_params.append(f"age={age}")
        if parent_eid:
            query_params.append(f"parent_eid={parent_eid}")

        url = "{}/element/conditions?{}".format(sc.engine(), "&".join(query_params))
        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()

        if output == 'json':
            print(json.dumps(result, indent=4))
            return
        if output == 'yaml':
            print(yaml.dump(result, indent=4))
            return

        items = result.get('items', [])
        if not items:
            print("No conditions found")
            return

        wide = output == 'wide'
        if wide:
            headers = ["Kind", "Name", "UID", "Type", "Status", "Polarity", "Reason", "Message", "Last Probe", "Last Transition"]
        else:
            headers = ["Kind", "Name", "UID", "Type", "Status", "Polarity", "Reason"]
        data = []
        for item in items:
            cond = item.get('condition', {})
            row = [
                item.get('kind', ''),
                item.get('name', ''),
                item.get('uid', ''),
                cond.get('type', ''),
                cond.get('status', ''),
                cond.get('polarity', ''),
                cond.get('reason', ''),
            ]
            if wide:
                row += [
                    cond.get('message', ''),
                    cond.get('last_probe_time', ''),
                    cond.get('last_transition_time', ''),
                ]
            data.append(row)

        print(tabulate(data, headers, tablefmt="pretty"))
        print(f"\n{result.get('total', len(items))} condition(s) found\n")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list element conditions. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)



