@cli.group(cls=ClickAliasedGroup, hidden=True)
def k3s():
    """K3S Cluster Management"""
    pass

@k3s.command()
@click.argument('name', type=str)
@add_options(k8screate_options)
@click.option('--cni-artifact', type=str, default=None, help="cni-artifact")
@add_options(common_options)
def create(name, **kwargs):
    """Create a K3S element based on VMaaS VMs"""
    try:
        k8s_config = {
            "num_masters" : kwargs['num_masters']
        }
        k8s_config['install_type'] = "NON-HA"
        if kwargs['num_masters'] > 1:
            k8s_config['install_type'] = "HA"

        master_flavor = kwargs['vm_master_flavor']
        worker_flavor = kwargs['vm_worker_flavor'] if kwargs.get('vm_worker_flavor') else master_flavor

        for key in ["vip", "vrid", "k8s_version", "airgapped", "repo_url", "targz_url",
                    "netchecker_port", "agent_report_interval", "kube_proxy_mode", "dns_domain",
                    "skydns_server", "container_manager", "docker_image_repo", "preinstall_selinux_state"]:
            if kwargs.get(key):
                k8s_config[key] = kwargs[key]

        infra = {}
        primary_master = None
        secondary_masters = []
        agents = []
        vms_to_add = []
        for i in range(int(kwargs['num_masters'])):
            ordinal = f"0{i + 1}" if i + 1 < 10 else f"{i + 1}"
            vmname = f"{name}-ms-{ordinal}"
            if not primary_master:
                primary_master = vmname
            else:
                secondary_masters.append(vmname)
            vms_to_add.append({'name': vmname, 'flavor': master_flavor})

        for i in range(int(kwargs['num_workers'])):
            ordinal = f"0{i + 1}" if i + 1 < 10 else f"{i + 1}"
            vmname = f"{name}-wk-{ordinal}"
            agents.append(vmname)
            vms_to_add.append({'name': vmname, 'flavor': worker_flavor})

        k8s_config['primary_master'] = primary_master
        k8s_config['secondary_masters'] = secondary_masters
        k8s_config['agents'] = agents
        if kwargs.get('cni_artifact'):
            k8s_config['cni_artifact'] = kwargs['cni_artifact']

        for vm_elem in vms_to_add:
            vmname = vm_elem['name']
            vm_flavor = vm_elem['flavor']
            vm_kwargs = {'element_version': "1", 'labels': [f"k8sgroup:{name}"], 'cluster': kwargs.get('cluster')}
            if kwargs.get('vm_cloudconfig'):
                vm_kwargs['cloudconfig'] = kwargs['vm_cloudconfig']
            vmdata = get_vmaas_vm_create_data(vmname, kwargs['vm_type'], kwargs['vm_image'], vm_flavor, kwargs['vm_networks'], vm_kwargs)
            vmdata['apiVersion'] = "mdcap.robin.io/v1"
            vmdata['kind'] = "VM"
            infra[vmname] = vmdata

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "K3S",
            "metadata": {"name": name, "description": f"k3s-cluster-{name}"},
            "spec": {
                "k8s_config": k8s_config,
                "developer_options": {},
                "infra": infra
            }
        }
        if kwargs.get('skip_workflow'):
            data['spec']['skip_workflow'] = True

        hdrs = get_hdrs()
        if kwargs.get('dryrun'):
            print(json.dumps(data, indent=4))
            return
        r = requests.post(f"{sc.engine()}/k3s", json=data, headers=hdrs, verify=False)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        print(traceback.format_exc())
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

