@k3s.command()
@click.argument('uids', type=str)
@click.argument('workflow', type=str)
@click.option('-o', "--output-file", help="Output file to dump generated workflow to")
@add_options(common_options)
def genwf(uids, workflow, output_file, **kwargs):
    """Generate a config file for a dynamic workflow of a K3S Element"""
    try:
        r = None
        hdrs = get_hdrs()
        data = {
            'uids': uids.split(","),
            'wf_name': workflow
        }
        r = requests.put(f"{sc.engine()}/k3s", json=data, headers=hdrs, verify=False)
        r.raise_for_status()
        if output_file:
            with open(output_file, 'w') as outfile:
                json.dump(r.json(), outfile)
        else:
            print(json.dumps(r.json(), indent=4))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to generate workflow {} for K3S Element(s) {}. ".format(workflow, uids))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)



