# from sanic.log import logger

def k8s_runwf(uid_arr, workflow, extra_payload=None):
    r = None
    hdrs = get_hdrs()
    if not uid_arr:
        raise Exception("Atleast one UID should be passed")
    data = {
        'uids': uid_arr,
        'wf_name': workflow,
    }
    url = f"{sc.engine()}/k8s/wf/{workflow}"
    if len(uid_arr) == 1:
        url = f"{sc.engine()}/k8s/wf/{workflow}/{uid_arr[0]}"

    if extra_payload:
        data.update(extra_payload)

    r = requests.put(url, json=data, verify=False, headers=hdrs)
    r.raise_for_status()
    handle_k8s_wfresp(",".join(uid_arr), r, hdrs)
    return r, hdrs, data

def handle_k8s_wfresp(uids, r, hdrs):
    uid_arr = []
    resp = r.json()
    wf_tracker = resp.get('wf_tracker')
    if uids:
        uid_arr = uids.split(',')
    else:
        uid_arr = resp['uid'].split(',')
    print(resp.get('msg', ""))


