        evaluate_str = "?evaluate=true" if evaluate else ""
        expand_str = "?expand=true" if expand else ""
        r = requests.get(f"{sc.engine()}/k8s/{uid}{evaluate_str}{expand_str}", verify=False, headers=hdrs)
        r.raise_for_status()

