            print(f"INFRA:\n")
            pprint(result['spec']['infra'])


            result['spec'].pop('kube_config', '')
            result['spec'].pop('infra', '')
            if result['spec']:
                print()
                print("Additional Config:")
                print_nested(result['spec'], indent=0)
