@network_function.command()
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def list(index, labels, match, output, **kwargs):
    """List all Network Function elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/network_function{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        results = r.json()
        if not results['items']:
            print("No results found")
        else:
            # hdrs = ['uid', 'type', 'name', 'description']
            print(tabulate(elem_format(results['items'], keys=['uid', 'name', 'flavor', 'version', 'description', 'liveness', 'readiness']), headers="keys"))
            footer = '\n--------------------------------------------\n'
            num, den = (results['count'], results['limit']) if results['count'] < results['limit'] else (results['limit'], results['count'])
            footer += "Displaying {}/{} elements from offset {}\n".format(num, den, results['offset'])
            footer += '--------------------------------------------\n'
            print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list Network Functions. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@network_function.command()
@click.argument('uid', type=str)
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--evaluate", is_flag=True, help="Evaluate any properties referenced from registry within the Network Function config")
@click.option("--appjson", is_flag=True, help="Display network function application json.")
@add_options(common_options)
def info(uid, output, appjson, evaluate, **kwargs):
    """Get information about a particular Network Function"""
    try:
        r = None
        hdrs = get_hdrs()
        if appjson:
            r = requests.get(f"{sc.engine()}/network_function/{uid}?details=true", verify=False, headers=hdrs)
        else:
            evaluate_str = "&evaluate=true" if evaluate else ""
            r = requests.get(f"{sc.engine()}/network_function/{uid}?expand=true{evaluate_str}", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        if not result:
            print("Network Function '{}' does not exist".format(uid))
        else:
            #hdrs = ['uid', 'type', 'name', 'description']
            if appjson:
                print(json.dumps(result, indent=4))
                return

            if output == 'yaml':
                print(yaml.dump(r.json(), indent=4))
                return

            if output == 'json':
                print(json.dumps(r.json(), indent=4))
                return

            cluster = result['spec']['cluster'] if result['spec'].get('cluster') else result['spec']['robincluster']
            print("Name:        {}".format(result['metadata']['name']))
            print("UUID:        {}".format(result['metadata']['uid']))
            print("Description: {}".format(result['metadata']['description'] if result.get('metadata', {}).get('description') else "-"))
            print("Class:       {}".format(result['spec']['class'] if result.get('spec', {}).get('class') else "-"))
            print()
            print("Cluster:")
            print("    Name:        {}".format(cluster['metadata']['name']))
            print("    Description: {}".format(cluster['metadata']['description'] if cluster['metadata'].get('description') else "-"))
            print()
            print("Runtime Configuration:")
            print()
            print(yaml.dump(result['spec']['runtime_config']))
            print()
            print("Network Function Package:")
            print("    Name:    {}".format(result['spec'].get('nfp', {}).get('metadata', {}).get('name', "-")))
            print("    Vendor:  {}".format(result['spec'].get('nfp', {}).get('metadata', {}).get('vendor', "-")))
            print("    Version: {}".format(result['spec'].get('nfp', {}).get('metadata', {}).get('version', "-")))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for Network Function '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@network_function.command('clone')
@click.argument('uid',type=str)
@click.option('--name', required=True, type=str, help="name for the new NF")
@click.option('--newcluster', type=str, help="new cluster _ref for NF")
@add_options(common_options)
def clone(uid, name, newcluster, **kwargs):
    """Clone a network function"""
    try:
        r = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/network_function/{uid}?expand=true", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()    
        
        if newcluster is None:
            robincluster_ref = {"_ref":result["spec"]["robincluster"]["_ref"]}
            result['spec']['default_app_name'] = result['metadata']['name']
        else:
            robincluster_ref = {"_ref":newcluster}


        if "bucket" in result["spec"]:
            result["spec"].pop("bucket", None)
        result["spec"]["robincluster"] = robincluster_ref
        result.pop("status", None)

        nfp_ref = {"elem_uid":result["spec"]["nfp"]["elem_uid"]}
        result["spec"]["nfp"] = nfp_ref
        result["metadata"].pop("ctime", None)
        result["metadata"].pop("uid", None)

        result["metadata"]["name"] = name
        print(json.dumps(result, indent=4))

        r = requests.post(f"{sc.engine()}/network_function", headers=hdrs, json=result, verify=False)
        r.raise_for_status()
        print(r.json()['msg'])

    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for Network Function '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@network_function.command('inventory')
@click.argument('uid',type=str)
@add_options(common_options)
def inventory(uid, **kwargs):
    
    hdrs = get_hdrs()
    try:
        url = "{}/network_function/inventory".format(sc.engine())
        params = f'?uid={uid}'
        url = url+params
        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()
        resp = r.json()
        app = resp.get('inventory',{})
        if not app:
            print(f"No application deployed with name {resp['name']}")
        else:
            print(f"Appname:    {app['name']}\n")
            print(f"Bundle Name:{app.get('bundle_name',[])}\n")
            print(f"Snapshots:")
            data = []
            headers =["ID", "Name", "Created", "State"]
            snaps = app.get('snapshots',[])
            if snaps:
                for snap in snaps:
                    data.append([snap[4], snap[0], timestamp_to_human_readable(snap[1]), snap[2]])
                print(tabulate(data, headers))
            print(f"\nBackups:")
            data = []
            headers =["ID", "Name", "Created", "State"]
            backups = app.get('backups',[])
            if backups:
                for backup in backups:
                    data.append([backup[0], backup[1], timestamp_to_human_readable(backup[2]), backup[3]])
                print(tabulate(data, headers))
            print("\nRepos:")
            data = []
            headers =['Name', 'Bucket', 'Path', 'Permission']
            repos = app.get('repos',[])
            if repos:
                for repo in repos:
                    params = json.loads(repo['params'])
                    data.append([repo['name'], params['bucket'], params['path'], params['permissions']])
                print(tabulate(data, headers))
            print("\nSchedules:")
            schedule = app['config'].get('snapback', {}).get('snapshot', {})
            if schedule:
                schedules = process_schedules(schedule, "snapshot")
                if schedules:
                    print("Snapshot Schedule(s):")
                for schedule in schedules:
                    print("-- {}".format(schedule))
            schedule = app['config'].get('snapback', {}).get('backup', {})
            if schedule:
                schedules = process_schedules(schedule, "backup")
                if schedules:
                    print("Backup Schedule(s):")
                for schedule in schedules:
                    print("-- {}".format(schedule))
        
    except Exception as ex:
        handle_error(ex, action_msg="Failed to get inventory. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

