@repo.command()
@click.argument('uid', type=str)
@click.argument('chart_name', type=str)
@click.option('--values', '-f', 'values_file', type=click.File('r'), default=None, help="YAML file with value overrides")
@click.option('--set', 'set_values', type=str, multiple=True, metavar='KEY=VALUE', help="Helm --set overrides (repeatable, e.g. --set image.tag=1.2)")
@click.option('--storage-class', 'storage_class', type=str, default=None, help="Storage class (sets global.storageClass and global.defaultStorageClass)")
@click.option('--version', 'chart_version', type=str, default=None, help="Chart version (default: latest)")
@click.option('--primary-network', 'primary_network', type=str, default=None, help="Primary network (IPPOOL name); accepted by the API but does not change the rendered template")
@click.option('--secondary-network', 'secondary_networks', type=str, multiple=True, help="Secondary networks (repeatable, IPPOOL names); sets the robin.io/networks annotation")
@click.option('--robinrpool', 'robinrpool', type=str, default=None, help="Robin resource pool; sets the robin.io/robinrpool annotation on PVC, DataVolume, StatefulSet, Deployment and DaemonSet")
@click.option('-o', '--output', 'output', type=click.Choice(['json', 'yaml']), default=None, help="Output format for metadata")
@add_options(common_options)
def chart_template(uid, chart_name, values_file, set_values, storage_class, chart_version, primary_network, secondary_networks, robinrpool, output, **kwargs):
    """Render helm template for a chart in a REPO"""
    try:
        r = None
        hdrs = get_hdrs()
        values = {}
        if values_file:
            values = yaml.safe_load(values_file) or {}
        body = {}
        if values:
            body['values'] = values
        if set_values:
            body['set_options'] = [*set_values]
        if storage_class:
            body['storage_class'] = storage_class
        if primary_network:
            body['primary_network'] = primary_network
        if secondary_networks:
            body['secondary_networks'] = [*secondary_networks]
        if robinrpool:
            body['robinrpool'] = robinrpool
        params = {"chart": chart_name}
        if chart_version:
            params["version"] = chart_version
        r = requests.post(f"{sc.engine()}/repo/charttemplate/{uid}", params=params, json=body, verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        if output == 'yaml':
            print(yaml.dump(data, indent=2))
            return
        if output == 'json':
            print(json.dumps(data, indent=2))
            return
        meta = {k: v for k, v in data.items() if k != 'objects'}
        print(json.dumps(meta, indent=2))
        print()
        for obj in data.get('objects') or []:
            tmpl = obj.get('template')
            if tmpl:
                print('---')
                print(base64.b64decode(tmpl).decode())
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=body)

