@repo.command(name='chart-details')
@click.argument('uid', type=str)
@click.argument('chart_name', type=str)
@click.option('--version', 'chart_version', type=str, default=None, help="Chart version (default: latest)")
@click.option('--output', '-o', type=click.Choice(['summary', 'values', 'resources', 'template', 'versions', 'json']), default='summary', help="Output format")
@click.option('--details', type=str, default=None, help="Comma separated parts to fetch: all, or any of template,values,versions (default: derived from --output)")
@add_options(common_options)
def chart_details(uid, chart_name, chart_version, output, details, **kwargs):
    """Fetch combined chart values and resource summary for a chart in a REPO"""
    try:
        r = None
        hdrs = get_hdrs()
        params = {"chart": chart_name}
        if chart_version:
            params["version"] = chart_version
        if output == 'template':
            params['retain_template'] = 'true'
        if not details:
            details = {'values': 'values', 'template': 'template', 'resources': 'template', 'versions': 'versions'}.get(output, 'all')
        params['details'] = details
        r = requests.get(f"{sc.engine()}/repo/chartdetails/{uid}", params=params, verify=False, headers=hdrs)
        r.raise_for_status()
        data = r.json()
        if output == 'json':
            print(json.dumps(data, indent=2))
        elif output == 'values':
            raw = data.get('stripped_values') or data.get('values')
            if raw:
                print(base64.b64decode(raw).decode())
            else:
                print("No values available")
        elif output == 'template':
            objects = data.get('objects') or []
            if not objects:
                print("No template available")
            else:
                for obj in objects:
                    tmpl = obj.get('template')
                    if tmpl:
                        print('---')
                        print(base64.b64decode(tmpl).decode())
        elif output == 'versions':
            versions = data.get('versions') or []
            if not versions:
                print("No versions available")
            else:
                print(tabulate([[v.get('version', ''), v.get('app_version', ''), v.get('description', '')] for v in versions],
                               headers=['Version', 'App Version', 'Description'], tablefmt='pretty'))
        elif output == 'resources':
            compute = data.get('compute_resources', [])
            all_res = data.get('all_resources', [])
            print("Compute Resources:")
            for r_ in compute:
                print(f"  {r_}")
            print("\nAll Resources:")
            for r_ in all_res:
                print(f"  {r_}")
        else:
            print(f"Chart:   {data.get('chart_name', chart_name)}")
            print(f"Version: {data.get('chart_version', '-')}")
            print(f"Repo:    {data.get('repo_name', '-')}")
            compute = data.get('compute_resources', [])
            all_res = data.get('all_resources', [])
            print(f"\nCompute Resources ({len(compute)}): {', '.join(compute) or '-'}")
            print(f"All Resources    ({len(all_res)}): {', '.join(all_res) or '-'}")
            if 'versions' in data:
                print(f"Versions         ({len(data['versions'])}): {', '.join(v.get('version', '') for v in data['versions']) or '-'}")
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@repo.command()
@click.argument('uid', type=str)
@click.argument('chart_tgz_file', type=str)
@add_options(common_options)
def upload_chart(uid, chart_tgz_file, **kwargs):
    """Upload chart to the internal REPO element."""
    try:
        r = None
        hdrs = get_hdrs()
        filename = os.path.basename(chart_tgz_file)
        r = requests.get(f"{sc.engine()}/repo/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        if not result:
            print("REPO '{}' does not exist".format(uid))
            return
        spec = result['spec']
        if not spec.get('internal'):
            raise Exception(f"Upload chart is only supported for internal repos")

        # upload tgz file to artifactory using the internal repo url
        url = f"{spec['repo_url']}/{filename}"
        val = asyncio.run(upload_file(url, chart_tgz_file, headers=CHECKSUM_HEADERS))
        if val:
            print("Uploaded tgz successfully to artifactory")

        print("Waiting for repo index to be updated ... ")
        time.sleep(6)
        r = requests.put(f"{sc.engine()}/repo/{uid}", json={}, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.text)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

