@robincluster.command()
@click.argument('name', type=str)
@click.option('--uid', type=str, help="Specify RC UID")
@add_options(k8screate_options)
@click.option('--robin-config', type=str, default=None, help="Pass file which contains robin_config section")
@add_options(common_options)
def create(name, **kwargs):
    """Create a ROBINCLUSTER element based on VMaaS VMs"""
    try:
        robin_config = {}
        if kwargs.get('robin_config'):
            robin_config.update(read_json_file(kwargs['robin_config']))

        robin_config['install_type'] = "NON-HA"
        if kwargs['num_masters'] > 1:
            robin_config['install_type'] = "HA"
        master_flavor = kwargs['vm_master_flavor']
        worker_flavor = kwargs['vm_worker_flavor'] if kwargs.get('vm_worker_flavor') else master_flavor
        for key in ["vip", "vrid"]:
            if kwargs.get(key):
                robin_config[key] = kwargs[key]

        infra = {}
        primary_master = None
        secondary_masters = []
        agents = []
        vms_to_add = []
        for i in range(int(kwargs['num_masters'])):
            ordinal = f"0{i + 1}" if i + 1 < 10 else f"{i + 1}"
            vmname = f"{name}-ms-{ordinal}"
            if not primary_master:
                primary_master = vmname
            else:
                secondary_masters.append(vmname)
            vms_to_add.append({'name': vmname, 'flavor': master_flavor})

        for i in range(int(kwargs['num_workers'])):
            ordinal = f"0{i + 1}" if i + 1 < 10 else f"{i + 1}"
            vmname = f"{name}-wk-{ordinal}"
            agents.append(vmname)
            vms_to_add.append({'name': vmname, 'flavor': worker_flavor})

        robin_config['primary_master'] = primary_master
        robin_config['secondary_masters'] = secondary_masters
        robin_config['agents'] = agents
        robin_config['name'] = name
        robin_config['cluster_name'] = name
        robin_config['robin_user'] = "robin"
        robin_config['robin_password'] = "Robin123"
        robin_config['version'] = "5.4.3"
        robin_config['build_url'] = "tmp"

        for vm_elem in vms_to_add:
            vmname = vm_elem['name']
            vm_flavor = vm_elem['flavor']
            vm_kwargs = {'labels': [f"rcgroup:{name}"]}
            if kwargs.get('vm_cloudconfig'):
                vm_kwargs['cloudconfig'] = kwargs['vm_cloudconfig']
            vmdata = get_vmaas_vm_create_data(vmname, kwargs['vm_type'], kwargs['vm_image'], vm_flavor, kwargs['vm_networks'], vm_kwargs)
            vmdata['apiVersion'] = "mdcap.robin.io/v1"
            vmdata['kind'] = "VM"
            infra[vmname] = vmdata

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "ROBINCLUSTER",
            "metadata": {"name": name, "description": f"CNP-cluster-{name}"},
            "spec": {
                "robin_config": robin_config,
                "developer_options": {},
                "infra": infra
            }
        }
        if kwargs.get('uid'):
            data['metadata']['uid'] = kwargs['uid']

        if kwargs.get('skip_workflow'):
            data['spec']['skip_workflow'] = True

        hdrs = get_hdrs()
        if kwargs.get('dryrun'):
            print(json.dumps(data, indent=4))
            return

        r = requests.post(f"{sc.engine()}/robincluster", json=data, headers=hdrs, verify=False)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        print(traceback.format_exc())
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

