@robincluster.command()
@click.option('-r', "--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--config", is_flag=True, help="Include config", default=True)
@click.option("--metrics", is_flag=True, help="Include metrics for each cluster", default=False)
@click.option("--metrics-duration", type=str, default=None, help="Sample duration for metrics (e.g. 5m, 1h)")
@click.option("--tenant", type=str, default=None, help="Filter by tenant name (admin only)")
@click.option("--tenant-uid", type=str, default=None, help="Filter by tenant UID (admin only)")
@add_options(common_options)
def list(index, labels, match, output, config, metrics, metrics_duration, tenant, tenant_uid, **kwargs):
    """List all Robin Cluster elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        if config:
            query_params.append(f"config={config}")
        if metrics:
            query_params.append("metrics=true")
        if metrics_duration:
            query_params.append(f"metrics_duration={metrics_duration}")
        if tenant:
            query_params.append(f"tenant={tenant}")
        if tenant_uid:
            query_params.append(f"tenant_uid={tenant_uid}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/robincluster{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()
        results = r.json()

        if output == 'yaml':
            print(yaml.dump(results, indent=4))
            return

        if output == 'json':
            print(json.dumps(results, indent=4))
            return

        if not results['items']:
            print("No results found")
            return

        data = []
        headers = ['uid', 'name', 'description', '#Nodes (#CP/#WK)', 'CP-Node', 'liveness', 'readiness']
        for item in results['items']:
            metadata = item['metadata']
            status = item.get('status', {})
            spec = item.get('spec', {})
            num_str = "-"
            if spec.get('infra'):
                num_nodes = len(spec.get('infra', []))
                num_masters = 1 + len(spec.get('robin_config', {}).get('secondary_masters', []))
                num_agents = len(spec.get('robin_config', {}).get('agents', []))
                num_str = f"{num_nodes} ({num_masters}/{num_agents})"
            cp_node = spec.get('robin_config', {}).get('primary_master', '-')
            liveness_str = "-"
            readiness_str = "-"
            if status:
                liveness_str = get_element_liveness_str(status['liveness'])
                readiness_str = status['readiness']
            data.append([metadata['uid'], metadata['name'], metadata['description'], num_str, cp_node, liveness_str, readiness_str])
        print(tabulate(data, headers, tablefmt="pretty"))
        if 'count' not in results:
            print('\n')
            return

        footer = '\n--------------------------------------------\n'
        num, den = (results['count'], results['limit']) if results['count'] < results['limit'] else (results['limit'], results['count'])
        footer += "Displaying {}/{} elements from offset {}\n".format(num, den, results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list Robin Clusters. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


@robincluster.command()
@click.argument('uid', type=str)
@click.option("--evaluate", is_flag=True, help="Evaluate any properties referenced from registry within the Robin Cluster config")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("-c", "--clusternodes", is_flag=True, help="Robin cluster node details")
@add_options(common_options)
def info(uid, output, evaluate, clusternodes, **kwargs):
    """Get information about a particular Robin Cluster element"""
    try:
        r = None
        hdrs = get_hdrs()
        evaluate_str = "&evaluate=true" if evaluate else ""
        cn_str = "&cn=true" if clusternodes else ""
        r = requests.get(f"{sc.engine()}/robincluster/{uid}?expand=true{evaluate_str}{cn_str}", verify=False, headers=hdrs)
        r.raise_for_status()
        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        result = r.json()
        if not result:
            print("ROBINCLUSTER '{}' does not exist".format(uid))
        else:
            #hdrs = ['uid', 'type', 'name', 'description']
            print("Name: {}".format(result['metadata']['name']))
            print("UUID: {}".format(result['metadata']['uid']))
            print("Description: {}".format(result['metadata']['description'] if result['metadata'].get('description') else "-"))
            print(f"Status: {result.get('status', {}).get('curr_st', '')}")
            print()
            robin_config = result.get('spec', {}) and result.get('spec', {}).get('robin_config')
            if robin_config:
                print("Robin Config:")
                print("    Robin User: {}".format(robin_config['robin_user']))
                print("    Robin Password: {}".format("*" * 8))
                print("    Installation Type: {}".format(robin_config.get('install_type', 'UNKNOWN')))
                if robin_config.get('install_type', '').upper() == "HA":
                    print("    Virtual IP Address: {}".format(robin_config['vip']))
                    print("    Virtual Router ID: {}".format(robin_config['vrid']))
                print("    Version: {}".format(robin_config['version'] if robin_config.get('version') else "-"))
                print("    Build URL: {}".format(robin_config['build_url'] if robin_config.get('build_url') else "-"))
                print("    Primary Master: {}".format(robin_config['primary_master']))
                if robin_config.get('secondary_masters'):
                    print("    Secondary Masters: {}".format(", ".join(robin_config['secondary_masters'])))
                if robin_config.get('agents'):
                    print("    Agents: {}".format(", ".join(robin_config['agents'])))
            clusternodes = result.get("clusternodes", None)
            if clusternodes:
                print ("\n    {:<60} {:<10} {:<10}".format("Hostname", "State", "Status"))
                for node in clusternodes['items']:
                    print (f"    {node['hostname']:<60} {node['state']:<10} {node['status']:<10}")
            tenant_list = result.get('access', {}).get('atl')
            if tenant_list:
                print("Tenants:")
                for item in tenant_list:
                    print(f"    {item}")


    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for Robin Cluster '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


@robincluster.command('inventory')
@click.argument('uid',type=str)
@add_options(common_options)
def inventory(uid, **kwargs):
    
    hdrs = get_hdrs()
    try:
        url = "{}/robincluster/inventory".format(sc.engine())
        params = f'?uid={uid}'
        url = url+params
        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()
        resp = r.json()
        apps = resp.get('inventory',{})
        if not apps:
            print("No applications")
        else:
            for app in apps:
                print(f"Appname:    {app['ainstances'][0]['app']}\n")
                print(f"Bundle Name:{app.get('bundle_name',[])}\n")
                print(f"Snapshots:")
                data = []
                headers =["ID", "Name", "Created", "State"]
                snaps = app.get('snapshots',[])
                if snaps:
                    for snap in snaps:
                        data.append([snap[4], snap[0], timestamp_to_human_readable(snap[1]), snap[2]])
                    print(tabulate(data, headers))
                print(f"\nBackups:")
                data = []
                headers =["ID", "Name", "Created", "State"]
                backups = app.get('backups',[])
                if backups:
                    for backup in backups:
                        data.append([backup[0], backup[1], timestamp_to_human_readable(backup[2]), backup[3]])
                    print(tabulate(data, headers))
                print("\nRepos:")
                data = []
                headers =['Name', 'Bucket', 'Path', 'Permission']
                repos = app.get('repos',[])
                if repos:
                    for repo in repos:
                        params = json.loads(repo['params'])
                        data.append([repo['name'], params['bucket'], params['path'], params['permissions']])
                    print(tabulate(data, headers))
                print("\nSchedules:")
                schedule = app['config'].get('snapback', {}).get('snapshot', {})
                if schedule:
                    schedules = process_schedules(schedule, "snapshot")
                    if schedules:
                        print("Snapshot Schedule(s):")
                    for schedule in schedules:
                        print("-- {}".format(schedule))
                schedule = app['config'].get('snapback', {}).get('backup', {})
                if schedule:
                    schedules = process_schedules(schedule, "backup")
                    if schedules:
                        print("Backup Schedule(s):")
                    for schedule in schedules:
                        print("-- {}".format(schedule))
                
                print("\n---------------------------------------------------------\n")
        repos = resp.get('repos',{})
        if repos:
            print("Repositories")
            data = []
            headers = ['Name','Type','BackupTarget','Bucket','Path','Permissions']
            for repo in repos:
                data.append([repo['name'],repo['repo_type'],repo['backup_target'],repo['bucket'],repo['path'],repo['permissions']])
            print(tabulate(data, headers))
        else :
            print("\nNo repositories")
    except Exception as ex:
        handle_error(ex, action_msg="Failed to get inventory. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

