@robincluster.command(name="bulk-discover")
@click.argument('filepath', type=str)
@add_options(common_options)
def bulk_discover(filepath, **kwargs):
    '''Bulk Discover multiple RobinClusters from file (csv,xls,xlsx) containing Master IPs/VIPs and Credentials'''
    try:
        res = None
        hdrs = get_hdrs()
        if not os.path.exists(filepath):
            raise Exception("No file found at specified location: {}".format(filepath))
        files = {}
        files['upload_file'] = open(filepath, 'rb')
        split_loc = os.path.splitext(filepath)
        ex = split_loc[1]
        files['ext'] = ex
        res = requests.post(f"{sc.engine()}/robincluster/discover", files = files, headers=hdrs, verify=False)
        #out = res.json()
        res.raise_for_status()
        #print(out)
        print(res.json()['msg'])
    except Exception as ex:
        handle_error(ex, action_msg="Failed to discover RobinClusters")
    finally:
        if kwargs.get('urlinfo') and res:
            compute_curl_command(res, headers=hdrs)

