@robincluster.command(name="list-repo-backups")
@click.argument('uid', type=str)
@click.option("--reponame", type=str, required=True, help="Storage repo name")
@click.option("-d", "--dangling-only", is_flag=True, default=False, help="Show only dangling backups (app no longer exists as a VM element)")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def list_repo_backups(uid, reponame, dangling_only, output, **kwargs):
    """List all backups on a storage repo for a ROBINCLUSTER element"""
    try:
        r = None
        hdrs = get_hdrs()
        url = f"{sc.engine()}/robincluster/repo-backups/{uid}?reponame={reponame}"
        if dangling_only:
            url += "&dangling_only=true"
        r = requests.get(url, verify=False, headers=hdrs)
        r.raise_for_status()
        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return
        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        items = r.json().get('items', [])
        if not items:
            print(f"No {'dangling ' if dangling_only else ''}backups found for repo '{reponame}'")
            return
        headers = ["BackupID", "Backup Name", "VM Name", "Owner/Tenant"]
        data = [
            [b.get('bkpid'), b.get('backupname'), b.get('appname'),
             "{}/{}".format(b.get('username', '-'), b.get('tenant', '-'))]
            for b in items
        ]
        print(tabulate(data, headers, tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to list repo backups for RobinCluster '{uid}'. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, ignore_response=True)
            print(f"Response is verbose. Please redirect it into a file for viewing with [CURL cmd] > resp.json")


