@robincluster.command(hidden=True)
@click.argument('uid', type=str, required=False)
@click.option("--all", "probe_all", is_flag=True, default=False, help="Probe all ROBINCLUSTERs")
@click.option("-l", "--labels", type=str, multiple=True, help="Filter by labels (key=value)")
@add_options(common_options)
def probe(uid, probe_all, labels, **kwargs):
    """Probes cno-agent-cm configmap on ROBINCLUSTER"""
    try:
        r = None
        hdrs = get_hdrs()
        if uid:
            r = requests.put(f"{sc.engine()}/robincluster/probe/{uid}", verify=False, headers=hdrs)
            r.raise_for_status()
            print(r.json()['msg'])
        elif probe_all or labels:
            labellist = parse_labels(labels)
            limit_url = parameter_string([labellist]) if labellist else ""
            r = requests.put(f"{sc.engine()}/robincluster/probe{limit_url}", verify=False, headers=hdrs)
            r.raise_for_status()
            data = r.json()
            if data.get('probed'):
                print(f"Probed: {', '.join(data['probed'])}")
            if data.get('errors'):
                for err in data['errors']:
                    print(f"Error probing {err['name']} ({err['uid']}): {err['error']}")
        else:
            raise Exception("Provide a UID, --all, or --labels")
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=None)

