@robincluster.command()
@click.argument('uid', type=str)
@click.option("-n", "--nodes", is_flag=True, help="Robin cluster node details")
@click.option("-p", "--pods", is_flag=True, help="Robin cluster pod details")
@click.option("--vmaas", is_flag=True, help="Robin cluster pod details")
@add_options(common_options)
def capacity(uid, nodes, pods, vmaas, **kwargs):
    """Get information about a particular Robin Cluster element"""
    try:
        r = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/robincluster/{uid}?expand=true", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()

        kconfig = get_element_kubeconfig(result)
        list_capacity(kconfig, nodes=nodes, pods=pods, vmaas=vmaas)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to get capacity information about RobinCluster")
    finally:
        if kwargs.get('urlinfo') and res:
            compute_curl_command(res, headers=hdrs)


def list_capacity(kconfig, nodes=False, pods=False, vmaas=False, values=False):
    vals = []
    colname = "Total(cpu/mem/pod)"
    if pods:
        colname = "Pod"
    hdrs = ["Nodename", colname, "Cpu(Req/Lim/Util)", "Mem(Req/Lim/Util)", "PodCount"]
    extra_opts = "--util --pods --pod-count"
    if vmaas:
        extra_opts += " -l virtman.component=virtman-vm,kubevirt.io=virt-launcher"

    cmd = f"kubectl --kubeconfig={kconfig} get nodes -o jsonpath='{{.items}}'"
    out, err, code = run_command(cmd)
    nodemap = {}
    ccap = {'cpu': 0, 'memory': 0, 'pods': 0}
    for n in json.loads(out.strip()):
        nodemap[n['metadata']['name']] = n
        ncap = n['status']['allocatable']
        ccap['cpu'] += int(ncap['cpu'])
        ccap['pods'] += int(ncap['pods'])
        if "Ki" in ncap['memory']:
            ccap['memory'] += int(ncap['memory'].replace('Ki', '')) * 1024
        elif "Mi" in ncap['memory']:
            ccap['memory'] += int(ncap['memory'].replace('Mi', '')) * 1024 * 1024
    ccap['memory'] = int(ccap['memory'] / (1024.0 * 1024.0 * 1024.0))

    cmd = f"kube-capacity --kubeconfig={kconfig} {extra_opts} -o json"
    out, err, code = run_command(cmd)
    ret = json.loads(out.strip())
    cobj = ret['clusterTotals']

    req, reqpct, lim, limpct, util, utilpct = get_cpu_val(cobj['cpu'])
    if values:
        crl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
    else:
        crl = f"{reqpct}%/{limpct}%/{utilpct}%"

    req, reqpct, lim, limpct, util, utilpct = get_mem_val(cobj['memory'])
    if values:
        mrl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
    else:
        mrl = f"{reqpct}%/{limpct}%/{utilpct}%"

    pcnt = cobj['podCount'].split('/')[0]
    ptl = cobj['podCount'].split('/')[1]
    _total = f"{ccap['cpu']}/{ccap['memory']}/{ptl}"

    if not pods:
        vals.append(("*", _total, crl, mrl, pcnt))

    if not nodes and not pods:
        ret['nodes'] = []

    for cobj in ret['nodes']:
        n = nodemap[cobj['name']]
        ncap = n['status']['allocatable']
        total_cpucap = int(ncap['cpu'])
        if "Ki" in ncap['memory']:
            total_memcap = int(ncap['memory'].replace('Ki', '')) * 1024
        elif "Mi" in ncap['memory']:
            total_memcap = int(ncap['memory'].replace('Mi', '')) * 1024 * 1024
        total_memcap = int(total_memcap / (1024.0 * 1024.0 * 1024.0))

        req, reqpct, lim, limpct, util, utilpct = get_cpu_val(cobj['cpu'])
        if values:
            crl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
        else:
            crl = f"{reqpct}%/{limpct}%/{utilpct}%"

        req, reqpct, lim, limpct, util, utilpct = get_mem_val(cobj['memory'])
        if values:
            mrl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
        else:
            mrl = f"{reqpct}%/{limpct}%/{utilpct}%"

        pcnt = cobj['podCount'].split('/')[0]
        ptl = cobj['podCount'].split('/')[1]
        _total = f"{total_cpucap}/{total_memcap}/{ptl}"
        namestr = cobj['name'].split('.')[0]

        if pods:
            _total = "*"
        vals.append((namestr, _total, crl, mrl, pcnt))
        if not pods or not cobj.get('pods'):
            continue
        for pobj in cobj['pods']:
            podname = f"{pobj['namespace']}/{pobj['name']}"
            req, reqpct, lim, limpct, util, utilpct = get_cpu_val(pobj['cpu'])
            if values:
                crl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
            else:
                crl = f"{reqpct}%/{limpct}%/{utilpct}%"

            req, reqpct, lim, limpct, util, utilpct = get_mem_val(pobj['memory'])
            if values:
                mrl = f"{req}({reqpct}%) / {lim}({limpct}%) / {util}({utilpct}%)"
            else:
                mrl = f"{reqpct}%/{limpct}%/{utilpct}%"
            vals.append((namestr, podname, crl, mrl, "-"))
    print(tabulate(vals, headers=hdrs, tablefmt="pretty"))


def get_cpu_val(obj):
    util = utilpct = req = reqpct = lim = limpct = 0
    _tmp = int(obj['requests'].replace('m', ''))
    req = int(_tmp/1000.0)
    reqpct = int(obj['requestsPercent'].replace('%', ''))
    _tmp = int(obj['limits'].replace('m', ''))
    lim = int(_tmp/1000.0)
    limpct = int(obj['limitsPercent'].replace('%', ''))
    if 'utilization' in obj:
        _tmp = int(obj['utilization'].replace('m', ''))
        util = int(_tmp/1000.0)
        utilpct = int(obj['utilizationPercent'].replace('%', ''))
    return req, reqpct, lim, limpct, util, utilpct


def get_mem_val(obj):
    util = utilpct = req = reqpct = lim = limpct = 0
    req = int(int(obj['requests'].replace('Mi', ''))/1024.0)
    reqpct = int(obj['requestsPercent'].replace('%', ''))
    lim = int(int(obj['limits'].replace('Mi', ''))/1024.0)
    limpct = int(obj['limitsPercent'].replace('%', ''))
    if 'utilization' in obj:
        util = int(int(obj['utilization'].replace('Mi', ''))/1024.0)
        utilpct = int(obj['utilizationPercent'].replace('%', ''))
    return req, reqpct, lim, limpct, util, utilpct


@robincluster.command(name='k9s-console', aliases=['k9s'])
@click.argument('uid', type=str)
@add_options(common_options)
def k9s_console(uid, **kwargs):
    """Open k9s console for a ROBINCLUSTER element"""
    try:
        r = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/robincluster/{uid}?expand=true", verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        kconfig = get_element_kubeconfig(result)
        if not kconfig:
            return
        os.execlp('k9s', 'k9s', f'--kubeconfig={kconfig}', '-A')
    except Exception as ex:
        handle_error(ex, action_msg="Failed to open k9s console for RobinCluster")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)



