@vm.command(name="import")
@click.argument('location',type= str)
@add_options(common_options)
def import_elements(location, **kwargs):
    '''Import VMs from file(json)'''
    try:
        r = None
        hdrs = get_hdrs()

        if not os.path.exists(location):
            raise Exception("No file found at specified location: {}".format(location))
        with open(location, 'r') as fh:
            vms = json.load(fh)
            print(f"Importing {len(vms)} vms...")
            for vm in vms:
                vmtype = vm.get('vmtype')
                if not vmtype:
                    vmtype = "generic"
                data = {
                    'apiVersion': vm['apiVersion'],
                    'kind': vm['kind'],
                    'metadata': {
                        'name': vm['metadata']['name'],
                        'description': vm['metadata'].get('description', ''),
                        'labels': parse_labels(vm['metadata']['labels'], ret_dict=True) if 'labels' in vm['metadata'] else {}
                    },
                    'spec': {
                        'vmtype': vmtype,
                        'connectors': {
                            'ssh': {
                                'sshhost': vm['spec']['connectors']['ssh'].get('sshhost', 'fillin'),
                                'username': vm['spec']['connectors']['ssh']['username'],
                                'password': vm['spec']['connectors']['ssh']['password']
                            }
                        }
                    }
                }
                r = requests.post(f"{sc.engine()}/vm", json=data, verify=False, headers=hdrs)
                r.raise_for_status()
                print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex, action_msg="Failed to import elements")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

@vm.command()
@click.argument('name', type=str)
@add_options(vmcreate_options)
@click.option('--pvcs', multiple=True, default=None, help="Pass existing PVC names to boot the VM with")
@click.option('--dryrun', help="Dryrun", type=click.Choice(['client', 'server', "none"]), default="none")
@click.option('--genplan', is_flag=True, type=bool, default=False, help="Generate plan", hidden=True)
@click.option('--backupid', type=str, default=None, help="VM being created from backup ID")
@click.option('--backupname', type=str, default=None, help="VM being created from backup ID")
@click.option('--username', type=str, default=None, help="Create on behalf of the user")
@click.option('--tenant-name', type=str, default=None, help="Create on behalf of the user")
@click.option('--role-name', type=str, default=None, help="Create on behalf of the user")
@click.option('--discover', is_flag=True, type=bool, default=False, help="Generate plan", hidden=True)
@add_options(common_options)
def create(name, image, flavor, **kwargs):
    """Create a VM"""
    try:
        r = None
        hdrs = get_hdrs()
        from_backup = kwargs.get('backupid') or kwargs.get('backupname')
        if not (from_backup or kwargs.get('discover')):
            if not image:
                raise Exception("--image is required")
            if not flavor:
                raise Exception("--flavor is required")
            if not kwargs.get('network'):
                raise Exception("--network is required")
        networks = kwargs.get('network')
        vmtype = kwargs['vmtype']
        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "VM",
        }
        vmdata = get_vmaas_vm_create_data(name, vmtype, image, flavor, networks, kwargs)
        data.update(vmdata)

        if kwargs.get('pvcs', []):
            if not kwargs.get('cluster'):
                raise Exception("Target Cluster have to be passed if PVCs are passed")
            data['spec']['existing_pvcs'] = kwargs['pvcs']

        cluster_check = False
        reason = ""
        if kwargs.get('backupid') or kwargs.get('backupname'):
            if kwargs.get('backupid'):
                data['spec']['backupid'] = kwargs['backupid']
                if '-' not in kwargs['backupid']:
                    cluster_check = True
                    reason = "backupid doesnt contain cluster name"
            elif kwargs.get('backupname'):
                data['spec']['backupname'] = kwargs['backupname']
                cluster_check = True
                reason = "backupname is passed"
        elif kwargs.get('discover'):
            data['spec']['discover'] = True
            cluster_check = True
            reason = "discover is passed"

        if cluster_check and not kwargs.get('cluster'):
            raise Exception(f"Target Cluster have to be passed if {reason}")

        if kwargs.get('username'):
            if not kwargs.get('tenant_name') or not kwargs.get('role_name'):
                raise Exception("--tenant-name and --role-name are required when --username is specified")
            data['spec']['username'] = kwargs['username']
            data['spec']['tenant_name'] = kwargs['tenant_name']
            data['spec']['role_name'] = kwargs['role_name']

        if kwargs.get('dryrun', '') == "client":
            print(json.dumps(data, indent=4))
            return

        r = requests.post(f"{sc.engine()}/vm", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        _handle_vm_wfresp(None, r, hdrs)
        if kwargs.get('genplan'):
            resp = r.json()
            if kwargs.get('json'):
                print(json.dumps(resp, indent=4))
                return
            print_plan(resp)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)


def print_plan(resp):
    data = []
    headers = None
    for vm_elem in resp.get('plan', []):
        meta = vm_elem['metadata']
        spec = vm_elem['spec']
        alloc_net = spec['alloc_net']
        val = [meta['name'], spec['cluster'], spec['namespace']]
        if not headers:
            headers = ["Name", "Cluster", "Namespace"]
            for net in alloc_net:
                headers.append(net['name'])
        for net in alloc_net:
            val.append(",".join(net['allocated_ipaddrs']))
        data.append(val)
    print(tabulate(data, headers, tablefmt="pretty"))


def print_addnetwork_plan(resp):
    """Print plan for add-network workflow showing newly added networks with allocated IPs"""
    data = []
    headers = ["Name", "Cluster", "Namespace"]

    for vm_elem in resp.get('plan', []):
        meta = vm_elem['metadata']
        spec = vm_elem['spec']
        alloc_net = spec.get('alloc_net', [])

        # Build row with VM info
        val = [meta['name'], spec.get('cluster', 'N/A'), spec.get('namespace', 'N/A')]

        # Add columns for each network with allocated IPs
        for net in alloc_net:
            net_name = net.get('name', 'unknown')
            if net_name not in headers:
                headers.append(net_name)

        # Add IP addresses for this VM's networks
        for net_name in headers[3:]:  # Skip Name, Cluster, Namespace
            found = False
            for net in alloc_net:
                if net.get('name') == net_name:
                    ips = net.get('allocated_ipaddrs', [])
                    val.append(",".join(ips) if ips else "N/A")
                    found = True
                    break
            if not found:
                val.append("N/A")

        data.append(val)

    print(tabulate(data, headers, tablefmt="pretty"))


@vm.command()
@click.argument('uids', type=str, nargs=-1)
@click.option('-y', '--yes', is_flag=True, type=bool, default=False, help="Confirm yes")
@click.option('--caller-uid', type=str, help="Caller UID")
@click.option('--force', is_flag=True, type=bool, default=False, help="Force delete", hidden=True)
@click.option('--skip-robin-app', is_flag=True, type=bool, default=False, help="Skip robin app deletion", hidden=True)
@click.option('--purge-backups', is_flag=True, type=bool, default=False, help="Delete all backups before VM deletion")
@click.option('--preserve-vm-ips', is_flag=True, type=bool, default=False, help="Preserve VM IPs for backup/restore purposes.")
@add_options(common_options)
def delete(uids, **kwargs):
    """Delete a VM"""
    try:
        if not kwargs.get('yes'):
            if not get_user_confirmation('Do you want to delete?'):
                return None
        r = None
        hdrs = get_hdrs()
        payload = {'uids': uids}
        url = f"{sc.engine()}/vm/delete/"
        query_params = []
        if kwargs.get('caller_uid'):
            payload['caller_uid'] = kwargs['caller_uid']
        if kwargs.get('skip_robin_app'):
            payload['skip_robin_app'] = True
        if kwargs.get('purge_backups'):
            query_params.append('purge_backups=true')
        if kwargs.get('preserve_vm_ips'):
            payload['preserve_vm_ips'] = True
        if len(uids) == 1:
            url = f"{sc.engine()}/vm/{uids[0]}"
            if kwargs.get('force'):
                print('This will force delete the VM from CNO and might leave objects in the Cluster. Are you sure ? Enter VM UID again:', end="")
                x = input()
                if x != uids[0]:
                    print('UID did not match')
                    return
                query_params.append("origin=workflow")
        elif kwargs.get('force'):
            print('Force not suported for more than 1 VM UID')
            return

        if query_params:
            url += "?" + "&".join(query_params)

        r = requests.delete(url, json=payload, verify=False, headers=hdrs)
        r.raise_for_status()
        _handle_vm_wfresp(",".join(uids), r, hdrs)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=payload)

@vm.command()
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option('-c', '--columns', multiple=True)
@click.option("--metrics", is_flag=True, help="Include metrics for each VM", default=False)
@click.option("--metrics-duration", type=str, default=None, help="Sample duration for metrics (e.g. 5m, 1h)")
@add_options(common_options)
def list(index, labels, match, output, metrics, metrics_duration, **kwargs):
    """List all VMs"""
    try:
        r = hdrs = data = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        if metrics:
            query_params.append("metrics=true")
        if metrics_duration:
            query_params.append(f"metrics_duration={metrics_duration}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/vm{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
            return

        if kwargs.get('columns'):
            cols = []
            values = []
            for item in kwargs['columns']:
                _arr = item.split(':')
                cols.append(_arr[0])
                values.append(_arr[1])
            hdrs = ["UID", "Name"] + cols
            targets = ["/metadata/uid", "/metadata/name"] + values
            vals = []
            for vm_obj in results['items']:
                row = []
                for tgt in targets:
                    curr_val = vm_obj
                    path_arr = tgt.lstrip('/').split('/')
                    for path in path_arr:
                        try:
                            path = int(path)
                            curr_val = curr_val[path]
                        except ValueError:
                            curr_val = curr_val.get(path)
                        if curr_val is None:
                           curr_val = ""
                           break
                    row.append(curr_val)
                vals.append(row)
            print(tabulate(vals, headers=hdrs, tablefmt="pretty"))
            return

        data = []
        headers = ["Uid", "Name", "Tenant", "User", "Age", "State", "Health", "Hostname", "IP", "Flavor", "Image", "Node"]
        for item in results['items']:
            metadata = item['metadata']
            status = item['status']
            age = get_element_age(item)
            spec = item['spec']
            vmtype = spec.get('vmtype') or "generic"
            cluster = spec.get('cluster') or "-"
            namespace = spec.get('namespace') or "-"
            tenant = spec.get('tenant_name') or "-"
            username = spec.get('username') or "-"
            nodename = spec.get('nodename') or "-"
            group = spec.get('group') or "-"
            if group and group == metadata['name']:
                name_str = metadata['name']
            else:
                name_str = "{} ({})".format(metadata['name'], group)
            status_str = status['curr_st']
            if status['lock'] != 0:
                status_str += "(locked)"
            elif spec.get('dryrun'):
                status_str += "(dryrun)"
            ipaddress = spec.get('ipaddress')
            if not ipaddress:
                ipaddress = spec.get('connectors', {}).get('ssh', {}).get('sshhost') or "-"
            flavor = spec.get('flavor', {}).get('elem_name') or "-"
            image = spec.get('image', {}).get('elem_name') or "-"
            network = spec.get('network') or "-"
            hostname = spec.get('hostname') or "-"
            port = spec.get('port')
            snap_count = len(spec.get('snapshots', []))
            liveness_str = get_element_liveness_str(status['liveness'])
            data.append([metadata['uid'], name_str, tenant, username, age, status_str, liveness_str, hostname, ipaddress, flavor, image, f"{cluster}/{nodename}"])
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += "Displaying {}/{} VMs from offset {}\n".format(results['count'], results['limit'], results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list vms. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

def get_vm_info(uid, hdrs, expand=False, get_iam=False):
    r = None
    param_str = ""
    if expand and get_iam:
        param_str = "?expand=true&iam=true"
    elif expand:
        param_str = "?expand=true"
    elif get_iam:
        param_str = "?iam=true"
    r = requests.get(f"{sc.engine()}/vm/{uid}{param_str}", verify=False, headers=hdrs)
    r.raise_for_status()
    result = r.json()
    spec = result.get('spec', {})
    return result, r

def get_vm_podname(cluster_config, vmname, vncpod=False):
    label = "vncname" if vncpod else "vmname"
    cmd = f"kubectl --kubeconfig {cluster_config} get pods -l app.release.{label}={vmname}"
    cmd += " -o jsonpath={.items[].metadata.name}"
    podname, err, code = run_command(cmd)
    return podname


def get_vm_kubeconfig(result):
    vmname = result['metadata']['name']
    namespace = result['spec']['namespace']
    alloc_cluster = result['spec'].get('cluster')
    iam = result['spec'].get('iam')
    if not alloc_cluster or not iam:
        print(f"VM {vmname} not initialized yet Alloc CLuster: {alloc_cluster}")
        return
    base_dir = sc.base_vmaas_dir()
    if not os.path.isdir(base_dir):
        os.mkdir(base_dir)
    cluster_dir = os.path.join(base_dir, alloc_cluster)
    if not os.path.isdir(cluster_dir):
        os.mkdir(cluster_dir)
    cluster_config = os.path.join(cluster_dir, f"{namespace}.kubeconfig")
    if not os.path.isfile(cluster_config):
        with open(cluster_config, 'w') as fp:
            fp.write(yaml.dump(iam, default_flow_style=False, allow_unicode=True, encoding=None))
    return cluster_config

def _decode_b64(val):
    try:
        return base64.b64decode(val).decode('utf-8')
    except Exception:
        return val or ""


def _info_section(title):
    head = click.style(title, bold=True) if sys.stdout.isatty() else title
    print(f"\n{head}")
    print("-" * len(title))


def _info_kv(rows):
    """Print (key, value) rows with the keys padded to one width. Rows with an empty value are skipped."""
    rows = [(k, v) for k, v in rows if v not in (None, "", [], {})]
    if not rows:
        return
    width = max(len(k) for k, _ in rows)
    for key, val in rows:
        print(f"  {key:<{width}} : {val}")


def _info_table(headers, rows, tablefmt="pretty"):
    print(tabulate(rows, headers=headers, tablefmt=tablefmt))


def _state_text(status):
    state = status.get('curr_st') or "-"
    try:
        health = get_element_liveness_str(status.get('liveness'))
    except Exception:
        health = None
    text = f"{state} ({health})" if health else state
    if not sys.stdout.isatty():
        return text
    color = {"healthy": "green", "partial": "yellow", "unhealthy": "red", "poweroff": "bright_black"}.get(health, None)
    return click.style(text, fg=color) if color else text


def print_vm_info(result, events, batches, full=False):
    """Human readable VMaaS VM summary. Empty sections are left out; `full` adds the detailed ones."""
    metadata = result['metadata']
    spec = result.get('spec') or {}
    status = result.get('status') or {}
    uid = metadata['uid']

    # Summary
    owner = spec.get('username') or ""
    if owner and spec.get('tenant_name'):
        owner = f"{spec['tenant_name']}/{owner}"
    cluster = spec.get('cluster') or ""
    if cluster and spec.get('cluster_uid'):
        cluster = f"{cluster} ({spec['cluster_uid']})"
    try:
        age = get_element_age(result)
    except Exception:
        age = ""
    labels = ", ".join(f"{k}={v}" for k, v in (metadata.get('labels') or {}).items())
    csa = spec.get('compute_storage_affinity')
    if csa:
        csa_text = f"{csa if isinstance(csa, str) else 'enabled'} (level: {spec.get('compute_storage_affinity_level') or 'host'})"
    else:
        csa_text = "disabled"
    _info_kv([
        ("Name", metadata['name']),
        ("UUID", uid),
        ("State", _state_text(status)),
        ("Description", metadata.get('description') if metadata.get('description') not in (None, metadata['name']) else ""),
        ("IP Address", spec.get('ipaddress')),
        ("Cluster", cluster),
        ("Node", spec.get('nodename') if spec.get('nodename') not in ("-", None) else ""),
        ("Namespace", spec.get('namespace')),
        ("Owner", owner),
        ("Age", age),
        ("Image", (spec.get('image') or {}).get('elem_name')),
        ("Flavor", (spec.get('flavor') or {}).get('elem_name')),
        ("Compute/Storage Affinity", csa_text),
        ("Group", spec.get('group')),
        ("Version", spec.get('version')),
        ("Portgroup", (spec.get('portgroup') or {}).get('elem_name')),
        ("Cloudconfig", ", ".join(c['elem_name'] for c in spec.get('cloudconfig', []))),
        ("Security Groups", ", ".join(c['elem_name'] for c in spec.get('securitygroup', []))),
        ("Hostname", spec.get('hostname')),
        ("FQDN", spec.get('fqdn')),
        ("Labels", labels),
    ])

    # Conditions
    conditions = result.get('conditions') or []
    if conditions:
        _info_section("Conditions")
        rows = []
        for cond in conditions:
            msg = cond.get('message', '') or ''
            rows.append([cond['type'], cond.get('status', ''), cond.get('reason', ''), str(cond.get('last_transition_time', ''))[:19],
                         msg if full or len(msg) <= 60 else msg[:60] + '...'])
        _info_table(["Type", "Status", "Reason", "Since", "Message"], rows)

    # Compute
    domain = spec.get('domain_spec') or {}
    if domain:
        _info_section("Compute")
        cpu = domain.get('cpu', {})
        mem = domain.get('memory', {})
        res = domain.get('resources', {})
        fmt = lambda d: ", ".join(f"{k}={v}" for k, v in (d or {}).items())
        rows = [
            ("vCPU", cpu.get('sockets')),
            ("Memory", mem.get('guest')),
            ("Requests", fmt(res.get('requests'))),
            ("Limits", fmt(res.get('limits'))),
        ]
        if full:
            rows += [("Max sockets", cpu.get('maxSockets')), ("CPU model", cpu.get('model')),
                     ("Dedicated placement", cpu.get('dedicatedCpuPlacement')), ("Max memory", mem.get('maxGuest'))]
        _info_kv(rows)

    # Network
    alloc_net = [spec['cluster_net']] if spec.get('cluster_net') else (spec.get('alloc_net') or [])
    if alloc_net:
        _info_section("Network")
        _info_table(["Network", "IP addresses"], [[n.get('name', ''), ", ".join(n.get('allocated_ipaddrs', []))] for n in alloc_net])
    if spec.get('alloc_eippool'):
        _info_section("Elastic IP")
        _info_table(["Pool", "IP addresses"], [[n.get('name', ''), ", ".join(n.get('allocated_ipaddrs', []))] for n in spec['alloc_eippool']])

    # Volumes
    volumes = spec.get('volumes') or []
    unattached = spec.get('unattached_volumes') or []
    if volumes or unattached:
        _info_section("Volumes")
        rows = []
        for vol, state in [(v, "attached") for v in volumes] + [(v, "unattached") for v in unattached]:
            pvc = vol.get('persistentVolumeClaimInfo', {})
            size = pvc.get('requests', {}).get('storage') or pvc.get('capacity', {}).get('storage') or vol.get('capacity', {}).get('storage') or "-"
            rows.append([vol['name'], size, pvc.get('volumeMode') or vol.get('volumeMode') or "-", vol.get('target', ''), state])
        _info_table(["Name", "Size", "Mode", "Target", "State"], rows)

    # Endpoints
    endpoints = spec.get('endpoints') or []
    if endpoints:
        _info_section("Endpoints")
        hdrs = ["Name", "External URL"] + (["Internal URL"] if full else [])
        rows = [[ep['name'], _decode_b64(ep.get('eurl'))] + ([_decode_b64(ep.get('url'))] if full else []) for ep in endpoints]
        _info_table(hdrs, rows)

    # Snapshots / backups
    if spec.get('snapshots'):
        _info_section("Snapshots")
        _info_table(["Name", "State", "Age"], [[c['name'], c['state'], get_element_age(None, ctime=c['create_time'])] for c in spec['snapshots']])
    if spec.get('backups'):
        _info_section("Backups")
        _info_table(["Name", "Snapshot", "Repo", "State", "Age"],
                    [[c['name'], c['snapshot'], c['repo'], c['state'], get_element_age(None, ctime=c['create_time'])] for c in spec['backups']])

    # Details only shown with --full
    if full:
        if spec.get('metrics_dashboards'):
            _info_section("Metrics")
            _info_table(["Dashboard", "URL"], [[md['title'], md['url']] for md in spec['metrics_dashboards']])
        for ckey, cobj in (spec.get('connectors') or {}).items():
            _info_section(f"{ckey.upper()} connector")
            _info_kv([(key, _decode_b64(val) if key in ("connect_url", "connect_eurl") else val) for key, val in cobj.items()])

    if events is not None:
        _info_section("Events")
        print_events_table(events, uid)
    if batches is not None:
        _info_section("Batches")
        print_batches_table(batches, uid)
    print()


@vm.command()
@click.argument('uid', type=str)
@click.option("--evaluate", is_flag=True, help="Evaluate any properties referenced from registry within the VM config")
@click.option("--expand", is_flag=True, help="Expand infra elements referenced from registry within the Kubernetes Element config")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--iam", is_flag=True, help="show IAM for accessing the VM cluster")
@click.option("--helm-values", is_flag=True, help="show helm values used to create VM")
@click.option("--helm-template", is_flag=True, help="show helm template of the VM")
@click.option("--helm-out", is_flag=True, help="show helm output helm command used to create the VM")
@click.option("--k8s-objects", is_flag=True, help="show all k8s objects of the VM")
@click.option("--virshxml", is_flag=True, help="show virsh dumpxml of the VM")
@click.option("-v", "--full", is_flag=True, help="show the detailed sections as well (compute details, internal URLs, connectors, metrics)")
@click.option("--no-events", is_flag=True, help="do not fetch and show the VM's events and batches")
@add_options(common_options)
def info(uid, output, evaluate, expand, **kwargs):
    """Get information on a particular VM"""
    try:
        r = hdrs = None
        hdrs = get_hdrs()
        get_iam = False
        if kwargs.get('virshxml') or kwargs.get('k8s_objects'):
            get_iam = True
        events = batches = None
        plain = not output and not any(kwargs.get(key) for key in ('iam', 'helm_values', 'helm_template', 'helm_out', 'k8s_objects', 'virshxml'))
        if plain and kwargs.get('no_events'):
            result, r = get_vm_info(uid, hdrs, expand, get_iam=get_iam)
        elif plain:
            # The VM, its events and its batches are independent requests; fetch them together and print later
            vm_resp, events, batches = run_concurrently(lambda: get_vm_info(uid, hdrs, expand, get_iam=get_iam),
                                                        lambda: get_element_events(uid),
                                                        lambda: get_element_batches(uid))
            if isinstance(vm_resp, Exception):
                raise vm_resp
            result, r = vm_resp
        else:
            result, r = get_vm_info(uid, hdrs, expand, get_iam=get_iam)
        if not result:
            print("vm '{}' does not exist".format(uid))
            return

        if output == 'yaml':
            print(yaml.dump(result, indent=4))
            return

        if output == 'json':
            print(json.dumps(result, indent=4))
            return

        mask_sensitive_data(result)

        vmtype = result.get('spec', {}).get('vmtype') or "generic"

        ssh_host = result['spec']['connectors']['ssh']['sshhost']
        ssh_username = result['spec']['connectors']['ssh']['username']
        ssh_port = result['spec']['connectors']['ssh'].get('sshport', 22)

        if vmtype != "vmaas":
            print("Name: {}".format(result['metadata']['name']))
            print("UUID: {}".format(result['metadata']['uid']))
            print("Description: {}".format(result['metadata']['description'] if result['metadata']['description'] else "-"))
            print()
            print("SSH Config:")
            print("    SSH Host: {}".format(ssh_host))
            print("    SSH Username: {}".format(ssh_username))
            print("    SSH Password: {}".format("*" * 8))
            if ssh_port != 22:
                print("    SSH Port: {}".format(ssh_port))

            result['spec'].pop('connectors')
            if result['spec']:
                print()
                print("Additional Config:")
                print_nested(result['spec'], indent=0)
            return

        # if kwargs.get('ssh_info'):
            # print(f"ssh -p {ssh_port} {ssh_username}@{ssh_host}")
            # return

        if kwargs.get('virshxml'):
            vmname = result['metadata']['name']
            cluster_config = get_vm_kubeconfig(result)
            podname = get_vm_podname(cluster_config, vmname, vncpod=kwargs.get('vnc'))
            container = "compute"
            args = ["kubectl", f"--kubeconfig={cluster_config}", "exec", "-ti", podname, "-c", container, "--", "virsh", "dumpxml", "1"]
            if not shutil.which("kubectl"):
                raise Exception("'kubectl' binary not found in PATH")
            os.execvp("kubectl", args)

        if kwargs.get('iam'):
            print(yaml.dump(result.get('spec', {}).get('iam', {}),
                            default_flow_style=False,
                            allow_unicode=True, encoding=None))
            return

        if kwargs.get('helm_values'):
            values_b64 = result.get('spec', {}).get('helm', {}).get('values', '')
            if values_b64:
                print(base64.b64decode(values_b64).decode('utf-8'))
            else:
                print("helm values not present for VM")
            return

        if kwargs.get('helm_template'):
            enc_str = result.get('spec', {}).get('helm', {}).get('template', '')
            if enc_str:
                print(base64.b64decode(enc_str).decode('utf-8'))
            else:
                print("helm template not present for VM")
            return

        if kwargs.get('helm_out'):
            print("STDOUT:\n\n")
            enc_str = result.get('spec', {}).get('helm', {}).get('out', '')
            print(base64.b64decode(enc_str).decode('utf-8'))
            print("STDERR:\n\n")
            enc_str = result.get('spec', {}).get('helm', {}).get('error', '')
            print(base64.b64decode(enc_str).decode('utf-8'))
            return

        metadata = result['metadata']
        if kwargs.get('k8s_objects'):
            cluster_config = get_vm_kubeconfig(result)
            objects = "dv,pvc,vm,vmi,pod,svc,cm,secret,networkpolicy,endpoints,net-attach-def"
            cmd = f"kubectl --kubeconfig={cluster_config} get {objects} -o wide -l app.release.vmname={metadata['name']}"
            out, err, status = run_command(cmd)
            print(out)
            cmd = f"kubectl --kubeconfig={cluster_config} get volumesnapshots -o wide -l app.release.vmname={metadata['name']}"
            out, err, status = run_command(cmd)
            print(out)
            cmd = f"kubectl --kubeconfig={cluster_config} get {objects} -o wide -l app.release.vncname={metadata['name']}"
            out, err, status = run_command(cmd)
            print(out)
            return

        print_vm_info(result, events, batches, full=kwargs.get('full'))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for vm '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@cli.group(cls=ClickAliasedGroup)
def snapshot():
    """VM Snapshot Management"""
    pass

@snapshot.command(name='list', aliases=['snaplist'])
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--vm", type=str, default=None)
@add_options(common_options)
def snaplist(index, labels, output, **kwargs):
    """List all VM Snapshots"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if kwargs.get('vm'):
            query_params.append(f"match={kwargs['vm']}")
        limit_url = parameter_string(query_params)
        url = f"{sc.engine()}/snapshot{limit_url}"
        r = requests.get(url, headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
            return

        data = []
        headers = ["Name", "VM", "SnapUID", "Created", "Age", "State", "VMUID", "Tenant", "User", "Cluster"]
        for snap in results['items']:
            age = get_element_age(None, ctime=snap['create_time'])
            created = timestamp_to_human_readable(snap['create_time'])
            data.append([snap['name'], snap['vm_name'], snap['id'], created, age, snap['state'], snap['vm_uid'], snap['tenant'], snap['username'], snap['cluster']])
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += "Displaying {}/{} VM Snapshots from offset {}\n".format(results['count'], results['limit'], results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list vm snapshots. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

