@vm.command()
@click.argument('uid', type=str)
@click.option("--vnc", is_flag=True, help="show VNC container logs for VM")
@click.option("--console", is_flag=True, help="show console container logs for VM")
@click.option("--console2", is_flag=True, help="show console container logs for VM")
@click.option("--hook", is_flag=True, help="show hook-sidecar container logs for VM")
@click.option("-f", "--follow", is_flag=True, help="Follow logs for VM")
@click.option('--tail', type=int, default=None, help="Specify tail count")
@add_options(common_options)
def logs(uid, **kwargs):
    """Show VM virtlauncher container logs"""
    try:
        r = hdrs = None
        hdrs = get_hdrs()
        result, r = get_vm_info(uid, hdrs, get_iam=True)
        vmname = result['metadata']['name']
        cluster_config = get_vm_kubeconfig(result)
        podname = get_vm_podname(cluster_config, vmname, vncpod=kwargs.get('vnc'))
        container = "compute"
        if kwargs.get('vnc'):
            container = "vnc"
        elif kwargs.get('hook'):
            container = "hook-sidecar-0"
        elif kwargs.get('console'):
            container = "guest-console-log"
        elif kwargs.get('console2'):
            container = "log"
        args = ["kubectl", f"--kubeconfig={cluster_config}", "logs", podname, "-c", container]
        if kwargs.get('follow'):
            args.append("-f")
        if kwargs.get('tail'):
            args.append("--tail={}".format(kwargs['tail']))
        if not shutil.which("kubectl"):
            raise Exception("'kubectl' binary not found in PATH")
        os.execvp("kubectl", args)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for vm '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

@vm.command(context_settings=dict(ignore_unknown_options=True))
@click.argument('uid', type=str)
@click.argument('ssh_opts', nargs=-1, type=click.UNPROCESSED)
@click.option('--download-id-file', is_flag=True, type=bool, default=False, help="Only download id file")
@click.option('--print-cmd', is_flag=True, type=bool, default=False, help="Only download id file")
@click.option('--user', default=None, help="Specify SSH user")
@add_options(common_options)
def ssh(uid, **kwargs):
    """SSH into VM with user sshkey IAM"""
    try:
        r = hdrs = None
        hdrs = get_hdrs()
        result, r = get_vm_info(uid, hdrs)
        vmname = result['metadata']['name']
        ssh_connector = result['spec']['connectors'].get('ssh', {})
        iam_ref = None
        username = result['spec']['username']
        ssh_host = ssh_connector['sshhost']
        ssh_port = ssh_connector.get('sshport', 22)
        ssh_user = ssh_connector.get('username')
        if kwargs.get('user'):
            ssh_user = kwargs['user']
        if not ssh_user:
            ssh_user = "root"
        keyname = f"{username}-vmaas-sshkey"
        for sshkey in result['spec'].get('ssh_keys', []):
            if 'iam_ref' in sshkey and sshkey.get('name', '') == keyname:
                iam_ref = sshkey['iam_ref']
                break
        base_dir = sc.base_vmaas_dir()
        keydir = f"{base_dir}/iam-{keyname}"
        if not os.path.isdir(base_dir):
            os.mkdir(base_dir)
        if not os.path.isdir(keydir):
            os.mkdir(keydir)
        id_file_raw = f"{keydir}/id.raw"
        id_file = f"{keydir}/id.fixed"
        args = ["ssh"]
        if iam_ref:
            r = requests.get(f"{sc.engine()}/iam/{iam_ref}", headers=hdrs, verify=False)
            r.raise_for_status()
            req_json = r.json()
            if os.path.isfile(id_file_raw):
                if kwargs.get('download_id_file') or os.path.getmtime(id_file_raw) < req_json.get('ctime', 0):
                    os.unlink(id_file_raw)
                    if os.path.isfile(id_file):
                        os.unlink(id_file)
            if not os.path.isfile(id_file_raw):
                show_creds = "?show_creds=True"
                r = requests.get(f"{sc.engine()}/iam/{iam_ref}{show_creds}", headers=hdrs, verify=False)
                r.raise_for_status()
                req_json = r.json()
                ssh_key_data = json.loads(req_json['credentials'])
                val = base64.b64decode(ssh_key_data['config']['id']).decode('utf-8')
                with open(id_file_raw, 'w') as fp:
                    fp.write(val)
                os.chmod(id_file_raw, 0o600)
                newval = fix_ssh_private_key(val)
                with open(id_file, 'w') as fp:
                    fp.write(newval)
                os.chmod(id_file, 0o600)

            args.append('-i')
            args.append(id_file)

            if kwargs.get('download_id_file'):
                print(f"ID file is downloaded @ {id_file}")
                return

        if kwargs.get('ssh_opts'):
            for sshopt in kwargs['ssh_opts']:
                args.append(sshopt)

        args.append('-l')
        args.append(ssh_user)
        args.append("-p")
        args.append(f"{ssh_port}")

        args.append(ssh_host)
        # args = ["virtctl", f"--kubeconfig={cluster_config}", "console", vmname]
        # os.execvp("virtctl", args)
        # args = ["ssh", "-i", f"-kubeconfig={cluster_config}", "console", vmname]
        if kwargs.get('print_cmd'):
            print(" ".join(args))
            return
        # PyInstaller sets LD_LIBRARY_PATH to its temp dir; restore original so ssh
        # finds the system libcrypto instead of the bundled one.
        orig = os.environ.get('LD_LIBRARY_PATH_ORIG')
        if orig is not None:
            os.environ['LD_LIBRARY_PATH'] = orig
        elif 'LD_LIBRARY_PATH' in os.environ:
            del os.environ['LD_LIBRARY_PATH']
        if not shutil.which("ssh"):
            raise Exception("'ssh' binary not found in PATH")
        os.execvp("ssh", args)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for vm '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


