def vms_runwf(uid_arr, workflow, extra_payload=None):
    r = None
    hdrs = get_hdrs()
    if not uid_arr:
        raise Exception("Atleast one UID should be passed")

    data = {
        'uids': uid_arr,
        'wf_name': workflow,
    }
    url = f"{sc.engine()}/vm/wf/{workflow}"
    if len(uid_arr) == 1:
        url = f"{sc.engine()}/vm/wf/{workflow}/{uid_arr[0]}"

    if extra_payload:
        data.update(extra_payload)

    r = requests.put(url, json=data, verify=False, headers=hdrs)
    r.raise_for_status()
    _handle_vm_wfresp(",".join(uid_arr), r, hdrs)
    return r, hdrs, data


def _handle_vm_wfresp(uid, r, hdrs):
    uid_arr = []
    resp = r.json()
    wf_tracker = resp.get('wf_tracker')
    if uid:
        uid_arr = uid.split(',')
    else:
        uid_arr = resp['uid'].split(',')

    if wf_tracker:
        url = "{}/batch/bow/{}".format(sc.engine(), wf_tracker)
        res = requests.get(url, verify=False, headers=hdrs)
        res.raise_for_status()
        r1 = res.json()
        print()
        for batchid in r1.get('batches', []):
            print(f"{PROGRAM_NAME} batch info-bow {wf_tracker}")
            print(f"{PROGRAM_NAME} batch info {batchid}")
            for uid in uid_arr:
                print(f"{PROGRAM_NAME} batch logs {batchid} -e {uid}")
            print()
    else:
        print(resp.get('msg', ""))

@vm.command()
@click.argument('uid', type=str, nargs=-1)
@click.option('--vcpu', type=int, default=None, help='Set the number of vcpus that are visible inside guest')
@click.option('--cpu-request', type=str, default=None, help='Set the CPU requests at Kubernetes level')
@click.option('--cpu-limit', type=str, default=None, help='Set the CPU limits at Kubernetes level')
@click.option('--max-memory', type=str, default=None, help='Set the maximum guest-visible memory size for hotplug (format: Mi or Gi; enables memory hotplug)')
@click.option('--max-socket', type=int, default=None, help='Set the maximum number of CPU sockets for hotplug (enables CPU hotplug)')
@click.option('--memory-guest', type=str, default=None, help='Set the guest-visible memory size for live hotplug (format: Mi or Gi; requires maxGuest set at deploy time)')
@click.option('--memory-request', type=str, default=None, help='Set the memory requests at Kubernetes level (format: Mi or Gi only; no space)')
@click.option('--memory-limit', type=str, default=None, help='Set the memory limits at Kubernetes level (format: Mi or Gi only; no space)')
@click.option('--hugepages1g-request', type=str, default=None, help='Set the 1Gi hugepages requests at Kubernetes level')
@click.option('--hugepages1g-limit', type=str, default=None, help='Set the 1Gi hugepages limits at Kubernetes level')
@click.option('--hugepages2m-request', type=str, default=None, help='Set the 2Mi hugepages requests at Kubernetes level')
@click.option('--hugepages2m-limit', type=str, default=None, help='Set the 2Mi hugepages limits at Kubernetes level')
@click.option("--restart-option", type=click.Choice(['default', 'later', 'force']), default='default', help='Restart option (ignored when --hotplug is set)')
@click.option("--hotplug", is_flag=True, default=False, help='Apply compute changes live without restart (requires VM to support hotplug)')
@add_options(common_options)
def change_compute(uid, **kwargs):
    """Change compute for VM"""
    memory_pattern = re.compile(r'^[1-9][0-9]*(Mi|Gi)$')
    memory_options = [field for field in ['max_memory', 'memory_guest', 'memory_request', 'memory_limit'] if kwargs.get(field)]
    for field in memory_options:
        if not memory_pattern.match(kwargs[field]):
            error_msg = (f"Invalid format for --{field.replace('_', '-')}. "
                        "Only numeric characters (1-9) and unit ('Mi'/'Gi') are allowed. Must include unit.")
            handle_error(Exception(error_msg))

    hotplug = kwargs.pop('hotplug', False)
    _cold_compute_keys = [
        'cpu_request', 'cpu_limit',
        'max_memory', 'max_socket',
        'memory_limit', 'memory_request',
        'hugepages1g_request', 'hugepages1g_limit',
        'hugepages2m_request', 'hugepages2m_limit'
    ]
    if hotplug:
        if not kwargs.get('vcpu') and not kwargs.get('memory_guest'):
            handle_error(Exception("--hotplug requires --vcpu and/or --memory-guest"))
            return
        cold_only = [k for k in _cold_compute_keys if kwargs.get(k)]
        if cold_only:
            handle_error(Exception(f"--hotplug does not accept: {', '.join('--' + k.replace('_', '-') for k in cold_only)}"))
            return
    wfname = "vm-hotplugaddcompute" if hotplug else "vm-changecompute"

    try:
        r = hdrs = data = None
        r, hdrs, data = vms_runwf(uid, wfname, extra_payload=kwargs)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

