@click.option("--cold", is_flag=True, default=False, help="Cold-attach: modify VM spec and restart (default: False)")
@click.option("--no-persist", is_flag=True, default=False, help="Do not persist hotplug volume across VM restarts (default: False)")
@add_options(common_options)
def attach_disk(uid, volname, volcount, volsize, storage_class, restart_option, access_mode, volume_mode, cold, no_persist, **kwargs):
    """Attaches a disk to a VM (hotplug by default, use --cold to cold-attach)"""
    try:
        r = hdrs = data = None
        extra_payload = {}
        if volname:
            hdrs = get_hdrs()
            result, _ = get_vm_info(uid, hdrs)
            vm_vols = {v['name']: v for v in result.get('spec', {}).get('unattached_volumes', [])}
            if volname in vm_vols:
                vol_obj = vm_vols[volname]
                vm_name = result.get('metadata', {}).get('name', '')
                vm_prefix = f"{vm_name}-"
                stripped_volname = volname[len(vm_prefix):] if volname.startswith(vm_prefix) else volname
                is_hotplug = vol_obj.get('hotplugVolume') or vol_obj.get('hotpluggable') or 'hotplug' in stripped_volname

                # for hotplug re-attach, ensure that --cold is not passed
                if is_hotplug:
                    if cold:
                        raise Exception(f"Volume '{volname}' is a hotplug volume. Do not pass the --cold option to re-attach.")

                # for coldplug re-attach, ensure that --cold is passed
                else:
                    if not cold:
                        raise Exception(f"Volume '{volname}' is a coldplug volume. Pass the --cold option to re-attach.")
            extra_payload['volname'] = volname
        else:
            if volcount:
                extra_payload['volcount'] = volcount
            if volsize:
                extra_payload['volsize'] = volsize
            if storage_class:
                extra_payload['storage_class'] = storage_class
            if access_mode:
                extra_payload['access_mode'] = access_mode
            if volume_mode:
                extra_payload['volume_mode'] = volume_mode
        if restart_option:
            extra_payload['restart_option'] = restart_option
        if no_persist:
            extra_payload['persist'] = False
        if cold: 
            msg = f"Attaching COLDPLUG volume to vm {uid}"
            wf_name = "vm-attachvol"
        else:
            msg = f"Attaching HOTPLUG volume to vm {uid}"
            wf_name = "vm-hotplugaddvol"
        r, hdrs, data = vms_runwf([uid], wf_name, extra_payload=extra_payload)
        print(msg)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

