@vm.command(aliases=[])
@click.argument('uid', type=str, nargs=-1)
@click.option("--ippool-uids", type=str, multiple=True, help="Specify IPPOOL UIDs.")
@click.option("--ippool-names", type=str, multiple=True, help="Specify IPPOOL names.")
@click.option("--restart-option", type=click.Choice(['default', 'later', 'force']), default='default', help="Restart option for VM")
@click.option("--skip-workflow", is_flag=True, default=False, help="Skip workflow submission (only allocate IPs and update VM spec)")
@click.option('--genplan', is_flag=True, type=bool, default=False, help="Generate plan (allocate IPs and return VM details)")
@click.option('-o', '--output', type=click.Choice(['json', 'yaml']), default=None, help="Output plan format")
@click.option("--static-ips", type=str, multiple=True, help="Specify static IP(s) per IPPOOL (format: ippool_name=IP[,IP,...] or ippool_uid=IP[,IP,...])")
@click.option("--netindex", type=str, multiple=True, help="Specify insertion index per network (format: netname=INDEX)")
@add_options(common_options)
def add_network(uid, ippool_uids, ippool_names, restart_option, skip_workflow, genplan, output, static_ips, netindex, **kwargs):
    """Add network(s) to VM"""
    try:
        r = hdrs = data = None
        if ippool_uids and ippool_names:
            raise Exception("Provide either --ippool-uids or --ippool-names, not both")
        if not ippool_uids and not ippool_names:
            raise Exception("Either --ippool-uids or --ippool-names must be provided")
        extra_payload = {
            'restart_option': restart_option,
            'skip_workflow': skip_workflow,
            'genplan': genplan
        }
        if ippool_uids:
            extra_payload['ippool_uids'] = ippool_uids
        if ippool_names:
            extra_payload['ippool_names'] = ippool_names
        if static_ips:
            static_ips_dict = {}
            for item in static_ips:
                if '=' not in item:
                    raise Exception(f"Invalid --static-ips format: '{item}'. Expected 'ippool_name=IP[,IP,...]'")
                key, ip_str = item.split('=', 1)
                static_ips_dict[key.strip()] = ip_str.strip()
            extra_payload['static_ips'] = static_ips_dict
        if netindex:
            netindex_dict = {}
            for item in netindex:
                if '=' not in item:
                    raise Exception(f"Invalid --netindex format: '{item}'. Expected 'netname=INDEX'")
                netname, idx_str = item.split('=', 1)
                netindex_dict[netname.strip()] = int(idx_str.strip())
            extra_payload['netindex'] = netindex_dict
        r, hdrs, data = vms_runwf(uid, "vm-addnetwork", extra_payload=extra_payload)
        if genplan:
            resp = r.json()
            if output == 'json':
                print(json.dumps(resp, indent=4))
                return
            if output == 'yaml':
                print(yaml.dump(resp, default_flow_style=False))
                return
            if resp.get('plan'):
                print_addnetwork_plan(resp)
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

