def _validate_retention_time(ctx, param, value):
    if value is None:
        return None
    value = value.strip().lower()
    if len(value) < 2 or value[-1] not in ('d', 'h') or not value[:-1].isdigit() or int(value[:-1]) == 0:
        handle_error(Exception(f"'{value}' is invalid. Provide days or hours only (example: 7d or 10h)."), action_msg="Invalid --retention-time.")
    return value


def _validate_retention_count(ctx, param, value):
    if value is not None and value < 1:
        handle_error(Exception(f"'{value}' is invalid. Value must be 1 or more."), action_msg="Invalid --retention-count.")
    return value


def _validate_cron(ctx, param, value):
    # An unquoted cron string is split by the shell (and '*' expanded to file names), so only its first field arrives here
    if value is not None and len(value.split()) < 5:
        handle_error(Exception(f"Please wrap the valid cron expression in quotes, e.g. --cron '30 * * * *'."), action_msg=f"Invalid --cron passed: {value}.")
    return value


def _fmt_exec_time(ts):
    return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts)) if ts else '-'


def _list_vm_schedules(sched_type, status, name, output, limit, offset, **kwargs):
    try:
        r = hdrs = None
        hdrs = get_hdrs()
        q_params = []
        if limit:
            q_params.append(f"limit={limit}")
        if offset:
            q_params.append(f"offset={offset}")
        if name:
            q_params.append(f"name={name}")
        if status:
            q_params.append(f"status={status}")
        url_params = parameter_string(q_params) if q_params else ""
        r = requests.get(f"{sc.engine()}/vm/{sched_type}-schedule{url_params}", verify=False, headers=hdrs)
        r.raise_for_status()
        if output == 'json':
            print(json.dumps(r.json()))
        else:
            headers = ['uid', 'name', 'userid', 'state', 'cron', 'lastexec', 'nextexec', 'errmsg']
            rows = [[d['uid'], d['name'], d.get('userid') or '', d['state'], d['cron'],
                     _fmt_exec_time(d['lastexec']), _fmt_exec_time(d['nextexec']), d['errmsg']] for d in r.json()['schedule']]
            print(tabulate(rows, headers=headers, tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to list {sched_type} schedules.")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


def _info_vm_schedule(sched_type, uid, output, **kwargs):
    try:
        r = hdrs = None
        hdrs = get_hdrs()
        r = requests.get(f"{sc.engine()}/vm/{sched_type}-schedule/{uid}", verify=False, headers=hdrs)
        r.raise_for_status()
        if output == 'json':
            print(json.dumps(r.json()))
        else:
            d = r.json()['schedule']
            vm_uids = d['spec'].get('request', {}).get('payload', [{}])[0].get('elements', [])
            print(f"\nuid         : {d['uid']}")
            print(f"name        : {d['name']}")
            print(f"VM          : {', '.join(vm_uids)}")
            print(f"Status      : {d['state']}")
            print(f"Cron        : {d['cron']}")
            if sched_type == 'backup':
                print(f"Repo        : {d.get('reponame') or '-'}")
            print(f"Retention time  : {d.get('retention_time') or '-'}")
            print(f"Retention count : {d.get('retention_count') or '-'}")
            print(f"\nnextexec    : {_fmt_exec_time(d['nextexec'])}")
            print(f"lastexec    : {_fmt_exec_time(d['lastexec'])}")
            print(f"Errmsg      : {d['errmsg'] or '-'}")
            print("\nBatch/Workflow Trackers :")
            for idx, tracker in enumerate(d['trackers']):
                print(f"{idx}   : {tracker} \n")
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to fetch {sched_type} schedule.")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)


