@vm.command(hidden=True)
@click.argument('uid', type=str)
@add_options(common_options)
def add_guacamole_user(uid, **kwargs):
    """Adds guacamole user and returns a token to access a VM"""
    try:
        hdrs = get_hdrs()
        r = None
        data = {}
        r = requests.put(f"{sc.engine()}/vm/guacamole-token/{uid}", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()

        vmobj, r = get_vm_info(uid, hdrs)
        for ckey, cobj in vmobj['spec'].get('connectors', {}).items():
            if cobj.get('connect_url'):
                val = base64.b64decode(cobj['connect_url']).decode('utf-8')
                final_url = val + f"?token={result['token']}"
                print(f"{ckey} connect url ==> {final_url}")
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)


