@apploadbalancer.command()
@click.argument("name", type=str)
@click.option('--cluster', type=str, help="Cluster name", required=True)
@click.option('--namespace', type=str, help="Namespace name")
@click.option('--ippool', type=str, help="Loadbalancer type IPPool name")
@click.option('--ippool-uid', type=str, help="Loadbalancer type IPPool uid")
@click.option('--listener', type=str, help="Comma separated list of listeners which needs to be created with the loadbalancer [lisener-name]:[protocol]:[port] eg: tcp:80,udp:81", required=True)
@click.option('--vpc', type=str, help="VPC name which the loadbalancer will be attached to")
@click.option('--vpc-uid', type=str, help="VPC uid which the loadbalancer will be attached to")
@click.option('--allow-ippool', type=str, help="Comma separated list of IPPool name which the loadbalancer will be allowed to")
@click.option('--allow-cidr', type=str, help="CIDR which the loadbalancer will be allowed to")
@click.option("--external-traffic-policy", default=None, type=click.Choice(['Cluster', 'Local']))
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the loadbalancer key:value")
@click.option('--dryrun', is_flag=True, type=bool, default=False, help="Dryrun", hidden=True)
@add_options(common_options)
def create(name, cluster, namespace, ippool, ippool_uid, listener, vpc, vpc_uid, **kwargs):
    """Create an APPLOADBALANCER deprecated, use register with a config file instead"""
    try:
        spec_infra = {}

        if not ippool and not ippool_uid:
            raise Exception(f"At least one of --ippool or --ippool-uid should be passed")

        obj = {'kind': "IPPOOL"}
        if ippool_uid:
            obj['elem_uid'] = ippool_uid
        else:
            obj['elem_name'] = ippool
        spec_infra['ippool'] = obj
        if not vpc and not vpc_uid:
            raise Exception(f"At least one of --vpc or --vpc-uid should be passed")
        obj = {'kind': "VPC"}
        if vpc_uid:
            obj['elem_uid'] = vpc_uid
        else:
            obj['elem_name'] = vpc
        spec_infra['vpc'] = obj

        allow_subnet = {}
        if not kwargs.get('allow_ippool') and not kwargs.get('allow_cidr'):
            raise Exception(f"At least one of --allow-ippool or --allow-cidr should be passed")
        if kwargs.get('allow_ippool'):
            allow_ippool = []
            for ippool_name in kwargs.get('allow_ippool').split(','):
                ippool_obj = {'kind': "IPPOOL", 'elem_name': ippool_name.strip()}
                allow_ippool.append(ippool_obj)
            allow_subnet['ippool'] = allow_ippool
        if kwargs.get('allow_cidr'):
            allow_cidr = []
            for cidr in kwargs.get('allow_cidr').split(','):
                allow_cidr.append(cidr.strip())
            allow_subnet['cidr'] = allow_cidr

        listeners = []
        if listener:
            listener_list = [x.strip() for x in listener.split(',')]
            for lst in listener_list:
                _arr = lst.split(':')
                if len(_arr) != 3:
                    raise Exception(f"Listener {lst} format invalid. Should be name:protocol:port")
                listeners.append({'name': _arr[0], 'protocol': _arr[1].lower(), 'port': int(_arr[2])})

        spec = {
            'infra': spec_infra,
            'cluster': cluster,
            'namespace': namespace,
            'listeners': listeners,
            'allow_subnet': allow_subnet
            }
        if kwargs.get('external_traffic_policy'):
            spec['external_traffic_policy'] = kwargs['external_traffic_policy']

        labels = {}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "APPLOADBALANCER",
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs.get('description') or name
            },
            "spec": spec
        }

        if kwargs.get('dryrun'):
            print(json.dumps(data, indent=4))
            return

        r = None
        hdrs = get_hdrs()
        r = requests.post(f"{sc.engine()}/apploadbalancer", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
        raise
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

@apploadbalancer.command()
@click.argument('uid', type=str)
@click.option('--name', type=str, required=True, help="Name for the listener")
@click.option('--protocol', type=click.Choice(['TCP', 'UDP', 'HTTP', 'HTTPS', 'TLS'], case_sensitive=False), required=True, help="Protocol for the listener")
@click.option('--port', type=int, required=True, help="Port for the listener (1-65535)")
@click.option('--hostname', type=str, help="Hostname for the listener (applicable for HTTP/HTTPS/TLS)")
@click.option('--tls-mode', type=click.Choice(['Terminate', 'Passthrough'], case_sensitive=False), help="TLS mode for the listener (applicable for HTTPS/TLS)")
@click.option('--certificate-refs', type=str, help="Comma separated list of certificate references (applicable for HTTPS/TLS), secret type certification")
@add_options(common_options)
def add_listener(uid, name, protocol, port, **kwargs):
    """Add a listener to APPLOADBALANCER"""
    try:
        if port < 1 or port > 65535:
            raise click.ClickException("Port must be in range 1-65535")

        data = {
            'lb_uid': uid,
            'name': name,
            'protocol': protocol.upper(),
            'port': port
        }

        if kwargs.get('hostname'):
            data['hostname'] = kwargs.get('hostname')
        if protocol.upper() in ['HTTPS', 'TLS']:
            if not kwargs.get('tls_mode'):
                raise click.ClickException("TLS mode is required for HTTPS/TLS listeners")
            data['tls'] = {'mode': kwargs.get('tls_mode').capitalize()}
            if kwargs.get('certificate_refs'):
                cert_refs = [x.strip() for x in kwargs.get('certificate_refs').split(',')]
                data['tls']['certificate_refs'] = cert_refs

        r = None
        hdrs = get_hdrs()
        url = f"{sc.engine()}/apploadbalancer/listener"
        r = requests.post(url, json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        print(result['msg'])
        if result.get('wf_tracker'):
            print(f"Workflow tracker: {result['wf_tracker']}")

    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

