@flavor.command()
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@add_options(common_options)
def list(index, labels, match, output, **kwargs):
    """List all FLAVOR elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/flavor{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return

        results = r.json()
        if not results['items']:
            print("No results found")
            return

        data = []
        headers = ["UID", "Name", "Owner", "QOSClass", "CPU req/lmt (vCPU)", "Mem req/lmt", "#Disks/Gi", "StorageClass", "AccessMode"]
        for item in results['items']:
            total_size = 0
            metadata = item['metadata']
            cfg = item['spec']['flavor_config']
            req = cfg.get('resources', {}).get('requests', {})
            lim = cfg.get('resources', {}).get('limits', {})
            owner = get_element_owner(item)
            if not req:
                qosclass = "BestEffort"
            else:
                for key, val in req.items():
                    if key not in lim or val != lim[key]:
                        qosclass = "Burstable"
                        break
                else:
                    qosclass = "Guaranteed"
                    if len(req.keys()) != len(lim.keys()):
                        qosclass = "Busrtable"
            memory = req.get('memory', "").replace("Gi", "")
            vcpu = req.get('cpu', "")
            if cfg.get('sockets') and cfg.get('threads') and cfg.get('cores'):
                vcpu = int(cfg['cores']) * int(cfg['threads']) * int(cfg['sockets'])
            all_disks = []
            if cfg.get('rootdisk'):
                all_disks.append(cfg['rootdisk'])
            all_disks += cfg.get('disks', [])
            num_disks = len(all_disks)
            for disk_item in all_disks:
                total_size += int(disk_item['size'].replace('Gi', ''))
            cpu_str = f"{req.get('cpu', '-')}/{lim.get('cpu', '-')} ({vcpu})"
            mem_str = f"{req.get('memory', '-')}/{lim.get('memory', '-')}"
            access_mode = cfg.get('accessMode', 'ReadWriteOnce')
            access_mode = "rwx" if access_mode == "ReadWriteMany" else "rwo"
            disk_str = f"{num_disks}/{total_size}"
            data.append([metadata['uid'], metadata['name'], owner, qosclass, cpu_str, mem_str, disk_str, cfg['storageClassName'], access_mode])
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += f"Displaying {results['count']}/{results['limit']} elements from offset {results['offset']}\n"
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list flavors. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

