@flavor.command()
@click.argument('name', type=str)
@click.option('--storage-class', help="Default storage class", required=True)
@click.option("-q", "--qosclass", type=click.Choice(['guaranteed', 'besteffort', 'burstable']), required=True)
@click.option("--access-mode", type=click.Choice(['ReadWriteOnce', 'ReadWriteMany']), default=None)
@click.option('--cpu', type=int, help="Number of CPUs to be allocated by K8s. Requests", default=1)
@click.option('--vcpu', type=int, help="Number of vCPUs visible inside the VM", default=None)
@click.option('--memory', type=int, help="Amount of Memory(GB) to be allocated. Requests", default=4)
@click.option('--disks', type=int, help="Number of #disks attached to the VM(including root disk)", default=1)
@click.option('--disk-size', type=int, help="Size of disk attached to the VM", default=20)
@click.option('--thin-provision', is_flag=True, type=bool, default=False, help="ThinProvision for robinlocal volumes")
@click.option('--block-size', type=int, help="BlockSize of disk attached to the VM", default=4096)
@click.option('--description', help="Description", required=False)
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the flavor.key:value")
@add_options(common_options)
def create(name, **kwargs):
    """Generate a config file of a FLAVOR"""
    try:
        ret = {
            'storageClassName': kwargs['storage_class'],
            'rootdisk': {
                'size': "{}Gi".format(kwargs['disk_size'])
            },
            "disks": [],
            'resources': {
                'requests': {
                    'cpu': "{}".format(kwargs['cpu']),
                    'memory': "{}Gi".format(kwargs['memory'])
                }
            }
        }
        if kwargs.get('access_mode'):
            ret['accessMode'] = kwargs['access_mode']

        tmp_dict = {}
        vcpu = kwargs['cpu']
        if kwargs.get('vcpu'):
            vcpu = kwargs['vcpu']
            tmp_dict = {'cores': 1, 'sockets': kwargs['vcpu'], 'threads': 1}
        dedicatedCpuPlacement = False
        qosclass = kwargs['qosclass']
        if qosclass == "guaranteed":
            ret['resources']['limits'] = {
                'cpu': "{}".format(kwargs['cpu']),
                'memory': "{}Gi".format(kwargs['memory'])
            }
            if vcpu == kwargs['cpu']:
                dedicatedCpuPlacement = True

        if dedicatedCpuPlacement:
            ret['dedicatedCpuPlacement'] = True
        elif vcpu != kwargs['cpu']:
            ret.update(tmp_dict)

        num_data_disks = kwargs['disks'] - 1
        for i in range(num_data_disks):
            index = i + 1
            disk = {
                'size': "{}Gi".format(kwargs['disk_size']),
                'name': "data{}".format(index),
                'bus': "virtio"
            }
            annotations = []
            if kwargs['storage_class'].startswith("robin-local"):
                if 'thin_provision' in kwargs:
                    tp_str = "yes" if kwargs['thin_provision'] else "no"
                    annotations.append({'key': "robinlocal.csi.k8s.io/thin_provision", 'value': tp_str})
                if kwargs.get('block_size'):
                    annotations.append({'key': "robinlocal.csi.k8s.io/block_size", 'value': "{}".format(kwargs['block_size'])})
                    disk['block_size'] = {'physical': kwargs['block_size'], 'logical': kwargs['block_size']}
            if annotations:
                disk['annotations'] = annotations
            ret['disks'].append(disk)

        labels = {}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]
        labels['crtype'] = 'flavor'

        if not kwargs.get('description'):
            kwargs['description'] = f"{name}-description"

        config = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "FLAVOR",
            "name": name,
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs['description']
            },
            "spec": {
                "name": name,
                "flavor_config": ret,
            }
        }
        print(json.dumps(config, indent=4))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to generate workflow {} for FLAVOR {}. ".format(workflow, name))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)
