@image.command()
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option('--workspace', is_flag=True, type=bool, default=False, help="Show Only WORKSPACE images")
@click.option('--upgrade', type=str, help="Show Only upgradeable images for specified UID")
@click.option('--downgrade', type=str, help="Show Only dwongradeable images for specified UID")
@add_options(common_options)
def list(index, labels, match, output, workspace, upgrade, downgrade, **kwargs):
    """List all IMAGE elements"""
    try:
        r = None
        hdrs = get_hdrs()
        new_labels = labels
        if workspace:
            new_labels = ("workspace:true",) + labels
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(new_labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        if upgrade:
            query_params.append(f"upgrade={upgrade}")
        elif downgrade:
            query_params.append(f"downgrade={downgrade}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/image{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        results = r.json()
        if not results['items']:
            print("No results found")
            return
        else:
            data = []
            headers = ["uid", "name", "owner", "type", "port", "user", "repo", "file"]
            for item in results['items']:
                metadata = item['metadata']
                cfg = item['spec']['image_config']
                owner = get_element_owner(item)
                filename = os.path.basename(cfg['image']['url'])
                # If this is a registry path. extract the hostname portion
                image_url = cfg['image']['url']
                if not image_url.startswith('http'):
                    image_url = f"http://{image_url}"
                result = urllib.parse.urlparse(image_url)
                repo = result.netloc
                def_port = cfg['image'].get('default_port') or "-"
                def_user = cfg['image'].get('default_user') or "-"
                data.append([metadata['uid'], metadata['name'], owner, cfg['image']['image_type'], def_port, def_user, repo, filename])
            print(tabulate(data, headers, tablefmt="pretty"))
            footer = '\n--------------------------------------------\n'
            footer += "Displaying {}/{} elements from offset {}\n".format(results['count'], results['limit'], results['offset'])
            footer += '--------------------------------------------\n'
            print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list images. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

