@image.command()
@click.argument('name', type=str)
@click.argument('path', type=str)
@click.option('--image-type', type=click.Choice(['qcow2', 'iso']), required=True)
@click.option('--bus', type=str, help="Image disk bus", default="virtio", required=False)
@click.option('--default-port', type=int, help="Default port to check when VM boots up", default=22, required=False)
@click.option('--default-user', type=str, help="Default user to connect to VM", default="root", required=False)
@click.option('--default-password', type=str, help="Default password to connect to VM", required=False)
@click.option('--ostype', help="Ostype of the image", type=click.Choice(['linux', 'windows']), default=None, required=True)
@click.option('--vnc-password', type=str, help="VNC password of the image", required=False)
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the image.key:value")
@click.option('--verify', is_flag=True, default=False,
              help="Also hash the local file and compare it with the sha256 artifactory recorded (reads the file once more)")
@add_options(common_options)
def upload(name, path, image_type, verify, **kwargs):
    """Upload IMAGE"""
    bus = kwargs['bus']
    default_port = kwargs['default_port']
    default_user = kwargs['default_user']
    default_password = kwargs['default_password']
    ostype = kwargs['ostype']
    vnc_password = kwargs.get('vnc_password')

    if not os.path.isfile(path):
        raise click.UsageError(f"File not found: {path}")

    base_url = '/'.join(sc.engine().split('/')[:-3])
    url = f"{base_url}/artifact/api/v1/vmaas/{os.path.basename(path)}"
    url_type = "http"
    cert_url = f"{base_url}/artifact/api/v1/bmaas/archive/cno-tls-cert/cert.pem"

    ret = {
        "image": {
            "bus": bus,
            "default_user": default_user,
            "image_type": image_type,
            "default_port": default_port,
            "ostype": ostype,
            "url_type": url_type,
            "url": url
        }
    }
    if default_password:
        ret['image']['default_password'] = default_password
    if vnc_password:
        ret['image']['vnc_password'] = vnc_password
    ret['image']['cert_url'] = cert_url

    labels = {}
    for item in kwargs.get('labels', []):
        _arr = item.split(':')
        labels[_arr[0]] = _arr[1]
    labels['crtype'] = 'image'

    config = {
        "apiVersion": "mdcap.robin.io/v1",
 	    "kind": "IMAGE",
        "name": name,
 	    "metadata": {
            "name": name,
            "labels": labels,
            "description": "IMAGE for {}".format(name)
        },
        "spec": {
            "image_config": ret
        }
    }
    try:
        r = None
        hdrs = get_hdrs()
        local_sha256 = None
        if verify:
            print(f"Computing sha256 of {os.path.basename(path)}...")
            local_sha256 = _file_sha256(path)
        if not upload_to_robin_artifactory(url, path, progress=True, headers=CHECKSUM_HEADERS):
            raise Exception("Failed to upload image. Please check artifactory logs")
        print(f"Uploaded {os.path.basename(path)} successfully to {url}")

        try:
            server_sha256 = _server_sha256(url)
        except Exception:
            if verify:
                raise
            server_sha256 = None
        if server_sha256:
            if local_sha256 and server_sha256 != local_sha256:
                raise Exception(f"sha256 mismatch: local {local_sha256}, artifactory {server_sha256}. "
                                f"The upload was corrupted, run upload again")
            print(f"sha256: {server_sha256}{' (verified)' if local_sha256 else ''}")
        elif verify:
            print("Skipped verification: artifactory did not record a checksum")

        r = requests.post(f"{sc.engine()}/image", json=config, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex, action_msg=f"Failed to upload image '{name}'. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=config)
