@ippool.command()
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--full", is_flag=True, default=False, help="Display all columns including VPC and private")
@click.option("--cluster", type=str, default=None, help="Filter by cluster name")
@click.option("--type", 'ippool_type', type=str, default=None, help="Filter by type label (e.g. vmnet, elastic, loadbalancer)")
@click.option("--tenant", type=str, default=None, help="Filter by tenant name (admin or tenant-admin only)")
@click.option("--tenant-uid", type=str, default=None, help="Filter by tenant UID (admin or tenant-admin only)")
@add_options(common_options)
def list(index, labels, match, output, full, cluster, ippool_type, tenant, tenant_uid, **kwargs):
    """List all IPPOOL elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        if cluster:
            labels = labels + (f"cluster:{cluster}",)
        if ippool_type:
            labels = labels + (f"{ippool_type}:true",)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        if tenant:
            query_params.append(f"tenant={tenant}")
        if tenant_uid:
            query_params.append(f"tenant_uid={tenant_uid}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/ippool{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()
        results = r.json()

        if not results['items'] and not labels and not match:
            r = requests.get(f"{sc.engine()}/vm/vmaas-objects/", verify=False, headers=hdrs)
            r.raise_for_status()
            res = r.json()
            results = {'items': [], 'count': 0, 'limit': 0}
            for clus in res.get('robinclusters', []):
                for x in clus.get('networks', []):
                    results['items'].append(x)
                    results['count'] += 1
            results['limit'] = results['count']
            results['offset'] = 0

        if output == 'yaml':
            print(yaml.dump(results, indent=4))
            return

        if output == 'json':
            print(json.dumps(results, indent=4))
            return

        if not results['items']:
            print("No results found")
            return

        data = []
        if full:
            headers = ["uid", "name", "type", "driver", "cluster", "netname", "VPC", "private", "iprange", "Total/Used/Free", "CNP-IPPOOL"]
        else:
            headers = ["uid", "name", "type", "driver", "cluster", "netname", "iprange", "Total/Used/Free", "CNP-IPPOOL"]

        for item in results['items']:
            metadata = item['metadata']
            if not item.get('spec'):
                item['spec'] = metadata['labels']
            is_robin_ippool = bool(item['spec'].get('robin_ippool'))
            cluster = item['spec']['cluster']
            netname = item['spec']['netname']
            driver = item['spec'].get('driver', "-")
            itype = item['spec'].get('type', "")
            laytype = None
            private = "-"
            vpc = "-"
            if driver in ["default", "calico"]:
                laytype = "overlay"
            elif driver in ["ovs-secondary", "ovs", "sriov", "macvlan"]:
                laytype = "underlay"
            elif driver in ["ovn", "kubeovn"]:
                if item['spec'].get('cluster_vpc'):
                    laytype = "overlay"
                elif item['spec'].get('vlan'):
                    laytype = "underlay"
                if item['spec'].get('cluster_vpc'):
                    vpc = item['spec']['cluster_vpc']
            if laytype:
                itype += f"({laytype})"
            if 'private' in item['spec']:
                private = f"{item['spec']['private']}".lower()
            iprange = "-"
            ipv6range = "-"
            if driver in ["ovn", "kubeovn"] and item['spec'].get('cidr_block'):
                iprange = item['spec']['cidr_block']
            elif item['spec'].get('robin_config'):
                ranges = [f"{x['range']}/{item['spec']['robin_config'].get('cidrs', '-')}" for x in item['spec']['robin_config'].get('ranges', [])]
                iprange = ",".join(ranges)
            elif item['spec'].get('iprange'):
                iprange = item['spec']['iprange']
                for _rng in item['spec'].get('additional_ipranges', []):
                    iprange += f",{_rng}"
            elif item['spec'].get('iprange_display'):
                iprange = item['spec']['iprange_display']
            elif item['spec'].get('ipv4_addr_template'):
                iprange = item['spec']['ipv4_addr_template']
            elif item['spec'].get('ipv6_range'):
                iprange = item['spec']['ipv6_range']
            elif item['spec'].get('metallb_net'):
                iprange = ",".join(item['spec']['metallb_net'])
            elif item['spec'].get('cidr_block'):
                iprange = item['spec']['cidr_block']
            # Get IP statistics
            total_ips = item['spec'].get('total', '-')
            used_ips = item['spec'].get('used', '-')
            reserved_ips = item['spec'].get('reserved', '-')
            if used_ips != '-' and reserved_ips != '-':
                used_ips = int(used_ips) + int(reserved_ips)
            available_ips = '-'
            if used_ips != "-" and total_ips != "-":
                available_ips = int(total_ips) - int(used_ips)
            ip_stats = f"{total_ips}/{used_ips}/{available_ips}"
            if driver in ["ovs-secondary"]:
                ip_stats = "N/A"

            robin_ippool_indicator = "✓" if is_robin_ippool else ""

            if full:
                data.append([metadata.get('uid', "-"), metadata['name'], itype, driver, cluster, netname, vpc, private, iprange, ip_stats, robin_ippool_indicator])
            else:
                data.append([metadata.get('uid', "-"), metadata['name'], itype, driver, cluster, netname, iprange, ip_stats, robin_ippool_indicator])
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += "Displaying {}/{} elements from offset {}\n".format(results['count'], results['limit'], results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list ippools. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

