@ippool.command()
@click.argument('uid', type=str)
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--evaluate", is_flag=True, help="Evaluate any properties referenced from registry within the IPPOOL config")
@click.option("-t", "--tenants", is_flag=True, help="Get tenants details as well")
@click.option("--allocations", is_flag=True, default=False, help="Show child allocations (VMs using this IPPOOL)")
@click.option("--expand", is_flag=True, default=False, help="Expand IPPOOL config with referenced registry values")
@add_options(common_options)
def info(uid, output, evaluate, tenants, allocations, expand, **kwargs):
    """Get information on a particular IPPOOL element"""
    try:
        r = None
        hdrs = get_hdrs()
        evaluate_str = "&evaluate=true" if evaluate else ""
        t_str = "&tenants=true" if tenants else ""
        alloc_str = "&allocations=true" if allocations else ""
        expand_str = "&expand=true" if expand else ""
        r = requests.get(f"{sc.engine()}/ippool/{uid}?dummy=true{evaluate_str}{t_str}{alloc_str}{expand_str}", verify=False, headers=hdrs)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        result = r.json()
        if not result:
            print("ippool '{}' does not exist".format(uid))
        else:
            #hdrs = ['uid', 'type', 'name', 'description']
            print("Name: {}".format(result['metadata']['name']))
            print("UUID: {}".format(result['metadata']['uid']))
            print("Description: {}".format(result['metadata']['description'] if result['metadata']['description'] else "-"))
            print()
            if result['spec']:
                print()
                print("Additional Config:")
                print_nested(result['spec'], indent=0)
            if result.get('tenants'):
                print("Tenants:")
                print_nested(result['tenants'], indent=0)
            if result.get('allocations'):
                print()
                print("Allocations:")
                alloc_data = []
                for alloc in result['allocations']:
                    alloc_data.append([
                        alloc.get('eid') or '-',
                        alloc.get('eid_name') or '-',
                        alloc.get('eid_kind') or '-',
                        alloc.get('username') or '-',
                        alloc.get('namespace') or '-',
                        alloc.get('ipv4') or '-',
                        alloc.get('ipv6') or '-',
                        alloc.get('reserved', False),
                        alloc.get('cnp_app_name') or '-',
                        alloc.get('cnp_app_ns') or '-',
                        alloc.get('details', {}).get('resource') or '-',
                    ])
                print(tabulate(alloc_data, headers=["UID", "Name", "Kind", "Username", "Namespace", "IPv4", "IPv6", "Reserved", "CNP-App", "CNP-NS", "Resource"], tablefmt="pretty"))
    except Exception as ex:
        handle_error(ex, action_msg="Failed to display information for ippool '{}'. ".format(uid))
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

