@ippool.command()
@click.argument("netname", type=str)
@click.argument("cluster", type=str)
@click.argument("driver", type=click.Choice(["ovs", "ovn", "macvlan", "metallb", "sriov"]))
@click.option('--type', type=click.Choice(['vmnet', 'elastic', 'loadbalancer']), help="Type (pass option more than once for multiple types)", required=True, multiple=True)
@click.option('--name', type=str, help="Name of the ippool. Default is <cluster>-<netname>", required=False)
@click.option('--iprange', type=str, help="Iprange <ip-range>/<cidr>")
@click.option('--cidr-block', type=str, help="CIDR-Block <subnet>/<cidr>")
@click.option('--cluster-vpc', type=str, help="VPC name")
@click.option("--protocol", type=click.Choice(['IPv4', 'IPv6']))
@click.option('--mtu', type=int, help="MTU")
@click.option('--gateway', type=str, help="Gateway")
@click.option('--netmask', type=str, help="Netmask")
@click.option('--bridge', type=str, help="Bridge")
@click.option('--domain', type=str, help="Domain")
@click.option('--dns', type=str, help="DNS")
@click.option('--search', type=str, help="Search")
@click.option('--ipv6-enabled', is_flag=True, help="Assign ipv6 address as well", default=False)
@click.option('--ipv6-addr-template', type=str, help="ipv6 address template")
@click.option('--ipv4-addr-template', type=str, help="ipv4 address template")
@click.option('--gateway6', type=str, help="ipv6 gateway")
@click.option('--dns6', type=str, help="ipv6 DNS")
@click.option('--load-balancer-class', type=str, help="LoadBalancer class")
@click.option('--metallb-class', type=str, help="Metal LB class")
@click.option('--metallb-pool-name', type=str, help="Metal LB pool name")
@click.option('--metallb-net', type=str, multiple=True, help="Metal LB network list (pass option more than once for multiple entries)")
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the ippool key:value")
@add_options(common_options)
def generate_config(netname, cluster, driver, type, **kwargs):
    """Generate a config file for IPPOOL"""
    try:
        name = f"{cluster}-{netname}"
        if kwargs.get('name'):
            name = kwargs['name']
        spec = {
            "name": name,
            "netname": netname,
            "cluster": cluster,
            "description": kwargs.get('description') or name,
            "driver": driver,
            "type": ",".join(type)
        }

        labels = {'netname': netname, 'cluster': cluster, 'crtype': "ippool", 'driver': driver}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        for key in ["mtu", "gateway", "netmask", "bridge", "domain", "dns", "search", "ipv6_enabled", "ipv6_addr_template", "dns6", "gateway6"]:
            if kwargs.get(key):
                spec[key] = kwargs[key]

        if driver == "default":
            for key in ["iprange", "load_balancer_class"]:
                if kwargs.get(key):
                    spec[key] = kwargs[key]
        elif driver == "metallb":
            for key in ["metallb_class", "metallb_pool_name", "metallb_net"]:
                if kwargs.get(key):
                    spec[key] = kwargs[key]
        elif driver in ["kubeovn", "ovn"]:
            for key in ["cidr_block", "protocol", "cluster_vpc"]:
                if kwargs.get(key):
                    spec[key] = kwargs[key]
        elif driver in ["macvlan", "ovs", "sriov"]:
            if not kwargs.get('iprange') and not kwargs.get('ipv4_addr_template'):
                raise Exception("IPrange and IPV4AddrTemplate both cannot be empty")
            if kwargs.get('iprange'):
                spec['iprange'] = kwargs['iprange']
            elif kwargs.get('ipv4_addr_template'):
                spec['ipv4_addr_template'] = kwargs['ipv4_addr_template']

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "IPPOOL",
            "metadata": {
                "name": name,
                "labels": labels
            },
            "spec": spec
        }
        print(json.dumps(data, indent=4))
    except Exception as ex:
        import traceback
        traceback.print_exc()
        handle_error(ex, action_msg="Failed to generate ippool config. ")
