@nwepgroup.command()
@click.argument("name", type=str)
@click.option('--infra', type=str, multiple=True, help="VM name (or UID) to add to the group; repeat for several. Use this or --selector")
@click.option('--selector', type=str, multiple=True, help="Pod label key=value that selects the member pods; repeat for several. Requires --cluster and --namespace")
@click.option('--cluster', type=str, help="Cluster name (with --selector)")
@click.option('--namespace', type=str, help="Namespace of the selected pods (with --selector)")
@click.option('--scope', type=str, help="Scope of the Network Endpoint Group", default="namespace")
@click.option('--port', type=int, required=True, help="Port the endpoints listen on (1-65535)")
@click.option('--protocol', type=click.Choice(['TCP', 'UDP'], case_sensitive=False), default='TCP', show_default=True, help="Protocol of the endpoints")
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the nwepgroup key:value")
@add_options(common_options)
def create(name, infra, selector, cluster, namespace, scope, port, protocol, **kwargs):
    """Create a NWEPGROUP from VMs (--infra) or from pods matching labels (--selector)"""
    if bool(infra) == bool(selector):
        raise click.UsageError("Specify exactly one of --infra (VMs) or --selector (pod labels)")
    if selector and not (cluster and namespace):
        raise click.UsageError("--selector requires both --cluster and --namespace")
    spec_selector = {}
    for sel_item in selector:
        sel_key, sel_sep, sel_value = sel_item.partition('=')
        if not sel_sep or not sel_key:
            raise click.UsageError(f"Invalid --selector '{sel_item}', expected key=value")
        spec_selector[sel_key] = sel_value

    r = None
    try:
        spec_infra = {}
        spec = {
            "scope": scope,
            "port": port,
            "protocol": protocol.upper()
        }
        hdrs = get_hdrs()

        if selector:
            spec['selector'] = spec_selector
            spec['cluster'] = cluster
            spec['namespace'] = namespace
        else:
            r = requests.get("{}/vm?labels=vmtype:vmaas&config=False".format(sc.engine()), headers=hdrs, verify=False)
            r.raise_for_status()
            results = r.json()
            if not results['items']:
                print("No VMs found")
                return

            vmname_lookup = {}
            vmuid_lookup = {}
            for item in results['items']:
                vmname_lookup[item['metadata']['name']] = item
                vmuid_lookup[item['metadata']['uid']] = item

            for infra_item in infra:
                if infra_item in vmname_lookup:
                    item = vmname_lookup[infra_item]
                elif infra_item in vmuid_lookup:
                    item = vmuid_lookup[infra_item]
                else:
                    raise Exception(f"{infra_item} not found in VM list")
                elem_kind = item['kind']
                elem_uid = item['metadata']['uid']
                elem_name = item['metadata']['name']
                spec_infra[elem_name] = {'kind': elem_kind, 'elem_uid': elem_uid}

            spec['infra'] = spec_infra

        labels = {}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "NWEPGROUP",
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs.get('description') or name
            },
            "spec": spec
        }
        r = None
        r = requests.post(f"{sc.engine()}/nwepgroup", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
        raise
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

def nwepgroup_runwf(uid_arr, workflow, extra_payload=None):
    r = None
    hdrs = get_hdrs()
    if not uid_arr:
        raise Exception("Atleast one UID should be passed")

    data = {
        'uids': uid_arr,
        'wf_name': workflow,
    }
    url = f"{sc.engine()}/nwepgroup/wf/{workflow}"
    if len(uid_arr) == 1:
        url = f"{sc.engine()}/nwepgroup/wf/{workflow}/{uid_arr[0]}"

    if extra_payload:
        data.update(extra_payload)

    r = requests.put(url, json=data, verify=False, headers=hdrs)
    r.raise_for_status()
    handle_workspace_wfresp(",".join(uid_arr), r, hdrs)
    return r, hdrs, data
