def parse_nwlb_listener(text):
    """Parse a 'name:protocol:port' listener, e.g. web:tcp:80."""
    parts = text.split(':')
    if len(parts) != 3 or not parts[0]:
        raise ValueError(f"Invalid --listener '{text}', expected name:protocol:port")
    listener_name, protocol, port = parts
    if protocol.upper() not in ('TCP', 'UDP'):
        raise ValueError(f"Invalid --listener '{text}', protocol should be tcp or udp")
    try:
        port = int(port)
    except ValueError:
        raise ValueError(f"Invalid --listener '{text}', port should be a number")
    return {'name': listener_name, 'protocol': protocol.upper(), 'port': port}


@nwloadbalancer.command()
@click.argument("name", type=str)
@click.option('--cluster', type=str, required=True, help="Cluster name")
@click.option('--namespace', type=str, help="Namespace (default: ns-<user>)")
@click.option('--ippool', type=str, help="Loadbalancer type IPPool name")
@click.option('--ippool-uid', type=str, help="Loadbalancer type IPPool uid")
@click.option('--listener', 'listeners', type=str, multiple=True, required=True, help="Listener as name:protocol:port, e.g. web:tcp:80. Repeat for several")
@click.option('--nwepgroup', type=str, help="Endpoint group name. Required on clusters without the inframgr operator; otherwise attach endpoint groups with LBROUTE")
@click.option('--nwepgroup-uid', type=str, help="Endpoint group uid")
@click.option('--lb-mode', type=click.Choice(['auto', 'operator', 'direct']), default=None, hidden=True, help="Override the mode the cluster would pick")
@click.option("--external-traffic-policy", default=None, type=click.Choice(['Cluster', 'Local']))
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the nwloadbalancer key:value")
@click.option('--dryrun', is_flag=True, type=bool, default=False, help="Dryrun", hidden=True)
@add_options(common_options)
def create(name, cluster, namespace, ippool, ippool_uid, listeners, nwepgroup, nwepgroup_uid, lb_mode, **kwargs):
    """Create a NWLOADBALANCER"""
    if not ippool and not ippool_uid:
        raise click.UsageError("Atleast one of --ippool or --ippool-uid should be passed")
    try:
        spec_listeners = [parse_nwlb_listener(item) for item in listeners]
    except ValueError as ex:
        raise click.UsageError(str(ex))

    r = None
    try:
        spec_infra = {}

        if nwepgroup or nwepgroup_uid:
            obj = {'kind': "NWEPGROUP"}
            if nwepgroup_uid:
                obj['elem_uid'] = nwepgroup_uid
            else:
                obj['elem_name'] = nwepgroup
            spec_infra['nwepgroup'] = obj

        obj = {'kind': "IPPOOL"}
        if ippool_uid:
            obj['elem_uid'] = ippool_uid
        else:
            obj['elem_name'] = ippool
        spec_infra['ippool'] = obj

        spec = {'cluster': cluster, 'infra': spec_infra, 'listeners': spec_listeners}
        if namespace:
            spec['namespace'] = namespace
        if lb_mode:
            spec['lb_mode'] = lb_mode
        if kwargs.get('external_traffic_policy'):
            spec['external_traffic_policy'] = kwargs['external_traffic_policy']

        labels = {}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "NWLOADBALANCER",
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs.get('description') or name
            },
            "spec": spec
        }

        if kwargs.get('dryrun'):
            print(json.dumps(data, indent=4))
            return

        hdrs = get_hdrs()
        r = requests.post(f"{sc.engine()}/nwloadbalancer", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
        raise
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)


