PORTGROUP_DICT = {
    'cnpvm': [22, 111, 443, 2379, 2380, 6443, 9897, 10256, 29442, 29443, 29447, 29448, 29450, 29452, 29453, 29460, 29463, 29464, 29465, 35229, 36443],
    'linuxgui': [22, 3389, 5900],
    'linux': [22],
    'windows': [3389],
    'winvpn': [3389, 22, 80, 443, 29443, 29447, 29442, 6443, 36443]
}

def get_portgroup(portgroup):
    portlist = PORTGROUP_DICT[portgroup]
    ports = []
    for port in portlist:
        ports.append({'port': port, 'protocol': "TCP"})
    portgroup_config = {'ports': ports}
    name = portgroup
    return {
        "apiVersion": "mdcap.robin.io/v1",
 	    "kind": "PORTGROUP",
        "name": name,
 	    "metadata": {
            "name": name,
            "description": name,
            "labels": {
                "crtype": "portgroup",
                "public": "yes"
            }
        },
        "spec": portgroup_config,
    }

