@securitygroup.command()
@click.option("--range", 'index', type=str, help="Option to display a range of entries. Can be specified as a range i.e. <start_idx>:<end_idx>.")
@click.option("-l","--labels", type=str, multiple=True, help="filter search based on key value pairs.")
@click.option('-m', '--match', type=str, help="Partial filter match")
@click.option("-o", "--output", type=click.Choice(['json', 'yaml']))
@click.option("--full", is_flag=True, default=False, help="Display all columns including cluster and cluster_vpc")
@add_options(common_options)
def list(index, labels, match, output, full, **kwargs):
    """List all SECURITYGROUP elements"""
    try:
        r = None
        hdrs = get_hdrs()
        limit, offset = offset_limit_from_range(index)
        labellist = parse_labels(labels)
        query_params = [limit, offset, labellist]
        if match:
            query_params.append(f"match={match}")
        limit_url = parameter_string(query_params)
        r = requests.get("{}/securitygroup{}".format(sc.engine(), limit_url), headers=hdrs, verify=False)
        r.raise_for_status()

        if output == 'yaml':
            print(yaml.dump(r.json(), indent=4))
            return

        if output == 'json':
            print(json.dumps(r.json(), indent=4))
            return
        results = r.json()
        if not results['items']:
            print("No results found")
            return

        data = []
        headers = ["uid", "name", "type"]
        if full:
            headers += ["cluster", "cluster_vpc"]
        headers += ["policies", "description"]
        for item in results['items']:
            metadata = item['metadata']
            spec = item['spec']
            policy_types = []
            if spec.get('ingress'):
                policy_types.append('ingress')
            if spec.get('egress'):
                policy_types.append('egress')
            policies_str = ','.join(policy_types) if policy_types else '-'
            row = [metadata['uid'], metadata['name'], spec['type']]
            if full:
                row += [spec.get('cluster') or "-", spec.get('cluster_vpc') or "-"]
            row += [policies_str, metadata.get('description') or "-"]
            data.append(row)
        print(tabulate(data, headers, tablefmt="pretty"))
        footer = '\n--------------------------------------------\n'
        footer += "Displaying {}/{} elements from offset {}\n".format(results['count'], results['limit'], results['offset'])
        footer += '--------------------------------------------\n'
        print(footer)
    except Exception as ex:
        handle_error(ex, action_msg="Failed to list securitygroups. ")
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs)

