def sg_runwf(uid_arr, workflow, extra_payload=None):
    r = None
    hdrs = get_hdrs()
    if not uid_arr:
        raise Exception("Atleast one UID should be passed")

    data = {
        'uids': uid_arr,
        'wf_name': workflow,
    }
    url = f"{sc.engine()}/securitygroup/wf/{workflow}"
    if len(uid_arr) == 1:
        url = f"{sc.engine()}/securitygroup/wf/{workflow}/{uid_arr[0]}"

    if extra_payload:
        data.update(extra_payload)

    r = requests.put(url, json=data, verify=False, headers=hdrs)
    r.raise_for_status()
    _handle_sg_wfresp(",".join(uid_arr), r, hdrs)
    return r, hdrs, data

def _handle_sg_wfresp(uid, r, hdrs):
    uid_arr = []
    resp = r.json()
    wf_tracker = resp.get('wf_tracker')
    if uid:
        uid_arr = uid.split(',')
    else:
        uid_arr = resp['uid'].split(',')

    if wf_tracker:
        url = "{}/batch/bow/{}".format(sc.engine(), wf_tracker)
        res = requests.get(url, verify=False, headers=hdrs)
        res.raise_for_status()
        r1 = res.json()
        print()
        for batchid in r1.get('batches', []):
            print(f"{PROGRAM_NAME} batch info-bow {wf_tracker}")
            print(f"{PROGRAM_NAME} batch info {batchid}")
            for uid in uid_arr:
                print(f"{PROGRAM_NAME} batch logs {batchid} -e {uid}")
            print()
    else:
        print(resp.get('msg', ""))
