@click.option('--s3-bucket', type=str, help="S3 Bucket name [required for s3 type]")
@click.option('--s3-folder', type=str, help="S3 Bucket folder path [required for s3 type]")
@click.option('--s3-access-key', type=str, help="S3 Access key [required for s3 type]")
@click.option('--s3-secret-key', type=str, help="S3 Secret key [required for s3 type]")
@click.option('--region', type=str, help="S3 bucket region", required=True)
@click.option('--tls-enabled', is_flag=True, help="TLS enabled", default=False)
@click.option('--tls-verify', is_flag=True, help="TLS verify cert", default=False)
@click.option('--dryrun', help="Dryrun", default=None, type=click.Choice(['client', 'server']))
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the storagerepo key:value")
@add_options(common_options)
def create(name, type, endpoint, **kwargs):
    """Create a STORAGEREPO"""
    spec = {
        "type": type,
        "endpoint": endpoint,
        "tls_enabled": kwargs['tls_enabled'],
        "tls_verify": kwargs['tls_verify']
    }
    if kwargs.get('web_url'):
        spec['web_url'] = kwargs['web_url']
    labels = {'crtype': "storagerepo", 'type': type}
    for item in kwargs.get('labels', []):
        _arr = item.split(':')
        labels[_arr[0]] = _arr[1]

    if type == "s3":
        for key in ["s3_bucket", "s3_folder", "s3_access_key", "s3_secret_key"]:
            if not kwargs.get(key):
                handle_error(Exception(f"Key {key} is required for {type} repo"))
            spec[key] = kwargs[key]

    if kwargs.get('region',''):
        spec['region'] = kwargs['region']

    data = {
        "apiVersion": "mdcap.robin.io/v1",
 	    "kind": "STORAGEREPO",
 	    "metadata": {
            "name": name,
            "labels": labels
        },
        "spec": spec
    }
    if kwargs.get('dryrun', "") == "client":
        print(json.dumps(data, indent=4))
        return
    try:
        r = None
        hdrs = get_hdrs()
        r = requests.post(f"{sc.engine()}/storagerepo", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)
