def vmmigration():
    """VMMIGRATION Management"""
    pass

@vmmigration.command(aliases=['register'])
@click.option("-C", "--config", type=click.File("r"), required=False,
              help="Path to JSON config file")
@click.option("--name", type=str, required=False, help="Name of the spec")
@click.option("--target-endpoint", type=str, required=False, help="Target endpoint")
@click.option("--source-endpoint", type=str, required=False, help="Source endpoint")
@click.option("--flavor", type=str, required=False, help="target flavour")
@click.option("--instance", type=str, required=False, multiple=True,
              help="Instance name, can pass multiple times")
@click.option("--network", type=str, required=False, default="default", help="Network name : default 'pod network'")
@add_options(common_options)
def register(uid, config, name, target_endpoint, source_endpoint, instance, network, flavor, **kwargs):
    """Register a RMIGRATEvmspec element"""
    import pdb; pdb.set_trace()
    if config is None and not all([name, target_endpoint, source_endpoint, instance, network]):
        click.echo("Error: Must provide either a config file (-C) or all mandatory parameters (--name, --target-endpoint, --source-endpoint, --instance, --network).", err=True)
        raise click.UsageError("Missing required input")
    try:
        r = None
        hdrs = get_hdrs()
        uid = uid if uid else "-1"
        if config:
            data = json.load(config)
        else:
            #vm_instances_list = [instance]
            # Build payload from mandatory parameters
            if network == "default":
                network = 'pod network'
            data = {
                    "metadata" : {
                        "name":name
                        },
                    "spec": {
                "destination_endpoint_name": target_endpoint,
                "source_endpoint_name": source_endpoint,
                "vm_instances": instance,
                "network_map": {
                    "VM Network": network
                    },

                    "flavor": flavor
                }
            }
        r = requests.put(f"{sc.engine()}/rmigrate/{uid}/migrate", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)


