@volume.command()
@click.argument("name", type=str)
@click.option('--cluster', type=str, help="Cluster", required=True)
@click.option('--cluster-kind', type=str, help="Cluster Kind")
@click.option('--size', type=int, help="Size in Gi", required=True)
@click.option('--storage-class', type=str, help="Storage class", required=True)
@click.option('--namespace', type=str, help="select namespace", default=None)
@click.option("--access-mode", type=click.Choice(['rwx', 'rwo']), default='rwo')
@click.option('--fstype', type=click.Choice(['ext4', 'xfs']), help="Filesystem Type when mode is Filesystem")
@click.option("--volume-mode", type=click.Choice(['Block', 'Filesystem']), default='Filesystem')
@click.option("--guest-attachment-type", type=click.Choice(['disk', 'filesystem']), default=None)
@click.option("--shared", is_flag=True, type=bool, default=False, help="Create a shareable volume with other users")
@click.option("--nfs-server", is_flag=True, type=bool, default=False, help="For shareable volume, explicitly deploy NFS server POD in namespace if the storage-class doesn't support NFS")
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the volume key:value")
@add_options(common_options)
def create(name, cluster, **kwargs):
    """Create a VOLUME"""
    try:
        spec = {
            "cluster": cluster,
            "size": f"{kwargs['size']}Gi",
            "access_mode": kwargs['access_mode'],
            "volume_mode": kwargs['volume_mode'],
            "storage_class": kwargs['storage_class']
        }

        if kwargs.get('cluster_kind'):
            spec['cluster_kind'] = kwargs['cluster_kind']

        if kwargs.get('namespace'):
            spec['namespace'] = kwargs['namespace']

        if kwargs.get('fstype'):
            spec['fstype'] = kwargs['fstype']
        if kwargs.get('guest_attachment_type'):
            spec['guest_attachment_type'] = kwargs['guest_attachment_type']
        if kwargs.get('shared'):
            spec['shared'] = True
            if kwargs.get('nfs_server'):
                spec['nfs_server'] = True

        labels = {'crtype': "volume"}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "VOLUME",
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs.get('description') or name
            },
            "spec": spec
        }
        r = None
        hdrs = get_hdrs()
        r = requests.post(f"{sc.engine()}/volume", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
        raise
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

