@workspace.command()
@click.argument("name", type=str)
@click.option('--image', type=str, help="WORKSPACE Image", required=True)
@click.option('--vmconfig', type=click.File('r'),  help="VM create config file", required=True)
@click.option('--volume', type=str, multiple=True, help="User volumes to attach", required=True)
@click.option('-l', '--labels', type=str, multiple=True, help="Add labels to the workspace key:value")
@click.option('--dryrun', type=str, default="", help="Dryrun", hidden=True)
@add_options(common_options)
def create(name, image, vmconfig, volume, **kwargs):
    """Create a WORKSPACE"""
    try:
        infra = {}
        spec = {}
        vmdata = json.load(vmconfig)
        hdrs = get_hdrs()

        vmdata['kind'] = "VM"
        infra['vm'] = vmdata
        vmdata['spec']['image'] = image
        infra['image'] = {'kind': "IMAGE", 'elem_name': image}

        for volname in volume:
            infra[volname] = {'kind': "VOLUME", 'elem_name': volname}

        spec['infra'] = infra

        labels = {}
        for item in kwargs.get('labels', []):
            _arr = item.split(':')
            labels[_arr[0]] = _arr[1]

        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "WORKSPACE",
            "metadata": {
                "name": name,
                "labels": labels,
                "description": kwargs.get('description') or name
            },
            "spec": spec
        }

        if kwargs.get('dryrun') and kwargs['dryrun'] == "client":
            print(json.dumps(data, indent=4))
            return

        r = None
        r = requests.post(f"{sc.engine()}/workspace", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
        raise
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)
