@appvalues.command(aliases=['register'])
@click.argument('name', type=str)
@add_options(helm_app_options)
@click.option('--description', type=str, default='', help='Description')
@click.option('--label', 'labels', type=str, multiple=True, metavar='KEY:VALUE', help='Labels (repeatable)')
@click.option('--version', type=str, default='1', help='Metadata version', hidden=True)
@click.option('--flavor', type=str, default='default', help='Metadata flavor', hidden=True)
@add_options(common_options)
def add(name, description, labels, version, flavor,
        repo, chart, chart_version, cluster, namespace, storage_class, values,
        primary_network, secondary_networks, robinrpool, cluster_admin_privileges, set_options, **kwargs):
    """Register an APPVALUES element"""
    try:
        r = None
        hdrs = get_hdrs()

        values_dict = {}
        if values:
            with open(values, 'r', encoding='utf-8') as fh:
                values_dict = yaml.safe_load(fh) or {}

        labels_dict = {}
        for label in labels:
            if ':' not in label:
                raise Exception(f"Label '{label}' must be in KEY:VALUE format")
            k, v = label.split(':', 1)
            labels_dict[k.strip()] = v.strip()

        spec = build_helm_app_spec(repo, chart, chart_version, cluster, namespace, storage_class,
                                   values_dict, cluster_admin_privileges=cluster_admin_privileges,
                                   primary_network=primary_network, secondary_networks=secondary_networks,
                                   set_options=set_options, robinrpool=robinrpool)

        data = {
            'kind': 'APPVALUES',
            'apiVersion': 'mdcap.robin.io/v1',
            'metadata': {
                'name': name,
                'description': description,
                'labels': labels_dict,
                'version': version,
                'flavor': flavor,
            },
            'spec': spec,
        }

        r = requests.post(f"{sc.engine()}/appvalues", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        print(r.json()['msg'])
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

