def parse_bgp_setting(value):
    setting = {}
    peer_setting = {}
    for pair in value.split(','):
        key, sep, val = pair.partition('=')
        key, val = key.strip(), val.strip()
        if not sep or not val:
            raise click.BadParameter(f"'{pair}' should be key=value", param_hint='--bgp-setting')
        if key == 'bgp_config_name':
            setting[key] = val
        elif key == 'advertisement_ippool':
            setting[key] = [{"ippool_name": n.strip()} for n in val.split('|') if n.strip()]
        elif key in ('peer_address', 'hold_time', 'keep_alive_time'):
            peer_setting[key] = val
        elif key == 'peer_asn':
            try:
                peer_setting[key] = int(val)
            except ValueError:
                raise click.BadParameter(f"{key} should be an integer", param_hint='--bgp-setting')
        else:
            raise click.BadParameter(f"unsupported key '{key}'", param_hint='--bgp-setting')
    setting['peer_setting'] = peer_setting
    return setting

