@vpcnatgateway.command()
@click.argument('name', type=str)
@click.option('--vpc-name', type=str, help="VPC name", required=True)
@click.option('--external-ippool-name', type=str, help="Elastic type IP pool name", required=True)
@click.option('--replica', type=int, help="Number of replicas", default=1)
@click.option('--snat-ippool', 'snat_ippools', type=str, multiple=True,
              help="Comma separated IPPOOL names of the VPC whose traffic is SNATed. Can be repeated. e.g. pool1,pool2. More can be added later with add-ippool")
@add_options(common_options)
def create(name, vpc_name, external_ippool_name, snat_ippools, **kwargs):
    """Create a VPCNATGATEWAY element"""
    try:
        r = None
        hdrs = get_hdrs()
        ippool_names = [n.strip() for value in snat_ippools for n in value.split(',') if n.strip()]
        data = {
            "apiVersion": "mdcap.robin.io/v1",
            "kind": "VPCNATGATEWAY",
            "metadata": {
                "name": name
            },
            "spec": {
                "vpc_name": vpc_name,
                "external_ippool_name": external_ippool_name,
                "snat": [{"ippool_name": n} for n in ippool_names]
            }
        }
        for key in ["replica"]:
            if key in kwargs:
                data['spec'][key] = kwargs[key]

        r = requests.post(f"{sc.engine()}/vpcnatgateway", json=data, verify=False, headers=hdrs)
        r.raise_for_status()
        result = r.json()
        print(result['msg'])
        if result.get('wf_tracker'):
            print(f"Workflow tracker: {result['wf_tracker']}")
    except Exception as ex:
        handle_error(ex)
    finally:
        if kwargs.get('urlinfo') and r:
            compute_curl_command(r, headers=hdrs, data=data)

